/**
 * The side panel (spec §8, §11; mock-ups 09, 15, 24, 25): Subtitles — the
 * master switch, a card per track with its timing, "I just heard this line"
 * and its style — and Transcript. It pushes the picture aside instead of
 * covering it, opens on the left in a right-to-left interface, and is an
 * overlay with a scrim in a small window.
 */
import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent,
} from 'react';
import { plural, t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import type { PlayerController } from '../controller.js';
import { activeIndices, isRtlText } from '../model/cues.js';
import { LANGUAGES as LANGS, languageName, usesArabicScript } from '../model/languages.js';
import { MAX_SCALE, MIN_SCALE, placeTo, type SlotLayout } from '../model/layout.js';
import type { Edge, FontChoice, SlotStyle } from '../model/prefs.js';
import type { SlotNumber } from '../model/slots.js';
import { clock, offsetLabel } from '../model/time.js';
import { slotVisible, trackIn, updatePrefs, usePlayer, type TrackState } from '../store.js';
import { PIcon } from './icons.js';
import { IconButton, Kbd, Popover, Row, Switch } from './kit.js';
import { resolvedFont, trackColourVar } from './subtitleStyle.js';
import styles from './Panel.module.css';

interface Props {
  controller: PlayerController;
  onSelectText: (text: string, sentence: string, at: number, lang: string | undefined, rect: DOMRect) => void;
  notebookWords: ReadonlySet<string> | null;
  onToggleNotebookWords: () => void;
}

export function SidePanel({
  controller,
  onSelectText,
  notebookWords,
  onToggleNotebookWords,
}: Props): React.JSX.Element | null {
  const panel = usePlayer((s) => s.panel);
  const small = usePlayer((s) => s.small);
  if (panel === null) return null;
  const close = (): void => {
    usePlayer.setState({ panel: null });
  };
  return (
    <>
      {small ? <div className={styles.scrim} onClick={close} aria-hidden="true" /> : null}
      <aside
        className={cx(styles.panel, small && styles.overlay)}
        aria-label={t('player.panel.label')}
        data-player-overlay=""
      >
        <div className={styles.head}>
          <div className={styles.segc} role="tablist" aria-label={t('player.panel.label')}>
            <button
              type="button"
              role="tab"
              aria-selected={panel === 'subtitles'}
              className={cx(styles.segb, panel === 'subtitles' && styles.segOn)}
              onClick={() => {
                usePlayer.setState({ panel: 'subtitles', panelTab: 'subtitles' });
              }}
            >
              {t('player.panel.subtitles')}
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={panel === 'transcript'}
              className={cx(styles.segb, panel === 'transcript' && styles.segOn)}
              onClick={() => {
                usePlayer.setState({ panel: 'transcript', panelTab: 'transcript' });
              }}
            >
              {t('player.panel.transcript')}
            </button>
          </div>
          <IconButton icon="x" label={t('player.panel.close')} small onClick={close} tipSide="down" />
        </div>
        {panel === 'subtitles' ? (
          <SubtitlesTab controller={controller} />
        ) : (
          <Transcript
            controller={controller}
            onSelectText={onSelectText}
            notebookWords={notebookWords}
            onToggleNotebookWords={onToggleNotebookWords}
          />
        )}
      </aside>
    </>
  );
}

/* ================================================================ Subtitles */

function SubtitlesTab({ controller }: { controller: PlayerController }): React.JSX.Element {
  const master = usePlayer((s) => s.master);
  const slots = usePlayer((s) => s.slots);
  const off = usePlayer((s) => s.off);
  const count = slots.filter((x) => x !== null).length;
  const [open, setOpen] = useState<SlotNumber | null>(null);
  const firstFree = ([1, 2, 3] as const).find((n) => slots[n - 1] === null);
  return (
    <>
      <div className={styles.body}>
        <div className={styles.master}>
          <div className={styles.masterText}>
            <b>{t('player.subs.show')}</b>
            <small>
              {plural(count, 'player.panel.tracksOne', 'player.panel.tracks', { count })} · <Kbd>C</Kbd>{' '}
              {t('player.panel.hidesAll')}
            </small>
          </div>
          <Switch
            checked={master}
            label={t('player.subs.show')}
            onChange={(on) => {
              controller.setMaster(on);
            }}
          />
        </div>
        {([1, 2, 3] as const).map((n) => {
          const id = slots[n - 1];
          if (id === null || id === undefined) return null;
          return (
            <TrackCard
              key={id}
              slot={n}
              controller={controller}
              open={open === n}
              onToggleStyle={() => {
                setOpen((o) => (o === n ? null : n));
              }}
            />
          );
        })}
        {off.map((id) => (
          <OffCard key={id} id={id} controller={controller} />
        ))}
        {firstFree !== undefined ? (
          <button
            type="button"
            className={styles.addslot}
            onClick={() => {
              void controller.pick();
            }}
          >
            <PIcon name="plus" size={20} />
            {count === 0
              ? t('player.panel.addFirst')
              : count === 1
                ? t('player.panel.addSecond')
                : t('player.panel.addThird')}
          </button>
        ) : null}
      </div>
      <div className={styles.foot}>
        <button
          type="button"
          className={styles.footAdd}
          onClick={() => {
            void controller.pick();
          }}
        >
          <PIcon name="plus" size={16} />
          {t('player.panel.addFile')}
        </button>
        <button
          type="button"
          className={styles.footReset}
          onClick={() => {
            updatePrefs((p) => ({
              ...p,
              layouts: { 1: resetLayout(1), 2: resetLayout(2), 3: resetLayout(3) },
            }));
            controller.notice({ text: t('player.notice.layoutReset'), icon: 'check' });
          }}
        >
          {t('player.panel.resetLayout')}
        </button>
      </div>
    </>
  );
}

function resetLayout(slot: SlotNumber): SlotLayout {
  return placeTo(
    { mode: 'bottom', anchor: 'bottom', x: 0.5, y: 0, width: 0.8, scale: 1 },
    slot === 2 ? 'top' : 'bottom',
  );
}

function placeName(slot: SlotNumber, layout: SlotLayout): string {
  if (layout.mode === 'custom') return t('player.place.custom');
  if (slot === 3 && layout.mode === 'bottom') return t('player.place.above1');
  return layout.anchor === 'top' ? t('player.place.top') : t('player.place.bottom');
}

interface CardProps {
  slot: SlotNumber;
  controller: PlayerController;
  open: boolean;
  onToggleStyle: () => void;
}

function TrackCard({ slot, controller, open, onToggleStyle }: CardProps): React.JSX.Element | null {
  const track = usePlayer((s) => trackIn(s, slot));
  const visible = usePlayer((s) => slotVisible(s, slot));
  const shown = usePlayer((s) => s.shown[slot - 1] === true);
  const style = usePlayer((s) => s.prefs.styles[slot]);
  const layout = usePlayer((s) => s.prefs.layouts[slot]);
  const [more, setMore] = useState(false);
  const [typing, setTyping] = useState(false);
  const [moreEl, moreRef] = useState<HTMLButtonElement | null>(null);
  const dragY = useRef<number | null>(null);
  if (track === undefined) return null;
  const rtl = usesArabicScript(track.lang) || track.lang === 'he';
  const offset = track.offsetMs;
  const set = (ms: number): void => {
    controller.setOffset(slot, ms);
  };
  const where = placeName(slot, layout).toLowerCase();
  const reorderKey = (e: ReactKeyboardEvent<HTMLButtonElement>): void => {
    if (e.key === 'ArrowUp' && slot > 1) {
      e.preventDefault();
      controller.reorder(slot, (slot - 1) as SlotNumber);
    } else if (e.key === 'ArrowDown' && slot < 3) {
      e.preventDefault();
      controller.reorder(slot, (slot + 1) as SlotNumber);
    }
  };
  const onDragDown = (e: PointerEvent<HTMLButtonElement>): void => {
    e.currentTarget.setPointerCapture(e.pointerId);
    dragY.current = e.clientY;
  };
  const onDragUp = (e: PointerEvent<HTMLButtonElement>): void => {
    const y0 = dragY.current;
    dragY.current = null;
    if (y0 === null) return;
    const dy = e.clientY - y0;
    if (dy < -60 && slot > 1) controller.reorder(slot, (slot - 1) as SlotNumber);
    else if (dy > 60 && slot < 3) controller.reorder(slot, (slot + 1) as SlotNumber);
  };
  return (
    <div className={cx(styles.tcard, open && styles.tcardOpen, !visible && styles.tcardOff)}>
      <div className={styles.top}>
        <button
          type="button"
          className={styles.grab}
          aria-label={t('player.panel.reorder', { n: slot })}
          onKeyDown={reorderKey}
          onPointerDown={onDragDown}
          onPointerUp={onDragUp}
        >
          <PIcon name="dots" size={16} />
        </button>
        <span className={styles.num} style={{ background: trackColourVar(style.colour) }}>
          {slot}
        </span>
        <LanguageButton track={track} slot={slot} rtl={rtl} />
        <span className={styles.where}>· {where}</span>
        {track.picture ? <span className={styles.picture}>{t('player.subs.picture')}</span> : null}
        <span className={styles.topEnd}>
          <IconButton
            icon={shown ? 'eye' : 'eyeOff'}
            label={t('player.subs.eye', { n: slot })}
            small
            pressed={!shown}
            onClick={() => {
              controller.toggleSlot(slot);
            }}
          />
          <span className={styles.anchor}>
            <IconButton
              icon="more"
              label={t('player.panel.more', { n: slot })}
              small
              buttonRef={moreRef}
              menu={{ expanded: more }}
              onClick={() => {
                setMore((m) => !m);
              }}
            />
            {more ? (
              <Popover
                label={t('player.panel.more', { n: slot })}
                onClose={() => {
                  setMore(false);
                }}
                anchor={moreEl}
                className={styles.moreMenu}
              >
                <Row
                  onClick={() => {
                    setMore(false);
                    void controller.pick();
                  }}
                >
                  {t('player.panel.replace')}
                </Row>
                <Row
                  onClick={() => {
                    setMore(false);
                    controller.removeTrack(track.id);
                  }}
                >
                  {t('player.panel.remove')}
                </Row>
              </Popover>
            ) : null}
          </span>
        </span>
      </div>
      <div className={styles.src}>
        <PIcon name={track.source.kind === 'embedded' ? 'film' : 'file'} size={14} />
        <span className={styles.ellip}>
          {track.picture
            ? t('player.subs.pictureLine')
            : track.source.kind === 'embedded'
              ? t('player.panel.embeddedSource', {
                  n: (track.source.stream ?? 0) + 1,
                  codec: track.source.codec ?? '',
                })
              : track.source.name}
          {track.textFixed && !track.picture ? (
            <>
              {' · '}
              <span className={styles.fix}>{t('player.subs.textFixed')}</span>
            </>
          ) : null}
        </span>
      </div>
      <div className={styles.ctl} dir="ltr">
        <span className={styles.lbl}>{t('player.panel.timing')}</span>
        <button
          type="button"
          className={styles.step}
          aria-label={t('player.panel.earlier', { n: slot, amount: '0.5 s' })}
          onClick={() => {
            set(offset - 500);
          }}
        >
          −0.5
        </button>
        <button
          type="button"
          className={styles.step}
          aria-label={t('player.panel.earlier', { n: slot, amount: '0.1 s' })}
          onClick={() => {
            set(offset - 100);
          }}
        >
          −0.1
        </button>
        {typing ? (
          <input
            className={styles.ovalInput}
            aria-label={t('player.panel.typeOffset', { n: slot })}
            defaultValue={(offset / 1000).toFixed(1)}
            inputMode="decimal"
            autoFocus
            onBlur={(e) => {
              const v = Number(e.target.value.replace(',', '.').replace('−', '-'));
              if (Number.isFinite(v)) set(Math.round(v * 1000));
              setTyping(false);
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
              if (e.key === 'Escape') setTyping(false);
              e.stopPropagation();
            }}
          />
        ) : (
          <button
            type="button"
            className={cx(styles.oval, Math.round(offset / 100) === 0 && styles.zero)}
            onClick={() => {
              setTyping(true);
            }}
            onDoubleClick={() => {
              set(0);
            }}
          >
            {offsetLabel(offset)}
          </button>
        )}
        <button
          type="button"
          className={styles.step}
          aria-label={t('player.panel.later', { n: slot, amount: '0.1 s' })}
          onClick={() => {
            set(offset + 100);
          }}
        >
          +0.1
        </button>
        <button
          type="button"
          className={styles.step}
          aria-label={t('player.panel.later', { n: slot, amount: '0.5 s' })}
          onClick={() => {
            set(offset + 500);
          }}
        >
          +0.5
        </button>
      </div>
      <button
        type="button"
        className={styles.heard}
        onClick={() => {
          controller.openSync(slot);
        }}
      >
        <PIcon name="audio" size={16} />
        {t('player.panel.heard')}
        <Kbd className={styles.heardKey}>H</Kbd>
      </button>
      {!track.picture ? (
        open ? (
          <StyleGrid slot={slot} style={style} layout={layout} lang={track.lang} onClose={onToggleStyle} />
        ) : (
          <button type="button" className={styles.stylebtn} onClick={onToggleStyle} aria-expanded={false}>
            <span className={styles.swatch} style={{ color: trackColourVar(style.colour) }}>
              Aa
            </span>
            {t('player.panel.style')}
            <span className={styles.styleSummary}>
              {t('player.style.summary', {
                font: t(`player.font.${resolvedFont(style.font, track.lang)}` as 'player.font.sans'),
                size: Math.round(layout.scale * (slot === 2 ? 86 : slot === 3 ? 80 : 100)),
                edge: t(
                  `player.panel.edge${style.edge[0]?.toUpperCase() ?? ''}${style.edge.slice(1)}` as 'player.panel.edgeOutline',
                ).toLowerCase(),
              })}
            </span>
            <PIcon name="cd" size={16} />
          </button>
        )
      ) : null}
    </div>
  );
}

function LanguageButton({
  track,
  slot,
  rtl,
}: {
  track: TrackState;
  slot: SlotNumber;
  rtl: boolean;
}): React.JSX.Element {
  return (
    <label className={styles.langWrap}>
      <span className={cx(styles.name, rtl && styles.fa)} dir={rtl ? 'rtl' : undefined}>
        {track.lang === 'fa' ? 'فارسی' : languageName(track.lang)}
      </span>
      <select
        className={styles.langSelect}
        aria-label={t('player.panel.language', { n: slot })}
        value={track.lang ?? ''}
        onChange={(e) => {
          const code = e.target.value;
          usePlayer.setState((s) => ({
            tracks: { ...s.tracks, [track.id]: { ...track, lang: code, langConfidence: 1 } },
          }));
        }}
      >
        <LanguageOptions current={track.lang} />
      </select>
    </label>
  );
}

function LanguageOptions({ current }: { current: string | undefined }): React.JSX.Element {
  return (
    <>
      {current === undefined || current === '' ? <option value="">?</option> : null}
      {LANGS.map((l) => (
        <option key={l.code} value={l.code}>
          {l.autonym === l.name ? l.name : `${l.autonym} ${l.name}`}
        </option>
      ))}
    </>
  );
}

function OffCard({ id, controller }: { id: string; controller: PlayerController }): React.JSX.Element | null {
  const track = usePlayer((s) => s.tracks[id]);
  const slots = usePlayer((s) => s.slots);
  if (track === undefined) return null;
  const free = ([1, 2, 3] as const).find((n) => slots[n - 1] === null);
  return (
    <div className={cx(styles.tcard, styles.tcardOff)}>
      <div className={styles.top}>
        <span className={cx(styles.num, styles.numOff)}>–</span>
        <span className={styles.name}>{languageName(track.lang)}</span>
        <span className={styles.where}>· {t('player.panel.offEmpty').toLowerCase()}</span>
        <span className={styles.topEnd}>
          <button
            type="button"
            className={styles.use}
            onClick={() => {
              controller.put(id, free ?? 3);
            }}
          >
            {t('player.subs.use')}
          </button>
        </span>
      </div>
      <div className={styles.src}>
        <PIcon name="file" size={14} />
        <span className={styles.ellip}>{track.source.name}</span>
      </div>
    </div>
  );
}

const FONTS: FontChoice[] = ['sans', 'vazirmatn', 'naskh', 'atkinson', 'serif', 'system'];
const EDGES: Edge[] = ['none', 'outline', 'shadow', 'box'];
const COLOURS = ['white', 'yellow', 'sky', 'mint'] as const;

function StyleGrid({
  slot,
  style,
  layout,
  lang,
  onClose,
}: {
  slot: SlotNumber;
  style: SlotStyle;
  layout: SlotLayout;
  lang: string | undefined;
  onClose: () => void;
}): React.JSX.Element {
  const setStyle = (change: Partial<SlotStyle>): void => {
    updatePrefs((p) => ({ ...p, styles: { ...p.styles, [slot]: { ...p.styles[slot], ...change } } }));
  };
  const setLayout = (l: SlotLayout): void => {
    updatePrefs((p) => ({ ...p, layouts: { ...p.layouts, [slot]: l } }));
  };
  const font = resolvedFont(style.font, lang);
  const sizePct = Math.round(layout.scale * (slot === 2 ? 86 : slot === 3 ? 80 : 100));
  const custom = !COLOURS.includes(style.colour as (typeof COLOURS)[number]);
  return (
    <div className={styles.styleGrid}>
      <button type="button" className={styles.styleHead} onClick={onClose} aria-expanded>
        <span className={styles.swatch} style={{ color: trackColourVar(style.colour) }}>
          Aa
        </span>
        {t('player.panel.style')}
        <PIcon name="cu" size={16} className={styles.styleHeadIcon} />
      </button>
      <span className={styles.lbl}>{t('player.panel.font')}</span>
      <label className={styles.selectWrap}>
        <select
          className={styles.select}
          value={font}
          onChange={(e) => {
            setStyle({ font: e.target.value as FontChoice });
          }}
        >
          {FONTS.map((f) => (
            <option key={f} value={f}>
              {t(`player.font.${f}` as 'player.font.sans')}
            </option>
          ))}
        </select>
        {font === 'vazirmatn' && usesArabicScript(lang) ? (
          <span className={styles.forLang}>
            {lang === 'fa' ? t('player.panel.forPersian') : t('player.panel.forArabicScript')}
          </span>
        ) : null}
        <PIcon name="cd" size={15} className={styles.chev} />
      </label>
      <span className={styles.lbl}>{t('player.panel.size')}</span>
      <div className={styles.rowline}>
        <input
          type="range"
          className={styles.range}
          min={MIN_SCALE * 100}
          max={MAX_SCALE * 100}
          step={5}
          value={Math.round(layout.scale * 100)}
          aria-label={t('player.panel.size')}
          aria-valuetext={`${String(sizePct)}%`}
          onChange={(e) => {
            setLayout({ ...layout, scale: Number(e.target.value) / 100 });
          }}
          style={{
            ['--f' as string]: `${String(((layout.scale - MIN_SCALE) / (MAX_SCALE - MIN_SCALE)) * 100)}%`,
          }}
        />
        <span className={styles.val}>{sizePct}%</span>
      </div>
      <span className={styles.lbl}>{t('player.panel.colour')}</span>
      <div className={styles.swRow} role="radiogroup" aria-label={t('player.panel.colour')}>
        {COLOURS.map((c) => (
          <button
            key={c}
            type="button"
            role="radio"
            aria-checked={style.colour === c}
            aria-label={t(`player.colour.${c}`)}
            className={cx(styles.sw, style.colour === c && styles.swOn)}
            style={{ background: trackColourVar(c) }}
            onClick={() => {
              setStyle({ colour: c });
            }}
          />
        ))}
        <label
          className={cx(styles.sw, styles.swCustom, custom && styles.swOn)}
          aria-label={t('player.panel.custom')}
        >
          <input
            type="color"
            className={styles.colourInput}
            value={custom ? style.colour : '#ffffff'}
            onChange={(e) => {
              setStyle({ colour: e.target.value as `#${string}` });
            }}
          />
        </label>
      </div>
      <span className={styles.lbl}>{t('player.panel.edge')}</span>
      <div className={styles.segs} role="radiogroup" aria-label={t('player.panel.edge')}>
        {EDGES.map((e) => (
          <button
            key={e}
            type="button"
            role="radio"
            aria-checked={style.edge === e}
            className={cx(styles.segsb, style.edge === e && styles.segsOn)}
            onClick={() => {
              setStyle({ edge: e });
            }}
          >
            {t(`player.panel.edge${e[0]?.toUpperCase() ?? ''}${e.slice(1)}` as 'player.panel.edgeNone')}
          </button>
        ))}
      </div>
      <span className={styles.lbl}>{t('player.panel.opacity')}</span>
      <div className={styles.rowline}>
        <input
          type="range"
          className={styles.range}
          min={50}
          max={100}
          step={5}
          value={Math.round(style.opacity * 100)}
          aria-label={t('player.panel.opacity')}
          onChange={(e) => {
            setStyle({ opacity: Number(e.target.value) / 100 });
          }}
          style={{ ['--f' as string]: `${String(((style.opacity - 0.5) / 0.5) * 100)}%` }}
        />
        <span className={styles.val}>{Math.round(style.opacity * 100)}%</span>
      </div>
      {style.edge === 'box' ? (
        <>
          <span className={styles.lbl}>{t('player.panel.boxOpacity')}</span>
          <div className={styles.rowline}>
            <input
              type="range"
              className={styles.range}
              min={0}
              max={100}
              step={5}
              value={Math.round(style.boxOpacity * 100)}
              aria-label={t('player.panel.boxOpacity')}
              onChange={(e) => {
                setStyle({ boxOpacity: Number(e.target.value) / 100 });
              }}
              style={{ ['--f' as string]: `${String(style.boxOpacity * 100)}%` }}
            />
            <span className={styles.val}>{Math.round(style.boxOpacity * 100)}%</span>
          </div>
        </>
      ) : null}
      <span className={styles.lbl}>{t('player.place.title')}</span>
      <div className={styles.segs} role="radiogroup" aria-label={t('player.place.title')}>
        {(['bottom', 'top', 'custom'] as const).map((p) => {
          const on = layout.mode === p;
          return (
            <button
              key={p}
              type="button"
              role="radio"
              aria-checked={on}
              disabled={p === 'custom' && layout.mode !== 'custom'}
              className={cx(styles.segsb, on && styles.segsOn)}
              onClick={() => {
                if (p !== 'custom') setLayout(placeTo(layout, p));
              }}
            >
              {t(`player.place.${p}`)}
            </button>
          );
        })}
      </div>
    </div>
  );
}

/* ================================================================ Transcript */

interface TranscriptProps {
  controller: PlayerController;
  onSelectText: Props['onSelectText'];
  notebookWords: ReadonlySet<string> | null;
  onToggleNotebookWords: () => void;
}

/** The two passes "past lines are quiet" leaves undimmed before the current one, as the mock-up draws them. */
const CONTEXT_BEFORE = 2;
/** A click on a line seeks this far before its start (§11). */
const JUMP_LEAD_S = 0.3;

function Transcript({
  controller,
  onSelectText,
  notebookWords,
  onToggleNotebookWords,
}: TranscriptProps): React.JSX.Element {
  const learning = usePlayer((s) => trackIn(s, 1));
  const second = usePlayer((s) => trackIn(s, 2));
  const markOn = usePlayer((s) => s.prefs.settings.markNotebook);
  const [both, setBoth] = useState(true);
  const [follow, setFollow] = useState(true);
  const [current, setCurrent] = useState(-1);
  const [query, setQuery] = useState('');
  const [hit, setHit] = useState(0);
  const listRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const programmatic = useRef(false);

  useEffect(() => {
    if (learning === undefined) return;
    return controller.onTick((time) => {
      const idx = activeIndices(learning.cues, time * 1000, learning.offsetMs);
      const i = idx[idx.length - 1];
      if (i !== undefined) setCurrent(i);
    });
  }, [controller, learning]);

  // ⌘F / Ctrl+F focuses the search (§11).
  useEffect(() => {
    const focus = (): void => {
      searchRef.current?.focus();
    };
    window.addEventListener('player:search', focus);
    return () => {
      window.removeEventListener('player:search', focus);
    };
  }, []);

  const hits = useMemo(() => {
    if (learning === undefined || query.trim() === '') return [];
    const q = query.trim().toLocaleLowerCase();
    return learning.cues.flatMap((c, i) => (c.text.toLocaleLowerCase().includes(q) ? [i] : []));
  }, [learning, query]);

  // Follow: the current line stays in view until the learner scrolls.
  useEffect(() => {
    if (!follow || current < 0) return;
    const el = listRef.current?.querySelector<HTMLElement>(`[data-line="${String(current)}"]`);
    if (el === null || el === undefined) return;
    programmatic.current = true;
    el.scrollIntoView({ block: 'center', behavior: 'smooth' });
    window.setTimeout(() => {
      programmatic.current = false;
    }, 600);
  }, [current, follow]);

  // A search result is brought into view (Follow pauses where the hit is set).
  useEffect(() => {
    const at = hits[hit];
    if (at === undefined) return;
    listRef.current
      ?.querySelector<HTMLElement>(`[data-line="${String(at)}"]`)
      ?.scrollIntoView({ block: 'center' });
  }, [hit, hits]);
  const goHit = (step: number): void => {
    setFollow(false);
    setHit((h) => (hits.length === 0 ? 0 : (h + step + hits.length) % hits.length));
  };

  if (learning === undefined) {
    return <p className={styles.trEmpty}>{t('player.tr.empty')}</p>;
  }
  if (learning.picture) return <p className={styles.trEmpty}>{t('player.tr.picture')}</p>;

  const ownLine = (start: number, end: number): string => {
    if (second === undefined || second.picture) return '';
    const mid = (start + end) / 2 + second.offsetMs - learning.offsetMs;
    return activeIndices(second.cues, mid, second.offsetMs)
      .map((i) => second.cues[i]?.text ?? '')
      .join(' ')
      .replace(/\s+/g, ' ')
      .trim();
  };

  const onMouseUp = (): void => {
    const sel = window.getSelection();
    if (sel === null || sel.isCollapsed) return;
    const text = sel.toString().trim();
    if (text === '') return;
    const node = sel.anchorNode?.parentElement?.closest<HTMLElement>('[data-line]');
    if (node === null || node === undefined) return;
    const i = Number(node.dataset.line);
    const cue = learning.cues[i];
    if (cue === undefined) return;
    const rect = sel.getRangeAt(0).getBoundingClientRect();
    onSelectText(
      text,
      cue.text.replace(/\s+/g, ' ').trim(),
      (cue.start + learning.offsetMs) / 1000,
      learning.lang,
      rect,
    );
  };

  const q = query.trim();
  return (
    <>
      <div className={styles.searchRow}>
        <label className={styles.search}>
          <PIcon name="search" size={16} className={styles.searchIcon} />
          <input
            ref={searchRef}
            className={styles.searchInput}
            value={query}
            placeholder={t('player.tr.search')}
            aria-label={t('player.tr.search')}
            onChange={(e) => {
              setQuery(e.target.value);
              setHit(0);
              if (e.target.value.trim() !== '') setFollow(false);
            }}
            onKeyDown={(e) => {
              e.stopPropagation();
              if (e.key === 'Enter' || e.key === 'ArrowDown') goHit(1);
              if (e.key === 'ArrowUp') goHit(-1);
              if (e.key === 'Escape') setQuery('');
            }}
          />
          {q !== '' ? (
            <span className={styles.searchCount} aria-live="polite">
              {hits.length === 0
                ? t('player.tr.noResults')
                : t('player.tr.results', { at: hit + 1, count: hits.length })}
            </span>
          ) : null}
          <button
            type="button"
            className={styles.searchStep}
            aria-label={t('player.tr.previous')}
            onClick={() => {
              setHit((h) => (hits.length === 0 ? 0 : (h - 1 + hits.length) % hits.length));
            }}
          >
            <PIcon name="cu" size={18} />
          </button>
          <button
            type="button"
            className={styles.searchStep}
            aria-label={t('player.tr.next')}
            onClick={() => {
              setHit((h) => (hits.length === 0 ? 0 : (h + 1) % hits.length));
            }}
          >
            <PIcon name="cd" size={18} />
          </button>
        </label>
      </div>
      <div className={styles.chips}>
        {second !== undefined && !second.picture ? (
          <button
            type="button"
            className={cx(styles.chip, !both && styles.chipOff)}
            aria-pressed={both}
            onClick={() => {
              setBoth((b) => !b);
            }}
          >
            {languageName(learning.lang)} +{' '}
            <span className={styles.fa}>{second.lang === 'fa' ? 'فارسی' : languageName(second.lang)}</span>
          </button>
        ) : null}
        <button
          type="button"
          className={cx(styles.chip, !markOn && styles.chipOff)}
          aria-pressed={markOn}
          onClick={onToggleNotebookWords}
        >
          <PIcon name="book" size={13} />
          {t('player.tr.notebookWords')}
        </button>
        <span className={styles.followLabel}>{t('player.tr.follow')}</span>
        <Switch small checked={follow} label={t('player.tr.follow')} onChange={setFollow} />
      </div>
      <div
        ref={listRef}
        className={styles.lines}
        onScroll={() => {
          if (!programmatic.current && follow) setFollow(false);
        }}
        onMouseUp={onMouseUp}
      >
        {learning.cues.map((c, i) => {
          const isCurrent = i === current;
          const past = current >= 0 && i < current - CONTEXT_BEFORE;
          const own = both ? ownLine(c.start, c.end) : '';
          return (
            <div
              key={i}
              data-line={i}
              className={cx(styles.line, isCurrent && styles.lineNow, past && styles.past)}
            >
              <button
                type="button"
                className={styles.lineTime}
                aria-label={t('player.tr.jump', { time: clock((c.start + learning.offsetMs) / 1000) })}
                onClick={() => {
                  controller.seek(Math.max(0, (c.start + learning.offsetMs) / 1000 - JUMP_LEAD_S));
                }}
              >
                {clock((c.start + learning.offsetMs) / 1000)}
              </button>
              <div
                className={styles.lineBody}
                onClick={(e) => {
                  if (window.getSelection()?.isCollapsed !== false) {
                    e.preventDefault();
                    controller.seek(Math.max(0, (c.start + learning.offsetMs) / 1000 - JUMP_LEAD_S));
                  }
                }}
              >
                <div className={styles.lineText} dir={isRtlText(c.text) ? 'rtl' : 'ltr'}>
                  <Highlighted text={c.text} query={q} words={markOn ? notebookWords : null} />
                </div>
                {own !== '' ? (
                  <div className={styles.lineOwn} dir="rtl">
                    {own}
                  </div>
                ) : null}
              </div>
              <PIcon name="play" size={14} className={styles.lineGlyph} />
            </div>
          );
        })}
      </div>
      {!follow ? (
        <button
          type="button"
          className={styles.backToNow}
          onClick={() => {
            setFollow(true);
          }}
        >
          {t('player.tr.backToNow')}
        </button>
      ) : null}
      <div className={styles.foot}>{t('player.tr.foot')}</div>
    </>
  );
}

function Highlighted({
  text,
  query,
  words,
}: {
  text: string;
  query: string;
  words: ReadonlySet<string> | null;
}): React.JSX.Element {
  const flat = text.replace(/\s+/g, ' ');
  if (query === '' && words === null) return <>{flat}</>;
  const parts = flat.split(/(\s+)/);
  const q = query.toLocaleLowerCase();
  return (
    <>
      {parts.map((p, i) => {
        const bare = p.replace(/[^\p{L}\p{M}\p{N}'’-]/gu, '').toLocaleLowerCase();
        const inNb = words?.has(bare) === true;
        const hitHere = q !== '' && p.toLocaleLowerCase().includes(q);
        if (hitHere)
          return (
            <mark key={i} className={styles.mark}>
              {p}
            </mark>
          );
        if (inNb)
          return (
            <span key={i} className={styles.nbw}>
              {p}
            </span>
          );
        return <span key={i}>{p}</span>;
      })}
    </>
  );
}

export type { TrackState };
