/**
 * The subtitles on the video (spec §7): up to three boxes drawn by our own
 * engine, each a thing you can touch. Point at one and a grip and six
 * handles appear; the grip moves the box, the corners size it, the sides set
 * the line width, and the words are for clicking (one word), dragging
 * across (a phrase) or double-clicking. They never fight (§1.2).
 *
 * The playhead reaches this every frame through `controller.onTick`, but a
 * box renders only when its line changes; places are transforms, and a box
 * is measured only when its text changed (ResizeObserver), so playback
 * causes no layout work (§17).
 *
 * A new line never moves (§7.1): the box is placed before it is painted
 * (measured in a layout effect, hidden until then) and its place is never
 * animated. Only the bars' lift is, on its own `translate`, and only for the
 * moment the bars come or go (`LIFT_MS`).
 */
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type MouseEvent,
  type PointerEvent,
} from 'react';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import type { Cue } from '@/lib/platform/media.js';
import type { PlayerController } from '../controller.js';
import { activeIndices, isRtlText } from '../model/cues.js';
import {
  defaultLayout,
  fontPx,
  guidesFor,
  KEY_SCALE_STEP,
  KEY_STEP,
  KEY_STEP_BIG,
  layoutFromRect,
  liftFor,
  moveBy,
  pictureRect,
  placeBoxes,
  placeTo,
  readout,
  scaleBy,
  snap,
  widthTo,
  type Guide,
  type PlacedBox,
  type Rect,
  type Size,
  type SlotLayout,
} from '../model/layout.js';
import { languageName } from '../model/languages.js';
import type { SlotNumber } from '../model/slots.js';
import {
  asHeadword,
  lineOf,
  textBetween,
  tokenize,
  wordsBetween,
  MAX_WORDS,
  type Token,
} from '../model/words.js';
import { slotVisible, trackIn, updatePrefs, usePlayer, type TrackState } from '../store.js';
import { PIcon } from './icons.js';
import { Popover, Row } from './kit.js';
import { lineStyle, trackColourVar } from './subtitleStyle.js';
import styles from './Subtitles.module.css';

/** The grip and handles wait this long after the pointer arrives (§7.4). */
const HOVER_DELAY_MS = 150;
/** "Pause when I point at a subtitle": after resting this long on the text, and resuming this long after leaving (§7.6). */
const POINT_PAUSE_MS = 250;
const POINT_RESUME_MS = 300;
/** How long the bars' lift glides (the box's `.lifting` transition), with a frame to spare. */
const LIFT_MS = 200;

export interface WordSelection {
  slot: SlotNumber;
  cue: number;
  from: number;
  to: number;
}

/** One rendered line of a cue: its tokens with their span's look. */
interface TokenView extends Token {
  /** Index across the whole cue, so a phrase can cross spans. */
  index: number;
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  color?: string;
}

/** A cue's lines, tokenised. The file's own line breaks are kept (§7.1). */
export function cueLines(cue: Cue, keepColours: boolean): TokenView[][] {
  const lines: TokenView[][] = [[]];
  let index = 0;
  for (const span of cue.spans.length > 0 ? cue.spans : [{ text: cue.text }]) {
    const parts = span.text.split('\n');
    parts.forEach((part, i) => {
      if (i > 0) lines.push([]);
      for (const tok of tokenize(part)) {
        const view: TokenView = { ...tok, index };
        index += 1;
        if ('bold' in span && span.bold) view.bold = true;
        if ('italic' in span && span.italic) view.italic = true;
        if ('underline' in span && span.underline) view.underline = true;
        if (keepColours && 'color' in span && typeof span.color === 'string') view.color = span.color;
        lines[lines.length - 1]?.push(view);
      }
    });
  }
  return lines.filter((l) => l.length > 0);
}

/** All the tokens of a cue in order, for a selection's text. */
export function cueTokens(cue: Cue): Token[] {
  return cueLines(cue, false).flat();
}

interface LayerProps {
  controller: PlayerController;
  /** Where words are underlined because they are already in the notebook (off by default, §11.1). */
  notebookWords: ReadonlySet<string> | null;
  /** The selection the card is open on, painted in the selection wash. */
  selection: WordSelection | null;
  onSelect: (sel: WordSelection, rect: DOMRect, opts: { keyboard: boolean }) => void;
  /** A notice in the top-left corner: a top track steps down below it (§24.3). */
  noticeRect: Rect | null;
  /** The keyboard word cursor (W, §10). */
  wordCursor: WordSelection | null;
  /** A right-click on a word: the Player's own menu, with "Add … to Lexpad" (the box's menu stays for its frame). */
  onWordContext?: (sel: WordSelection, rect: DOMRect, text: string) => void;
}

interface DragState {
  slot: SlotNumber;
  kind: 'move' | 'scale' | 'width';
  startX: number;
  startY: number;
  startRect: Rect;
  startLayout: SlotLayout;
  layout: SlotLayout;
  guides: Guide[];
  /** The pixel size of the text, for the size readout. */
  px: number;
}

export function SubtitleLayer({
  controller,
  notebookWords,
  selection,
  onSelect,
  noticeRect,
  wordCursor,
  onWordContext,
}: LayerProps): React.JSX.Element {
  const ref = useRef<HTMLDivElement>(null);
  const [area, setArea] = useState<Size>({ w: 0, h: 0 });
  const [sizes, setSizes] = useState<Partial<Record<SlotNumber, Size>>>({});
  const [drag, setDrag] = useState<DragState | null>(null);
  const [hover, setHover] = useState<SlotNumber | null>(null);
  const [menu, setMenu] = useState<{ slot: SlotNumber; x: number; y: number } | null>(null);
  const [hint, setHint] = useState<SlotNumber | null>(null);
  const hoverTimer = useRef(0);
  const chrome = usePlayer((s) => s.chrome);
  const layouts = usePlayer((s) => s.prefs.layouts);
  const slots = usePlayer((s) => s.slots);
  const master = usePlayer((s) => s.master);
  const shown = usePlayer((s) => s.shown);
  const hintSeen = usePlayer((s) => s.prefs.hints.point);
  // The "click a word" hint waits while a word's card is open: it sat under the card.
  const cardOpen = usePlayer((s) => s.card !== null);
  const aspect = usePlayer((s) => {
    const v = s.playback?.plan.video;
    return v !== undefined && v.height > 0 ? v.width / v.height : 16 / 9;
  });

  useLayoutEffect(() => {
    const el = ref.current;
    if (el === null) return;
    const measure = (): void => {
      setArea({ w: el.clientWidth, h: el.clientHeight });
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => {
      ro.disconnect();
    };
  }, []);

  const visible = (n: SlotNumber): boolean => master && shown[n - 1] === true && slots[n - 1] !== null;

  // The lift glides only while the bars come or go, never when a line changes.
  const lifted = chrome && drag === null;
  const [liftSeen, setLiftSeen] = useState(lifted);
  const [lifting, setLifting] = useState(false);
  if (liftSeen !== lifted) {
    setLiftSeen(lifted);
    setLifting(true);
  }
  useEffect(() => {
    if (!lifting) return;
    const id = window.setTimeout(() => {
      setLifting(false);
    }, LIFT_MS + 50);
    return () => {
      window.clearTimeout(id);
    };
  }, [lifting, liftSeen]);

  const placed = useMemo(() => {
    const inputs = ([1, 2, 3] as const).flatMap((n) => {
      const size = sizes[n];
      if (!visible(n) || size === undefined) return [];
      const layout = drag?.slot === n ? drag.layout : layouts[n];
      return [
        {
          slot: n,
          layout,
          size,
          stacked: n === 3 && layout.mode !== 'custom' && sizes[1] !== undefined && visible(1),
        },
      ];
    });
    return placeBoxes(area, inputs, { chrome: lifted, notice: noticeRect });
    // `visible` reads the three values listed.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [area, sizes, layouts, drag, lifted, noticeRect, master, shown, slots]);

  /** A slot's lift before its line is measured, as `placeBoxes` will give it, so the first paint is already in place. */
  const liftOf = (n: SlotNumber): number => {
    const layout = drag?.slot === n ? drag.layout : layouts[n];
    const stacked = n === 3 && layout.mode !== 'custom' && sizes[1] !== undefined && visible(1);
    return liftFor(area, stacked ? layouts[1] : layout, lifted);
  };

  const picture = useMemo(() => pictureRect(area, aspect), [area, aspect]);

  const onSize = useCallback((slot: SlotNumber, size: Size | null) => {
    setSizes((s) => {
      const prev = s[slot];
      if (size === null) {
        if (prev === undefined) return s;
        const next: Partial<Record<SlotNumber, Size>> = {};
        for (const n of [1, 2, 3] as const) {
          const v = s[n];
          if (n !== slot && v !== undefined) next[n] = v;
        }
        return next;
      }
      if (prev !== undefined && Math.abs(prev.w - size.w) < 0.5 && Math.abs(prev.h - size.h) < 0.5) return s;
      return { ...s, [slot]: size };
    });
  }, []);

  const startHover = (slot: SlotNumber): void => {
    window.clearTimeout(hoverTimer.current);
    hoverTimer.current = window.setTimeout(() => {
      setHover(slot);
      if (!usePlayer.getState().prefs.hints.point) setHint(slot);
    }, HOVER_DELAY_MS);
  };
  const endHover = (): void => {
    window.clearTimeout(hoverTimer.current);
    hoverTimer.current = window.setTimeout(() => {
      setHover(null);
    }, HOVER_DELAY_MS);
  };
  useEffect(
    () => () => {
      window.clearTimeout(hoverTimer.current);
    },
    [],
  );

  const beginDrag = (slot: SlotNumber, kind: DragState['kind'], e: PointerEvent<HTMLElement>): void => {
    const box = placed.find((p) => p.slot === slot);
    if (box === undefined) return;
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    setDrag({
      slot,
      kind,
      startX: e.clientX,
      startY: e.clientY,
      startRect: box.rect,
      startLayout: layouts[slot],
      layout: layouts[slot],
      guides: [],
      px: fontPx(area, slot, layouts[slot].scale),
    });
    controller.markHint('move');
  };

  const moveDrag = (e: PointerEvent<HTMLElement>): void => {
    if (drag === null) return;
    const dx = e.clientX - drag.startX;
    const dy = e.clientY - drag.startY;
    if (drag.kind === 'move') {
      const others = placed.filter((p) => p.slot !== drag.slot).map((p) => p.rect);
      const proposed: Rect = {
        ...drag.startRect,
        x: e.shiftKey ? drag.startRect.x : drag.startRect.x + dx,
        y: drag.startRect.y + dy,
      };
      const free = e.metaKey || e.ctrlKey;
      const snapped = snap(proposed, guidesFor(area, picture, others), free);
      const layout = layoutFromRect(
        area,
        e.shiftKey ? { ...snapped.rect, x: drag.startRect.x } : snapped.rect,
        drag.startLayout,
      );
      setDrag({ ...drag, layout, guides: snapped.guides });
    } else if (drag.kind === 'scale') {
      const cx = drag.startRect.x + drag.startRect.w / 2;
      const cy = drag.startRect.y + drag.startRect.h / 2;
      const rect = ref.current?.getBoundingClientRect();
      const ox = rect?.left ?? 0;
      const oy = rect?.top ?? 0;
      const d0 = Math.hypot(drag.startX - ox - cx, drag.startY - oy - cy) || 1;
      const d1 = Math.hypot(e.clientX - ox - cx, e.clientY - oy - cy);
      const layout = scaleBy(
        { ...drag.startLayout, scale: drag.startLayout.scale },
        drag.startLayout.scale * (d1 / d0) - drag.startLayout.scale,
      );
      setDrag({ ...drag, layout, px: fontPx(area, drag.slot, layout.scale) });
    } else {
      const sign = (e.target as HTMLElement).dataset.side === 'l' ? -1 : 1;
      const layout = widthTo(
        drag.startLayout,
        drag.startLayout.width + (2 * sign * dx) / Math.max(1, area.w),
      );
      setDrag({ ...drag, layout });
    }
  };

  const endDrag = (cancel: boolean): void => {
    if (drag === null) return;
    if (!cancel) {
      const { slot, layout } = drag;
      updatePrefs((p) => ({ ...p, layouts: { ...p.layouts, [slot]: layout } }));
    }
    setDrag(null);
  };

  useEffect(() => {
    if (drag === null) return;
    const onKey = (e: globalThis.KeyboardEvent): void => {
      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        endDrag(true);
      }
    };
    window.addEventListener('keydown', onKey, true);
    return () => {
      window.removeEventListener('keydown', onKey, true);
    };
  });

  const setLayout = (slot: SlotNumber, layout: SlotLayout): void => {
    updatePrefs((p) => ({ ...p, layouts: { ...p.layouts, [slot]: layout } }));
  };

  const draggingBox = drag !== null ? placed.find((p) => p.slot === drag.slot) : undefined;
  const hintBox = hint !== null && !hintSeen && !cardOpen ? placed.find((p) => p.slot === hint) : undefined;

  return (
    <div
      ref={ref}
      className={cx(styles.layer, drag !== null && styles.dragging)}
      data-subtitle-layer=""
      onPointerMove={moveDrag}
      onPointerUp={() => {
        endDrag(false);
      }}
      data-chrome-hold={drag !== null ? '' : undefined}
    >
      {drag?.kind === 'move' ? <div className={styles.safe} aria-hidden="true" /> : null}
      {drag?.kind === 'move'
        ? drag.guides.map((g) => (
            <div
              key={`${g.kind}-${g.axis}-${String(g.at)}`}
              className={cx(styles.guide, g.axis === 'v' ? styles.guideV : styles.guideH)}
              style={g.axis === 'v' ? { left: g.at } : { top: g.at }}
              aria-hidden="true"
            >
              <span
                className={styles.guideLabel}
                style={g.axis === 'v' ? { top: '50%', left: 6 } : { left: 12, top: -10 }}
              >
                {t(`player.guide.${g.kind}` as 'player.guide.centre')}
              </span>
            </div>
          ))
        : null}
      {([1, 2, 3] as const).map((n) => (
        <SubtitleBox
          key={n}
          slot={n}
          controller={controller}
          area={area}
          box={placed.find((p) => p.slot === n)}
          lift={placed.find((p) => p.slot === n)?.lift ?? liftOf(n)}
          lifting={lifting}
          layout={drag?.slot === n ? drag.layout : layouts[n]}
          onSize={onSize}
          hovered={hover === n || drag?.slot === n}
          dragging={drag?.slot === n}
          onHoverStart={() => {
            startHover(n);
          }}
          onHoverEnd={endHover}
          onGripDown={(e) => {
            beginDrag(n, 'move', e);
          }}
          onHandleDown={(kind, e) => {
            beginDrag(n, kind, e);
          }}
          onReset={() => {
            setLayout(n, defaultLayout(n));
          }}
          onKeyMove={(layout) => {
            setLayout(n, layout);
          }}
          onContext={(x, y, word) => {
            if (word !== null && onWordContext !== undefined) {
              onWordContext({ slot: n, cue: word.cue, from: word.tok, to: word.tok }, word.rect, word.text);
              return;
            }
            setMenu({ slot: n, x, y });
          }}
          notebookWords={notebookWords}
          selection={selection?.slot === n ? selection : null}
          cursor={wordCursor?.slot === n ? wordCursor : null}
          onSelect={onSelect}
        />
      ))}
      {draggingBox !== undefined && drag !== null ? (
        <div
          className={styles.readout}
          style={{ left: draggingBox.rect.x + draggingBox.rect.w + 12, top: draggingBox.rect.y + 6 }}
          aria-live="polite"
        >
          {drag.kind === 'move'
            ? t('player.readout.pos', readout(drag.layout))
            : drag.kind === 'scale'
              ? t('player.readout.size', {
                  px: Math.round(drag.px),
                  pct: Math.round(drag.layout.scale * 100),
                })
              : t('player.readout.width', { pct: Math.round(drag.layout.width * 100) })}
        </div>
      ) : null}
      {hintBox !== undefined ? (
        <div
          className={styles.hint}
          role="status"
          style={{ left: area.w / 2, bottom: area.h - hintBox.rect.y + 64 }}
        >
          <PIcon name="move" size={18} className={styles.hintIcon} />
          <span>
            <b>{t('player.hint.pointStrong')}</b> {t('player.hint.point')}
          </span>
          <button
            type="button"
            className={styles.hintGot}
            onClick={() => {
              controller.markHint('point');
              setHint(null);
            }}
          >
            {t('player.hint.gotIt')}
          </button>
        </div>
      ) : null}
      {menu !== null ? (
        <BoxMenu
          slot={menu.slot}
          x={menu.x}
          y={menu.y}
          controller={controller}
          onClose={() => {
            setMenu(null);
          }}
          onLayout={(l) => {
            setLayout(menu.slot, l);
          }}
        />
      ) : null}
    </div>
  );
}

interface BoxProps {
  slot: SlotNumber;
  controller: PlayerController;
  area: Size;
  box: PlacedBox | undefined;
  /** The bars' part of the box's place (`PlacedBox.lift`), drawn as its own `translate`. */
  lift: number;
  /** The bars are coming or going: the lift glides. */
  lifting: boolean;
  layout: SlotLayout;
  onSize: (slot: SlotNumber, size: Size | null) => void;
  hovered: boolean;
  dragging: boolean;
  onHoverStart: () => void;
  onHoverEnd: () => void;
  onGripDown: (e: PointerEvent<HTMLElement>) => void;
  onHandleDown: (kind: 'scale' | 'width', e: PointerEvent<HTMLElement>) => void;
  onReset: () => void;
  onKeyMove: (layout: SlotLayout) => void;
  /** A right-click: where, and the word it was on, if any. */
  onContext: (
    x: number,
    y: number,
    word: { cue: number; tok: number; rect: DOMRect; text: string } | null,
  ) => void;
  notebookWords: ReadonlySet<string> | null;
  selection: WordSelection | null;
  cursor: WordSelection | null;
  onSelect: LayerProps['onSelect'];
}

function SubtitleBox({
  slot,
  controller,
  area,
  box,
  lift,
  lifting,
  layout,
  onSize,
  hovered,
  dragging,
  onHoverStart,
  onHoverEnd,
  onGripDown,
  onHandleDown,
  onReset,
  onKeyMove,
  onContext,
  notebookWords,
  selection,
  cursor,
  onSelect,
}: BoxProps): React.JSX.Element | null {
  const track = usePlayer((s) => trackIn(s, slot));
  const isVisible = usePlayer((s) => slotVisible(s, slot));
  const style = usePlayer((s) => s.prefs.styles[slot]);
  const useMine = usePlayer((s) => s.prefs.settings.myStyleForAss);
  const pauseOnPoint = usePlayer((s) => s.prefs.settings.pauseOnPoint);
  const prompted = usePlayer((s) => s.prompt?.kind === 'one' && s.prompt.trackId === track?.id);
  const [active, setActive] = useState<number[]>([]);
  const ref = useRef<HTMLDivElement>(null);
  const pointTimer = useRef(0);
  const pausedByMe = useRef(false);
  const press = useRef<{ cue: number; from: number; moved: boolean; pointerId: number } | null>(null);
  const [pressSel, setPressSel] = useState<WordSelection | null>(null);

  // The line on screen: recomputed every frame, rendered only when it changes.
  useEffect(() => {
    if (track === undefined || !isVisible) return;
    let last = '';
    return controller.onTick((time) => {
      const idx = activeIndices(track.cues, time * 1000, track.offsetMs);
      const key = idx.join(',');
      if (key !== last) {
        last = key;
        setActive(idx);
      }
    });
  }, [controller, track, isVisible]);

  // Measured only when its text or size changes.
  useLayoutEffect(() => {
    const el = ref.current;
    if (el === null || active.length === 0) {
      onSize(slot, null);
      return;
    }
    const measure = (): void => {
      onSize(slot, { w: el.offsetWidth, h: el.offsetHeight });
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => {
      ro.disconnect();
    };
  }, [active, slot, onSize]);

  useEffect(
    () => () => {
      window.clearTimeout(pointTimer.current);
    },
    [],
  );

  const stepsAside = usePlayer((st) => st.stepAside.includes(slot));

  if (track === undefined || !isVisible || active.length === 0) return null;

  const px = fontPx(area, slot, layout.scale);
  const anchorTop = box?.anchor === 'top';
  const lang = track.lang;
  const keepColours = track.format === 'ass' && !useMine;
  const cues = active.flatMap((i) => {
    const cue = track.cues[i];
    return cue === undefined ? [] : [{ index: i, cue }];
  });
  const placeWord =
    layout.mode === 'custom'
      ? t('player.place.custom')
      : slot === 2
        ? t('player.place.top')
        : slot === 3
          ? t('player.place.above1')
          : t('player.place.bottom');
  // The place without the lift, never animated; the lift on top of it (CSS adds `translate` before `transform`).
  const boxStyle: CSSProperties = {
    transform:
      box !== undefined
        ? `translate3d(${String(box.rect.x)}px, ${String(box.rect.y - lift)}px, 0)`
        : undefined,
    translate: `0 ${String(lift)}px`,
    // Unplaced yet, or stepping aside for the word card in a very small window (placeCard).
    visibility: box === undefined || stepsAside ? 'hidden' : undefined,
    maxWidth: `${String(Math.max(120, layout.width * area.w))}px`,
  };

  const onTextEnter = (): void => {
    if (!pauseOnPoint || dragging) return;
    window.clearTimeout(pointTimer.current);
    pointTimer.current = window.setTimeout(() => {
      if (controller.isPlaying() && usePlayer.getState().card === null) {
        pausedByMe.current = true;
        controller.pause();
      }
    }, POINT_PAUSE_MS);
  };
  const onTextLeave = (): void => {
    window.clearTimeout(pointTimer.current);
    if (!pausedByMe.current) return;
    pointTimer.current = window.setTimeout(() => {
      if (pausedByMe.current && usePlayer.getState().card === null) controller.play();
      pausedByMe.current = false;
    }, POINT_RESUME_MS);
  };

  const tokAt = (target: EventTarget | null): { cue: number; tok: number } | null => {
    const el = (target as HTMLElement | null)?.closest<HTMLElement>('[data-tok]');
    if (el == null) return null;
    return { cue: Number(el.dataset.cue), tok: Number(el.dataset.tok) };
  };

  const selectionRect = (sel: WordSelection): DOMRect | null => {
    const root = ref.current;
    if (root === null) return null;
    const a = Math.min(sel.from, sel.to);
    const b = Math.max(sel.from, sel.to);
    let rect: DOMRect | null = null;
    for (const el of root.querySelectorAll<HTMLElement>(`[data-cue="${String(sel.cue)}"][data-tok]`)) {
      const i = Number(el.dataset.tok);
      if (i < a || i > b) continue;
      const r = el.getBoundingClientRect();
      rect =
        rect === null
          ? r
          : new DOMRect(
              Math.min(rect.left, r.left),
              Math.min(rect.top, r.top),
              Math.max(rect.right, r.right) - Math.min(rect.left, r.left),
              Math.max(rect.bottom, r.bottom) - Math.min(rect.top, r.top),
            );
    }
    return rect;
  };

  const finish = (sel: WordSelection): void => {
    const rect = selectionRect(sel);
    if (rect !== null) onSelect(sel, rect, { keyboard: false });
  };

  const onTextDown = (e: PointerEvent<HTMLDivElement>): void => {
    if (e.button !== 0 || track.picture) return;
    // Alt / Option-drag anywhere on the box moves it (§7.4).
    if (e.altKey) {
      onGripDown(e);
      return;
    }
    const at = tokAt(e.target);
    if (at === null) return;
    e.stopPropagation();
    e.currentTarget.setPointerCapture(e.pointerId);
    press.current = { cue: at.cue, from: at.tok, moved: false, pointerId: e.pointerId };
    setPressSel({ slot, cue: at.cue, from: at.tok, to: at.tok });
  };
  const onTextMove = (e: PointerEvent<HTMLDivElement>): void => {
    const p = press.current;
    if (p === null) return;
    const el = document.elementFromPoint(e.clientX, e.clientY);
    const at = tokAt(el);
    if (at?.cue !== p.cue) return;
    if (at.tok !== p.from) p.moved = true;
    setPressSel({ slot, cue: p.cue, from: p.from, to: at.tok });
  };
  const onTextUp = (e: PointerEvent<HTMLDivElement>): void => {
    const p = press.current;
    press.current = null;
    if (p === null) return;
    e.stopPropagation();
    const sel = pressSel ?? { slot, cue: p.cue, from: p.from, to: p.from };
    setPressSel(null);
    // A click on a space or punctuation is not a word.
    const cue = track.cues[sel.cue];
    if (cue === undefined) return;
    const tokens = cueTokens(cue);
    const a = Math.min(sel.from, sel.to);
    const b = Math.max(sel.from, sel.to);
    if (!tokens.slice(a, b + 1).some((tk) => tk.word)) return;
    finish(sel);
  };

  const onKey = (e: KeyboardEvent<HTMLButtonElement>): void => {
    const step = e.shiftKey ? KEY_STEP_BIG : KEY_STEP;
    let next: SlotLayout | undefined;
    switch (e.key) {
      case 'ArrowLeft':
        next = moveBy(layout, -step, 0);
        break;
      case 'ArrowRight':
        next = moveBy(layout, step, 0);
        break;
      case 'ArrowUp':
        next = moveBy(layout, 0, -step);
        break;
      case 'ArrowDown':
        next = moveBy(layout, 0, step);
        break;
      case '+':
      case '=':
        next = scaleBy(layout, KEY_SCALE_STEP);
        break;
      case '-':
      case '_':
        next = scaleBy(layout, -KEY_SCALE_STEP);
        break;
      case '0':
        onReset();
        e.preventDefault();
        e.stopPropagation();
        return;
      case 'Enter':
        e.preventDefault();
        e.stopPropagation();
        controller.openPanel('subtitles');
        return;
      default:
        return;
    }
    e.preventDefault();
    e.stopPropagation();
    onKeyMove(next);
  };

  const hl = pressSel ?? selection;
  const showChrome = hovered || dragging;
  const colourVar = trackColourVar(style.colour);

  return (
    <div
      ref={ref}
      className={cx(
        styles.box,
        style.edge === 'box' && styles.edgeBox,
        style.edge === 'outline' && styles.edgeOutline,
        style.edge === 'shadow' && styles.edgeShadow,
        showChrome && styles.edit,
        lifting && styles.lifting,
        dragging && styles.drag,
        prompted && styles.prompted,
        track.picture && styles.picture,
      )}
      style={boxStyle}
      data-slot={slot}
      onPointerEnter={onHoverStart}
      onPointerLeave={onHoverEnd}
      onContextMenu={(e: MouseEvent<HTMLDivElement>) => {
        e.preventDefault();
        // The Player's own menu (PlayerScreen) must not also open.
        e.stopPropagation();
        const w = (e.target as HTMLElement).closest<HTMLElement>('[data-word]');
        onContext(
          e.clientX,
          e.clientY,
          w === null
            ? null
            : {
                cue: Number(w.dataset.cue),
                tok: Number(w.dataset.tok),
                rect: w.getBoundingClientRect(),
                text: w.textContent,
              },
        );
      }}
    >
      <div
        className={styles.text}
        style={lineStyle(style, lang, px)}
        onPointerEnter={onTextEnter}
        onPointerLeave={onTextLeave}
        onPointerDown={onTextDown}
        onPointerMove={onTextMove}
        onPointerUp={onTextUp}
        onDoubleClick={(e) => {
          e.stopPropagation();
        }}
      >
        {cues.map(({ index, cue }) =>
          cue.image !== undefined ? (
            <img
              key={index}
              src={cue.image.src}
              alt=""
              className={styles.image}
              style={{ width: `${String(cue.image.box[2] * area.w * layout.scale)}px` }}
              draggable={false}
            />
          ) : (
            <CueText
              key={index}
              cue={cue}
              index={index}
              keepColours={keepColours}
              notebookWords={notebookWords}
              selection={hl !== null && hl.cue === index ? hl : null}
              cursor={cursor !== null && cursor.cue === index ? cursor : null}
            />
          ),
        )}
      </div>
      {showChrome ? (
        <>
          <i
            className={cx(styles.h, styles.tl)}
            onPointerDown={(e) => {
              onHandleDown('scale', e);
            }}
            aria-hidden="true"
          />
          <i
            className={cx(styles.h, styles.tr)}
            onPointerDown={(e) => {
              onHandleDown('scale', e);
            }}
            aria-hidden="true"
          />
          <i
            className={cx(styles.h, styles.bl)}
            onPointerDown={(e) => {
              onHandleDown('scale', e);
            }}
            aria-hidden="true"
          />
          <i
            className={cx(styles.h, styles.br)}
            onPointerDown={(e) => {
              onHandleDown('scale', e);
            }}
            aria-hidden="true"
          />
          <i
            className={cx(styles.h, styles.ml)}
            data-side="l"
            onPointerDown={(e) => {
              onHandleDown('width', e);
            }}
            aria-hidden="true"
          />
          <i
            className={cx(styles.h, styles.mr)}
            data-side="r"
            onPointerDown={(e) => {
              onHandleDown('width', e);
            }}
            aria-hidden="true"
          />
        </>
      ) : null}
      <div
        className={cx(styles.grip, anchorTop && styles.gripBelow, showChrome && styles.gripShown)}
        dir="ltr"
      >
        <button
          type="button"
          className={styles.gripMove}
          aria-roledescription={t('player.grip.role')}
          aria-label={t('player.grip.label', {
            n: slot,
            lang: languageName(lang),
            place: placeWord.toLowerCase(),
          })}
          onPointerDown={onGripDown}
          onDoubleClick={(e) => {
            e.stopPropagation();
            onReset();
          }}
          onKeyDown={onKey}
          onFocus={onHoverStart}
          onBlur={onHoverEnd}
        >
          <span className={styles.gripDots}>
            <PIcon name="dots" size={15} />
          </span>
          <span className={styles.gripDot} style={{ background: colourVar }} />
          <span>
            {slot} · {languageName(lang)}
          </span>
          <span className={styles.gripSlot}>{placeWord.toLowerCase()}</span>
        </button>
        {!dragging ? (
          <button
            type="button"
            className={styles.gripEye}
            aria-label={t('player.grip.hide', { n: slot })}
            onClick={(e) => {
              e.stopPropagation();
              controller.toggleSlot(slot);
            }}
          >
            <PIcon name="eye" size={15} />
          </button>
        ) : null}
      </div>
      {track.picture && hovered ? <PictureNote controller={controller} /> : null}
    </div>
  );
}

function PictureNote({ controller }: { controller: PlayerController }): null {
  const shownFor = useRef<string | null>(null);
  const file = usePlayer((s) => s.file?.id ?? null);
  useEffect(() => {
    if (file === null || shownFor.current === file) return;
    shownFor.current = file;
    controller.notice({
      text: t('player.subs.pictureNotice'),
      icon: 'info',
      action: {
        label: t('player.subs.addAFile'),
        run: () => {
          void controller.pick();
        },
      },
    });
  }, [controller, file]);
  return null;
}

interface CueTextProps {
  cue: Cue;
  index: number;
  keepColours: boolean;
  notebookWords: ReadonlySet<string> | null;
  selection: WordSelection | null;
  cursor: WordSelection | null;
}

function CueText({
  cue,
  index,
  keepColours,
  notebookWords,
  selection,
  cursor,
}: CueTextProps): React.JSX.Element {
  const lines = useMemo(() => cueLines(cue, keepColours), [cue, keepColours]);
  const a = selection === null ? -1 : Math.min(selection.from, selection.to);
  const b = selection === null ? -1 : Math.max(selection.from, selection.to);
  const ca = cursor === null ? -1 : Math.min(cursor.from, cursor.to);
  const cb = cursor === null ? -1 : Math.max(cursor.from, cursor.to);
  return (
    <>
      {lines.map((line, li) => {
        const text = line.map((tk) => tk.text).join('');
        return (
          <span key={li} className={styles.lineWrap}>
            {li > 0 ? <br /> : null}
            <span className={styles.ln} dir={isRtlText(text) ? 'rtl' : 'ltr'}>
              {line.map((tk) =>
                tk.word ? (
                  <span
                    key={tk.index}
                    data-cue={index}
                    data-tok={tk.index}
                    data-word=""
                    data-selected={tk.index >= a && tk.index <= b ? '' : undefined}
                    className={cx(
                      styles.w,
                      tk.index >= a && tk.index <= b && styles.sel,
                      tk.index >= ca && tk.index <= cb && styles.cursor,
                      notebookWords?.has(tk.text.toLocaleLowerCase()) === true && styles.nb,
                    )}
                    style={{
                      ...(tk.bold === true ? { fontWeight: 700 } : {}),
                      ...(tk.italic === true ? { fontStyle: 'italic' } : {}),
                      ...(tk.color !== undefined ? { color: tk.color } : {}),
                    }}
                  >
                    {tk.text}
                  </span>
                ) : (
                  <span
                    key={tk.index}
                    data-cue={index}
                    data-tok={tk.index}
                    style={{
                      ...(tk.italic === true ? { fontStyle: 'italic' } : {}),
                      ...(tk.color !== undefined ? { color: tk.color } : {}),
                    }}
                  >
                    {tk.text}
                  </span>
                ),
              )}
            </span>
          </span>
        );
      })}
    </>
  );
}

function BoxMenu({
  slot,
  x,
  y,
  controller,
  onClose,
  onLayout,
}: {
  slot: SlotNumber;
  x: number;
  y: number;
  controller: PlayerController;
  onClose: () => void;
  onLayout: (l: SlotLayout) => void;
}): React.JSX.Element {
  const layout = usePlayer((s) => s.prefs.layouts[slot]);
  return (
    <Popover
      label={t('player.grip.menu', { n: slot })}
      onClose={onClose}
      className={styles.boxMenu}
      style={{ position: 'fixed', left: x, top: y }}
    >
      <Row
        onClick={() => {
          onClose();
          controller.toggleSlot(slot);
        }}
      >
        {t('player.grip.hide', { n: slot })}
      </Row>
      <Row
        onClick={() => {
          onClose();
          usePlayer.setState({ focusSlot: slot });
          controller.openPanel('subtitles');
        }}
      >
        {t('player.grip.style')}
      </Row>
      <Row
        onClick={() => {
          onClose();
          usePlayer.setState({ focusSlot: slot });
          controller.openPanel('subtitles');
        }}
      >
        {t('player.grip.timing')}
      </Row>
      <Row
        onClick={() => {
          onClose();
          onLayout(defaultLayout(slot));
        }}
      >
        {t('player.grip.reset')}
      </Row>
      <Row
        onClick={() => {
          onClose();
          onLayout(placeTo(layout, layout.anchor === 'top' ? 'bottom' : 'top'));
        }}
      >
        {layout.anchor === 'top' ? t('player.grip.toBottom') : t('player.grip.toTop')}
      </Row>
    </Popover>
  );
}

/** What a selection becomes: the headword, or the words to pick from when it is too long. */
export function selectionText(
  track: TrackState,
  sel: WordSelection,
): { headword: string | null; sentence: string; pickFrom?: string[] } {
  const cue = track.cues[sel.cue];
  if (cue === undefined) return { headword: null, sentence: '' };
  const tokens = cueTokens(cue);
  const sentence = lineOf(cue.text);
  const text = textBetween(tokens, sel.from, sel.to);
  const words = wordsBetween(tokens, sel.from, sel.to);
  if (words > MAX_WORDS) {
    return {
      headword: null,
      sentence,
      pickFrom: tokens
        .slice(Math.min(sel.from, sel.to), Math.max(sel.from, sel.to) + 1)
        .filter((tk) => tk.word)
        .map((tk) => tk.text),
    };
  }
  return { headword: asHeadword(text) ?? null, sentence };
}
