/**
 * The Player's right-click menu (owner, 26 Oct 2026: "right-click on the
 * video shows almost nothing"; like IINA's and VLC's). The core draws it as
 * the system's own menu (`player_context_menu`), the same items on macOS and
 * Windows; a chosen item comes back as a command on `player:menu`, like the
 * menu bar's. The page hands it the state and gets the items (no React).
 *
 * Every shortcut shown is read from the key table (`keys.ts` `commandFor`),
 * so the menu can never promise a key the Player does not answer.
 */
import { t, type MessageKey } from '@/i18n/index.js';
import type { CtxItem } from '@/lib/platform/types.js';
import { commandFor, type Command, type KeyLike, type Os } from './model/keys.js';

/** The speeds the Player offers (controller.ts SPEEDS). */
export interface ContextState {
  os: Os;
  hasVideo: boolean;
  paused: boolean;
  speed: number;
  speeds: readonly number[];
  /** Seconds ← and → move (Settings → Skip). */
  skip: number;
  /** Subtitle 1–3 as they are loaded: the language's name, shown or not. */
  tracks: { slot: 1 | 2 | 3; name: string; on: boolean }[];
  /** The master switch (C). */
  subtitlesOn: boolean;
  /** The video's audio streams, when there are several. */
  audio: { index: number; name: string; on: boolean }[];
  fullscreen: boolean;
  onTop: boolean;
  mini: boolean;
  /** The word right-clicked in a subtitle, when it was one. */
  word: string | null;
  /** The transcript panel is open. */
  transcriptOpen: boolean;
  /** A subtitle line is on screen now (Copy Line has something to copy). */
  lineShown: boolean;
}

/** Menu commands that are not keys: what the core sends back for them. */
export type MenuCommand =
  Command | 'addSubtitle' | 'addWord' | 'onTop' | `speed:${string}` | `audio:${string}`;

/* ------------------------------------------------------------ the keys, from the table */

/** The keys a press may be made of, in the order a shortcut is preferred. */
const KEYS = [
  ' ',
  'ArrowLeft',
  'ArrowRight',
  'ArrowUp',
  'ArrowDown',
  '[',
  ']',
  '\\',
  '?',
  ...'abcdefghijklmnopqrstuvwxyz0123456789,'.split(''),
  'F11',
];

/** Tauri's accelerator name for a key (`Space`, `Left`, `BracketLeft`, `O`…). */
function keyName(key: string): string {
  switch (key) {
    case ' ':
      return 'Space';
    case 'ArrowLeft':
      return 'Left';
    case 'ArrowRight':
      return 'Right';
    case 'ArrowUp':
      return 'Up';
    case 'ArrowDown':
      return 'Down';
    case '[':
      return 'BracketLeft';
    case ']':
      return 'BracketRight';
    case '\\':
      return 'Backslash';
    case '?':
      return 'Shift+Slash';
    case ',':
      return 'Comma';
    default:
      return key.length === 1 ? key.toUpperCase() : key;
  }
}

const memo = new Map<string, string | undefined>();

/**
 * The shortcut the key table gives `command`, as a Tauri accelerator
 * ("Space", "Shift+Left", "CmdOrCtrl+O"), or undefined when no key does it.
 * Single keys are read as if switched on: the menu shows the Player's keys.
 */
export function accelFor(command: Command, os: Os): string | undefined {
  const k = `${os}:${command}`;
  if (memo.has(k)) return memo.get(k);
  let found: string | undefined;
  const ctx = { os, typing: false, singleKeys: true };
  const press = (key: string, shift: boolean, mod: boolean): KeyLike => ({
    key: shift && key.length === 1 ? key.toUpperCase() : key,
    shiftKey: shift,
    altKey: false,
    metaKey: mod && os === 'macos',
    ctrlKey: mod && os !== 'macos',
  });
  outer: for (const mod of [false, true]) {
    for (const shift of [false, true]) {
      for (const key of KEYS) {
        // '?' is typed with Shift on its own; "Shift+?" is not a key.
        if (key === '?' && shift) continue;
        if (commandFor(press(key, shift, mod), ctx) === command) {
          const name = keyName(key);
          found = [mod ? 'CmdOrCtrl' : null, shift && !name.startsWith('Shift+') ? 'Shift' : null, name]
            .filter((x): x is string => x !== null)
            .join('+');
          break outer;
        }
      }
    }
  }
  memo.set(k, found);
  return found;
}

/* ------------------------------------------------------------ the items */

/**
 * Each OS's own menu style (uiux build review m5): macOS menus are in Title
 * Case ("Back 5 Seconds"), Windows menus in sentence case ("Back 5 seconds").
 * The labels live twice in the catalogue, `player.ctx.*` (macOS) and
 * `player.ctxWin.*` (Windows); `CTX_LABELS` lists them, and a test holds both.
 */
export const CTX_LABELS = [
  'play',
  'pause',
  'back',
  'forward',
  'replay',
  'copyLine',
  'speed',
  'speedNormal',
  'speedX',
  'slower',
  'faster',
  'normal',
  'subtitles',
  'track',
  'addSubtitle',
  'earlier',
  'later',
  'heard',
  'hideAll',
  'panel',
  'audio',
  'audioN',
  'addWord',
  'transcript',
  'fullscreen',
  'exitFullscreen',
  'onTop',
  'mini',
  'miniBack',
  'open',
  'shortcuts',
] as const;
export type CtxLabel = (typeof CTX_LABELS)[number];

export function ctxLabel(key: CtxLabel, os: Os, vars?: Record<string, string | number>): string {
  const full = `player.${os === 'windows' ? 'ctxWin' : 'ctx'}.${key}` as MessageKey;
  return t(full, vars);
}

/**
 * The shortcut shown beside a row. Only keys every menu draws in its own
 * form (macOS ← → ⌘O, Windows Left Right Ctrl+O); one a menu would spell
 * out with its Shift ("?" is Shift+/) is left off rather than shown wrong.
 * Why "?" cannot be drawn: Tauri 2.12 parses a menu item's accelerator into
 * muda's physical `Accelerator` (a key code: Slash) and gives no way to set
 * muda's logical `KeyAccelerator` (Key::Character("?")), so macOS would draw
 * "⇧/" and Windows "Shift+/". Only a core that sets the NSMenuItem's
 * keyEquivalent to "?" itself could show it.
 */
function shownAccel(command: MenuCommand, os: Os): string | undefined {
  if (command.includes(':')) return undefined;
  const accel = accelFor(command as Command, os);
  return accel === undefined || accel.includes('Slash') ? undefined : accel;
}

function item(command: MenuCommand, label: string, os: Os, enabled = true): CtxItem {
  const accel = shownAccel(command, os);
  return { kind: 'item', command, label, ...(accel !== undefined ? { accel } : {}), enabled };
}

function check(command: MenuCommand, label: string, checked: boolean, os: Os, enabled = true): CtxItem {
  const accel = shownAccel(command, os);
  return { kind: 'check', command, label, checked, ...(accel !== undefined ? { accel } : {}), enabled };
}

const SEP: CtxItem = { kind: 'separator' };

/**
 * The menu for this moment, in the order IINA's and VLC's follow: the word
 * (when the right-click was on one), transport, tracks, view, then file and
 * help. Without a video it offers only what can be done then.
 */
export function contextMenuItems(s: ContextState): CtxItem[] {
  const os = s.os;
  const L = (key: CtxLabel, vars?: Record<string, string | number>): string => ctxLabel(key, os, vars);
  const viewRows = (): CtxItem[] => [...(s.mini ? [] : [check('onTop', L('onTop'), s.onTop, os)])];
  if (!s.hasVideo) {
    return [item('open', L('open'), os), SEP, ...viewRows(), item('shortcuts', L('shortcuts'), os)];
  }
  const hasTracks = s.tracks.length > 0;
  const out: CtxItem[] = [];
  if (s.word !== null) out.push(item('addWord', L('addWord', { word: s.word }), os), SEP);
  // Transport.
  out.push(
    item('playPause', s.paused ? L('play') : L('pause'), os),
    item('back5', L('back', { n: s.skip }), os),
    item('forward5', L('forward', { n: s.skip }), os),
    item('replayLine', L('replay'), os, hasTracks),
    item('copyLine', L('copyLine'), os, s.lineShown),
    SEP,
    {
      kind: 'submenu',
      label: L('speed'),
      items: [
        ...s.speeds.map((x) =>
          check(
            `speed:${String(x)}`,
            x === 1 ? L('speedNormal') : L('speedX', { x: String(x) }),
            Math.abs(x - s.speed) < 0.001,
            os,
          ),
        ),
        SEP,
        item('slower', L('slower'), os),
        item('faster', L('faster'), os),
        item('normalSpeed', L('normal'), os),
      ],
    },
    SEP,
  );
  // Tracks.
  out.push({
    kind: 'submenu',
    label: L('subtitles'),
    items: [
      ...s.tracks.map((tr) =>
        check(
          `toggleTrack${String(tr.slot)}` as Command,
          L('track', { n: tr.slot, name: tr.name }),
          tr.on,
          os,
        ),
      ),
      ...(hasTracks ? [SEP] : []),
      item('addSubtitle', L('addSubtitle'), os),
      SEP,
      item('timingEarlier', L('earlier'), os, hasTracks),
      item('timingLater', L('later'), os, hasTracks),
      item('heard', L('heard'), os, hasTracks),
      SEP,
      check('toggleSubtitles', L('hideAll'), !s.subtitlesOn, os, hasTracks),
      item('subtitlesPanel', L('panel'), os),
    ],
  });
  if (s.audio.length > 1) {
    out.push({
      kind: 'submenu',
      label: L('audio'),
      items: s.audio.map((a) => check(`audio:${String(a.index)}`, a.name, a.on, os)),
    });
  }
  // View.
  out.push(
    SEP,
    check('transcript', L('transcript'), s.transcriptOpen, os),
    // macOS's own wording, "Enter Full Screen" / "Exit Full Screen", as a plain
    // item (build review p3); Windows the same kind in sentence case.
    item('fullscreen', s.fullscreen ? L('exitFullscreen') : L('fullscreen'), os),
    ...viewRows(),
    item('mini', s.mini ? L('miniBack') : L('mini'), os),
    // File and help.
    SEP,
    item('open', L('open'), os),
    item('shortcuts', L('shortcuts'), os),
  );
  return out;
}

/** A command the menu sent back: one with a value, or a plain one. */
export function parseMenuCommand(
  c: string,
): { kind: 'speed'; value: number } | { kind: 'audio'; index: number } | { kind: 'plain'; command: string } {
  const [head, value] = c.split(':');
  if (head === 'speed' && value !== undefined && Number.isFinite(Number(value)))
    return { kind: 'speed', value: Number(value) };
  if (head === 'audio' && value !== undefined && Number.isInteger(Number(value)))
    return { kind: 'audio', index: Number(value) };
  return { kind: 'plain', command: c };
}
