/**
 * The control bar (spec §6): the seek bar, then one 48 px row — play, the
 * episode buttons for a series, replay this line, volume with its boost,
 * the time and the chapter; on the right speed and audio pills, then
 * subtitles, transcript, mini player and full screen. Below 900 px the rare
 * ones move into "More" (§6.9).
 */
import { useEffect, useRef, useState, type KeyboardEvent, type WheelEvent } from 'react';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { MAX_VOLUME, VOLUME_STEP, type PlayerController } from '../controller.js';
import { clock, remaining } from '../model/time.js';
import { boostHere, shownCount, usePlayer } from '../store.js';
import { PIcon } from './icons.js';
import { IconButton } from './kit.js';
import { AudioMenu, MoreMenu, SpeedMenu, SubtitlesMenu, VolumeMenu } from './menus.js';
import { SeekBar } from './SeekBar.js';
import styles from './ControlBar.module.css';

interface Props {
  controller: PlayerController;
  onFullscreen: () => void;
  onMini: () => void;
}

export function ControlBar({ controller, onFullscreen, onMini }: Props): React.JSX.Element {
  const paused = usePlayer((s) => s.paused);
  const small = usePlayer((s) => s.small);
  const series = usePlayer((s) => s.episodes !== null);
  const next = usePlayer((s) => s.episodes?.next);
  const previous = usePlayer((s) => s.episodes?.previous);
  const menu = usePlayer((s) => s.menu);
  const speed = usePlayer((s) => s.speed);
  const audioCount = usePlayer((s) => s.playback?.info.audio.length ?? 0);
  const audioLang = usePlayer((s) => {
    const a = s.playback?.info.audio.find((x) => x.index === s.audio) ?? s.playback?.info.audio[0];
    return (a?.language ?? a?.languageTag ?? '').slice(0, 2).toUpperCase();
  });
  const anyShown = usePlayer((s) => shownCount(s) > 0);
  const count = usePlayer(shownCount);
  const hasTracks = usePlayer((s) => s.slots.some((x) => x !== null));
  const panel = usePlayer((s) => s.panel);
  const fullscreen = usePlayer((s) => s.fullscreen);
  // The buttons that open menus: the menus hand focus back to them.
  const [subsEl, subsRef] = useState<HTMLButtonElement | null>(null);
  const [speedEl, speedRef] = useState<HTMLButtonElement | null>(null);
  const [audioEl, audioRef] = useState<HTMLButtonElement | null>(null);
  const [moreEl, moreRef] = useState<HTMLButtonElement | null>(null);
  const [volEl, volRef] = useState<HTMLButtonElement | null>(null);

  const toggleMenu = (m: NonNullable<ReturnType<typeof usePlayer.getState>['menu']>): void => {
    usePlayer.setState((s) => ({ menu: s.menu === m ? null : m }));
  };
  const closeMenu = (): void => {
    usePlayer.setState({ menu: null });
  };

  return (
    <div className={styles.bar} data-chrome-zone="">
      <SeekBar controller={controller} />
      <div className={styles.row}>
        <IconButton
          icon={paused ? 'play' : 'pause'}
          label={paused ? t('player.ctl.play') : t('player.ctl.pause')}
          keys={['Space']}
          big
          onClick={() => {
            controller.togglePlay();
          }}
        />
        {series && !small ? (
          <IconButton
            icon="prev"
            label={t('player.ctl.previousEpisode')}
            keys={['⇧P']}
            disabled={previous === undefined}
            onClick={() => {
              if (previous !== undefined) void controller.openVideo(previous);
            }}
          />
        ) : null}
        {series ? (
          <IconButton
            icon="next"
            label={t('player.ctl.nextEpisode')}
            keys={['⇧N']}
            disabled={next === undefined}
            onClick={() => {
              if (next !== undefined) void controller.openVideo(next);
            }}
          />
        ) : null}
        {!small ? (
          <IconButton
            icon="replay"
            label={t('player.ctl.replay')}
            keys={['R']}
            onClick={() => {
              controller.stepLine(0);
            }}
          />
        ) : null}
        <Volume
          controller={controller}
          small={small}
          menuOpen={menu === 'volume'}
          buttonRef={volRef}
          anchor={volEl}
          onToggleMenu={() => {
            toggleMenu('volume');
          }}
          onCloseMenu={closeMenu}
        />
        <Time controller={controller} small={small} />
        {!small ? <Chapter controller={controller} /> : null}
        <div className={styles.spacer} />
        {!small ? (
          <div className={styles.anchor}>
            <button
              ref={speedRef}
              type="button"
              className={cx(styles.pill, menu === 'speed' && styles.pillOpen)}
              aria-label={`${t('player.ctl.speed')} ${speedText(speed)}`}
              aria-haspopup="menu"
              aria-expanded={menu === 'speed'}
              onClick={() => {
                toggleMenu('speed');
              }}
            >
              <PIcon name="speed" size={16} />
              {speedText(speed)}
            </button>
            {menu === 'speed' ? (
              <SpeedMenu controller={controller} anchor={speedEl} onClose={closeMenu} />
            ) : null}
          </div>
        ) : null}
        {!small && audioCount > 1 ? (
          <div className={styles.anchor}>
            <button
              ref={audioRef}
              type="button"
              className={cx(styles.pill, menu === 'audio' && styles.pillOpen)}
              aria-label={`${t('player.ctl.audio')} ${audioLang}`}
              aria-haspopup="menu"
              aria-expanded={menu === 'audio'}
              onClick={() => {
                toggleMenu('audio');
              }}
            >
              <PIcon name="audio" size={16} />
              {audioLang === '' ? '—' : audioLang}
            </button>
            {menu === 'audio' ? (
              <AudioMenu controller={controller} anchor={audioEl} onClose={closeMenu} />
            ) : null}
          </div>
        ) : null}
        {!small ? <span className={styles.sep} aria-hidden="true" /> : null}
        <div className={styles.anchor}>
          <IconButton
            icon={hasTracks && !anyShown ? 'subsOff' : 'subs'}
            label={t('player.ctl.subtitles')}
            keys={['C']}
            on={anyShown}
            badge={count >= 2 ? count : undefined}
            buttonRef={subsRef}
            menu={{ expanded: menu === 'subtitles' }}
            onClick={() => {
              toggleMenu('subtitles');
            }}
          />
          {menu === 'subtitles' ? (
            <SubtitlesMenu controller={controller} anchor={subsEl} onClose={closeMenu} />
          ) : null}
        </div>
        {!small ? (
          <IconButton
            icon="transcript"
            label={t('player.ctl.transcript')}
            keys={['T']}
            on={panel === 'transcript'}
            pressed={panel === 'transcript'}
            onClick={() => {
              controller.openPanel('transcript');
            }}
          />
        ) : null}
        {!small ? (
          <IconButton icon="mini" label={t('player.ctl.mini')} keys={['I']} onClick={onMini} />
        ) : null}
        {small ? (
          <div className={styles.anchor}>
            <IconButton
              icon="more"
              label={t('player.ctl.more')}
              buttonRef={moreRef}
              menu={{ expanded: menu === 'more' }}
              onClick={() => {
                toggleMenu('more');
              }}
            />
            {menu === 'more' ? (
              <MoreMenu controller={controller} anchor={moreEl} onClose={closeMenu} onMini={onMini} />
            ) : null}
          </div>
        ) : null}
        <IconButton
          icon={fullscreen ? 'unfull' : 'full'}
          label={fullscreen ? t('player.ctl.exitFullscreen') : t('player.ctl.fullscreen')}
          keys={['F']}
          onClick={onFullscreen}
        />
      </div>
    </div>
  );
}

export function speedText(speed: number): string {
  return `${String(Math.round(speed * 100) / 100)}×`;
}

function Time({ controller, small }: { controller: PlayerController; small: boolean }): React.JSX.Element {
  const duration = usePlayer((s) => s.duration);
  const [now, setNow] = useState(0);
  const [left, setLeft] = useState(false);
  const last = useRef(-1);
  useEffect(
    () =>
      controller.onTick((time) => {
        const s = Math.floor(time);
        if (s !== last.current) {
          last.current = s;
          setNow(time);
        }
      }),
    [controller],
  );
  // No total under 560 px (§6.9).
  const narrow = usePlayer((s) => s.small) && typeof window !== 'undefined' && window.innerWidth < 560;
  return (
    <button
      type="button"
      className={cx(styles.time, small && styles.timeSmall)}
      onClick={() => {
        setLeft((x) => !x);
      }}
      aria-label={left ? t('player.ctl.timeElapsed') : t('player.ctl.timeRemaining')}
    >
      <span aria-hidden="true">
        {left ? remaining(now, duration) : clock(now)}
        {narrow ? null : <span className={styles.total}> / {clock(duration)}</span>}
      </span>
    </button>
  );
}

function Chapter({ controller }: { controller: PlayerController }): React.JSX.Element | null {
  const chapters = usePlayer((s) => s.chapters);
  const [title, setTitle] = useState<string | null>(null);
  useEffect(
    () =>
      controller.onTick((time) => {
        const c = chapters.find((x) => time >= x.start && time < x.end);
        setTitle(c?.title ?? null);
      }),
    [controller, chapters],
  );
  if (title === null || title === '') return null;
  return <div className={styles.chapter}>{title}</div>;
}

interface VolumeProps {
  controller: PlayerController;
  small: boolean;
  menuOpen: boolean;
  buttonRef: (el: HTMLButtonElement | null) => void;
  anchor: HTMLButtonElement | null;
  onToggleMenu: () => void;
  onCloseMenu: () => void;
}

function Volume({
  controller,
  small,
  menuOpen,
  buttonRef,
  anchor,
  onToggleMenu,
  onCloseMenu,
}: VolumeProps): React.JSX.Element {
  const volume = usePlayer((s) => s.prefs.volume);
  const muted = usePlayer((s) => s.prefs.muted);
  const icon = muted || volume === 0 ? 'volMute' : volume < 0.5 ? 'volLow' : 'vol';
  return (
    <div className={cx(styles.vol, styles.anchor)}>
      <IconButton
        icon={icon}
        label={small ? t('player.ctl.volume') : muted ? t('player.ctl.unmute') : t('player.ctl.mute')}
        keys={small ? ['↑', '↓'] : ['M']}
        buttonRef={buttonRef}
        {...(small ? { menu: { expanded: menuOpen } } : {})}
        onClick={() => {
          if (small) onToggleMenu();
          else controller.toggleMute();
        }}
      />
      {!small ? <VolumeSlider controller={controller} /> : null}
      {small && menuOpen ? (
        <VolumeMenu controller={controller} anchor={anchor} onClose={onCloseMenu} />
      ) : null}
    </div>
  );
}

/** The wheel's pixels for one volume step: one notch of a mouse wheel (about 100 px in WebKit and Chromium) is one step. */
export const WHEEL_STEP_PX = 100;
/** A wheel that counts in lines: a line's pixels. */
const WHEEL_LINE_PX = 40;

/** The 92 px slider: 0–200%, a notch at 100%, gold above it (§6.3). */
export function VolumeSlider({ controller }: { controller: PlayerController }): React.JSX.Element {
  const volume = usePlayer((s) => s.prefs.volume);
  const muted = usePlayer((s) => s.prefs.muted);
  const boost = usePlayer(boostHere);
  const max = boost ? MAX_VOLUME : 1;
  const ref = useRef<HTMLDivElement>(null);
  const [drag, setDrag] = useState(false);
  const [tip, setTip] = useState(false);
  const shown = muted ? 0 : Math.min(volume, max);
  const frac = shown / MAX_VOLUME;
  const pct = Math.round(shown * 100);
  const at = (clientX: number): number => {
    const el = ref.current;
    if (el === null) return volume;
    const r = el.getBoundingClientRect();
    return Math.max(0, Math.min(max, ((clientX - r.left) / r.width) * MAX_VOLUME));
  };
  const onKey = (e: KeyboardEvent<HTMLDivElement>): void => {
    let next: number | undefined;
    if (e.key === 'ArrowUp' || e.key === 'ArrowRight') next = volume + VOLUME_STEP;
    else if (e.key === 'ArrowDown' || e.key === 'ArrowLeft') next = volume - VOLUME_STEP;
    else if (e.key === 'Home') next = 0;
    else if (e.key === 'End') next = max;
    if (next === undefined) return;
    e.preventDefault();
    e.stopPropagation();
    // A held key stops at 100% once; a fresh press goes on into boost.
    if (e.repeat && volume <= 1 && next > 1) next = 1;
    controller.setVolume(next);
  };
  // A step per notch of a wheel: a trackpad sends dozens of tiny deltas (and momentum after the
  // fingers lift), which at a step each took the sound to nothing in one flick.
  const wheel = useRef(0);
  const onWheel = (e: WheelEvent<HTMLDivElement>): void => {
    wheel.current += e.deltaMode === 1 ? e.deltaY * WHEEL_LINE_PX : e.deltaY;
    const steps = Math.trunc(wheel.current / WHEEL_STEP_PX);
    if (steps === 0) return;
    wheel.current -= steps * WHEEL_STEP_PX;
    controller.setVolume(volume - steps * VOLUME_STEP);
  };
  return (
    <div
      ref={ref}
      className={styles.vslider}
      role="slider"
      tabIndex={0}
      aria-label={t('player.ctl.volume')}
      aria-valuemin={0}
      aria-valuemax={Math.round(max * 100)}
      aria-valuenow={pct}
      aria-valuetext={
        pct > 100 ? t('player.ctl.volumeBoostValue', { pct }) : t('player.ctl.volumeValue', { pct })
      }
      onKeyDown={onKey}
      onWheel={onWheel}
      onPointerEnter={() => {
        setTip(true);
      }}
      onPointerLeave={() => {
        if (!drag) setTip(false);
      }}
      onFocus={() => {
        setTip(true);
      }}
      onBlur={() => {
        setTip(false);
      }}
      onPointerDown={(e) => {
        e.currentTarget.setPointerCapture(e.pointerId);
        setDrag(true);
        controller.setVolume(at(e.clientX));
      }}
      onPointerMove={(e) => {
        if (drag) controller.setVolume(at(e.clientX));
      }}
      onPointerUp={() => {
        setDrag(false);
      }}
    >
      <div className={styles.vfill} style={{ width: `${String(Math.min(frac, 0.5) * 100)}%` }} />
      {frac > 0.5 ? (
        <div className={styles.vboost} style={{ width: `${String((frac - 0.5) * 100)}%` }} />
      ) : null}
      <i className={styles.notch} aria-hidden="true" />
      <i className={styles.vknob} style={{ left: `${String(frac * 100)}%` }} aria-hidden="true" />
      {tip ? (
        <span className={styles.vtip} aria-hidden="true">
          {t('player.ctl.volumeTip', { pct })}
          {pct > 100 ? (
            <>
              {' · '}
              <span className={styles.boostWord}>{t('player.ctl.boost')}</span>
            </>
          ) : null}
        </span>
      ) : null}
    </div>
  );
}
