/**
 * What the Player tells the operators (activity contract §9 "Video", §10):
 * a video opened (its container kind, video codec, how it plays, how many
 * subtitles; never a file name), the minutes actually watched, an error's
 * stage, how often subtitles had to be moved in time, a subtitle whose
 * encoding was repaired, and the next episode taken. Counts only, through
 * `signal` (`lib/surface.ts`), so nothing leaves before the server takes it.
 */
import { activityOn, signal } from '@/lib/surface.js';
import type { Playback } from '@/lib/platform/media.js';
import { WatchMeter } from './model/watchMeter.js';

/** How often watched minutes are reported while a video plays (§9: every 10 min and on close). */
export const WATCH_REPORT_MS = 10 * 60_000;

/** The container's kind, as people name files: never more than a short slug. */
export function containerKind(container: string): string {
  const first = (container.split(',')[0] ?? '').trim().toLowerCase();
  const named: Record<string, string> = {
    matroska: 'mkv',
    mov: 'mp4',
    mp4: 'mp4',
    avi: 'avi',
    mpegts: 'ts',
    webm: 'webm',
    flv: 'flv',
    ogg: 'ogg',
    asf: 'wmv',
    mpeg: 'mpg',
  };
  const kind = named[first] ?? first;
  return /^[a-z0-9]{1,16}$/.test(kind) ? kind : 'other';
}

/** A codec name as a short slug (h264, hevc, av1, vp9…), or other. */
export function codecClass(codec: string | undefined): string | undefined {
  if (codec === undefined) return undefined;
  const slug = codec.trim().toLowerCase();
  return /^[a-z0-9_]{1,16}$/.test(slug) ? slug : 'other';
}

export class PlayerActivity {
  private readonly meter = new WatchMeter();
  private offsets = 0;
  private fixed = new Set<string>();
  private codec: string | undefined;
  private timer: ReturnType<typeof setInterval> | undefined;

  /** A video began: what kind of file, never which. */
  opened(p: Playback, subtitles: number): void {
    this.closed();
    // The switch off: no timer, nothing counted (the app as it was).
    if (!activityOn()) return;
    this.codec = codecClass(p.info.video[0]?.codec);
    const n = Math.max(0, Math.min(10, subtitles));
    signal({
      name: 'player.open',
      context: containerKind(p.info.container),
      meta: {
        container: containerKind(p.info.container),
        ...(this.codec === undefined ? {} : { codec: this.codec }),
        mode: p.mode === 'direct' || p.mode === 'remux' ? p.mode : 'transcode',
        hasSubs: n > 0,
        nSubs: n,
      },
    });
    this.timer = setInterval(() => {
      this.report();
    }, WATCH_REPORT_MS);
  }

  /** The playhead moved (timeupdate): counted only while it plays and the window is shown. */
  tick(video: HTMLVideoElement): void {
    if (this.timer === undefined) return;
    this.meter.tick(
      video.currentTime,
      !video.paused && !video.ended && document.visibilityState !== 'hidden',
      video.playbackRate,
    );
  }

  /** A seek or a new run: the next step starts from there. */
  jumped(): void {
    this.meter.reset();
  }

  failed(stage: string): void {
    signal({
      name: 'player.error',
      meta: { stage, ...(this.codec === undefined ? {} : { codec: this.codec }) },
    });
  }

  /** The learner moved a subtitle in time (a nudge or a sync). */
  offsetMoved(): void {
    this.offsets += 1;
  }

  /** A subtitle whose text encoding the engine repaired, once per track. */
  encodingFixed(trackKey: string): void {
    if (this.fixed.has(trackKey)) return;
    this.fixed.add(trackKey);
    signal({ name: 'player.sub_fix_encoding' });
  }

  nextEpisode(): void {
    signal({ name: 'player.next_episode' });
  }

  /** Whole minutes watched since the last report, if any. */
  report(): void {
    const minutes = this.meter.take();
    if (minutes > 0) signal({ name: 'player.watch', n: minutes, meta: { minutes } });
  }

  /** The video closed (another opens, the window closes): what is left is reported. */
  closed(): void {
    clearInterval(this.timer);
    this.timer = undefined;
    this.report();
    if (this.offsets > 0)
      signal({ name: 'player.sub_offset', n: this.offsets, meta: { changes: this.offsets } });
    this.offsets = 0;
    this.fixed = new Set();
    this.meter.reset();
  }
}
