/**
 * "I just heard this line" (spec §8.1, mock-up 10): H froze "now" and paused;
 * this lists the five lines around it with their start times. Choosing one
 * shows how far the track moves ("+1.8 s"); the button moves it, with Undo
 * in the notice corner. ↑ / ↓ and Enter in the list; Escape cancels and plays on.
 */
import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from 'react';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import type { PlayerController } from '../controller.js';
import { aroundIndices, nearestIndex, offsetToStartNow } from '../model/cues.js';
import { languageName } from '../model/languages.js';
import { clock, clockTenths, offsetLabel } from '../model/time.js';
import { trackIn, usePlayer } from '../store.js';
import styles from './Sync.module.css';

export function SyncPicker({ controller }: { controller: PlayerController }): React.JSX.Element | null {
  const sync = usePlayer((s) => s.sync);
  // A fresh picker for every press of H: its choice starts on the nearest line.
  return sync === null ? null : <Picker key={sync.at} controller={controller} />;
}

function Picker({ controller }: { controller: PlayerController }): React.JSX.Element | null {
  const sync = usePlayer((s) => s.sync);
  const track = usePlayer((s) => (s.sync === null ? undefined : trackIn(s, s.sync.slot)));
  const panelOpen = usePlayer((s) => s.panel !== null);
  const rows = useMemo(
    () => (sync === null || track === undefined ? [] : aroundIndices(track.cues, sync.at, track.offsetMs)),
    [sync, track],
  );
  const nearest =
    sync === null || track === undefined ? -1 : nearestIndex(track.cues, sync.at, track.offsetMs);
  const [chosen, setChosen] = useState(nearest);
  const listRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    listRef.current?.querySelector<HTMLElement>('[aria-selected="true"]')?.focus();
  }, [chosen]);
  if (sync === null || track === undefined) return null;
  const cue = track.cues[chosen];
  const move = cue === undefined ? 0 : offsetToStartNow(cue, sync.at) - track.offsetMs;
  const onKey = (e: KeyboardEvent<HTMLDivElement>): void => {
    const at = rows.indexOf(chosen);
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      e.stopPropagation();
      setChosen(rows[Math.min(rows.length - 1, at + 1)] ?? chosen);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      e.stopPropagation();
      setChosen(rows[Math.max(0, at - 1)] ?? chosen);
    } else if (e.key === 'Enter' && cue !== undefined) {
      e.preventDefault();
      e.stopPropagation();
      controller.applySync(cue);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      controller.cancelSync();
    }
  };
  return (
    <>
      <div className={styles.dim} aria-hidden="true" />
      <div
        className={cx(styles.pop, panelOpen && styles.besidePanel)}
        role="dialog"
        aria-label={t('player.sync.title')}
        onKeyDown={onKey}
        data-player-overlay=""
      >
        <div className={styles.head}>
          <div className={styles.title}>{t('player.sync.title')}</div>
          <div className={styles.sub}>
            {t('player.sync.sub', {
              n: sync.slot,
              lang: languageName(track.lang),
              time: clockTenths(sync.at / 1000),
            })}
          </div>
        </div>
        {rows.length === 0 ? <p className={styles.sub}>{t('player.sync.noLines')}</p> : null}
        <div ref={listRef} role="listbox" aria-label={t('player.sync.title')}>
          {rows.map((i) => {
            const c = track.cues[i];
            if (c === undefined) return null;
            const on = i === chosen;
            return (
              <div
                key={i}
                role="option"
                aria-selected={on}
                tabIndex={on ? 0 : -1}
                className={cx(styles.row, on && styles.on)}
                onClick={() => {
                  setChosen(i);
                }}
                onDoubleClick={() => {
                  controller.applySync(c);
                }}
              >
                <span className={styles.time}>{clock((c.start + track.offsetMs) / 1000)}</span>
                <span className={styles.text} dir="auto">
                  {c.text.replace(/\s+/g, ' ')}
                </span>
                {on ? <span className={styles.chip}>{offsetLabel(move)}</span> : null}
              </div>
            );
          })}
        </div>
        <div className={styles.actions}>
          <button
            type="button"
            className={styles.cancel}
            onClick={() => {
              controller.cancelSync();
            }}
          >
            {t('action.cancel')}
          </button>
          <button
            type="button"
            className={styles.primary}
            disabled={cue === undefined}
            onClick={() => {
              if (cue !== undefined) controller.applySync(cue);
            }}
          >
            {t('player.sync.move', { offset: offsetLabel(move) })}
          </button>
        </div>
      </div>
    </>
  );
}
