/**
 * Minutes actually watched (§9 `player.watch`, §10 "real playback
 * progress"): the sum of the playhead's forward steps while the video plays
 * and somebody is looking, never the wall clock. A step longer than
 * `MAX_STEP_S` (a seek forward, a laptop waking with the video still
 * "playing") or backwards (a seek back, a loop) is not watching and counts
 * nothing; paused, hidden or asleep counts nothing.
 */

/** The longest forward step taken as watching: timeupdate fires about four times a second. */
export const MAX_STEP_S = 2.5;
/** The most one report may claim (§10: player.watch ≤ 15 min per event). */
export const MAX_REPORT_MINUTES = 15;

export class WatchMeter {
  private last: number | undefined;
  private seconds = 0;

  /** The playhead now (element seconds), and whether this moment counts. */
  tick(currentTime: number, counting: boolean, rate = 1): void {
    const last = this.last;
    this.last = currentTime;
    if (!counting || last === undefined) return;
    const step = currentTime - last;
    if (step > 0 && step <= MAX_STEP_S * Math.max(1, rate)) this.seconds += step / Math.max(rate, 0.25);
  }

  /** The playhead jumped (seek, a new file): the next tick starts from there. */
  reset(): void {
    this.last = undefined;
  }

  /** Whole minutes watched since the last report, at most `MAX_REPORT_MINUTES`; the rest waits. */
  take(): number {
    const minutes = Math.min(MAX_REPORT_MINUTES, Math.floor(this.seconds / 60));
    this.seconds -= minutes * 60;
    return minutes;
  }

  /** Seconds waiting to make a minute, for tests. */
  pending(): number {
    return this.seconds;
  }
}
