/**
 * Click a word and the Lexpad card opens over the paused video (spec §10,
 * mock-ups 13 and 14): the desktop card's and the extension's content —
 * the meaning when it comes back, the line as "Seen in The Terrace · S1 E3 ·
 * 26:58", the notebook — pointing at the word with a caret, never covering
 * it. Signed out, its actions ask for sign-in at the first save; "Not now"
 * keeps the word on this computer until then (§24.7).
 */
import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties } from 'react';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { AppleMark, GoogleMark } from '@/components/ui/Icon.js';
import type { LanguageCode } from '@lexpad/core';
import { notebooks as notebooksApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { TARGET_LANGUAGES } from '@/features/settings/data.js';
import type { PlayerAccount, PlayerCard, PlayerNotebook } from '@/lib/platform/types.js';
import type { PlayerController } from '../controller.js';
import { compose, reportFragment } from '../model/compose.js';
import { isRtlText } from '../model/cues.js';
import { languageName } from '../model/languages.js';
import { baseLang, parallelTranslation, routeWord, type WordRoute } from '../model/route.js';
import { localDay } from '../model/prefs.js';
import type { SlotNumber } from '../model/slots.js';
import { placeCard, type CardPlace } from '../model/cardPlace.js';
import { asHeadword, contextHint, seenIn } from '../model/words.js';
import { clock } from '../model/time.js';
import { nextNoticeId, updatePrefs, usePlayer, type CardRequest } from '../store.js';
import { LanguageSelect } from './DropPrompt.js';
import { LexpadMark, PIcon } from './icons.js';
import styles from './Card.module.css';

/** The selected subtitle words' rectangle as laid out now, or null (a transcript pick, or gone). */
function liveAnchor(request: CardRequest): { x: number; y: number; w: number; h: number } | null {
  if (request.from !== 'subtitles') return null;
  const els = document.querySelectorAll<HTMLElement>(`[data-slot="${String(request.slot)}"] [data-selected]`);
  if (els.length === 0) return null;
  const rs = Array.from(els, (e) => e.getBoundingClientRect());
  const x = Math.min(...rs.map((r) => r.left));
  const y = Math.min(...rs.map((r) => r.top));
  return {
    x,
    y,
    w: Math.max(...rs.map((r) => r.right)) - x,
    h: Math.max(...rs.map((r) => r.bottom)) - y,
  };
}

/**
 * Below this Player height the word card is the compact one (uiux build review
 * M4, 26 Oct 2026: at 640×360 the whole card could not fit beside the lines).
 */
export const COMPACT_BELOW_PX = 420;

function useCompactPlayer(): boolean {
  const [compact, setCompact] = useState(() => window.innerHeight < COMPACT_BELOW_PX);
  useEffect(() => {
    const on = (): void => {
      setCompact(window.innerHeight < COMPACT_BELOW_PX);
    };
    window.addEventListener('resize', on);
    return () => {
      window.removeEventListener('resize', on);
    };
  }, []);
  return compact;
}

/** The card's width, and how far it keeps from the word and the window's edges (§10). */
const CARD_W = 344;

const GAP = 12;
const EDGE = 12;
/** "Added" (with its tick) stays this long before the card closes (§10). */
export const ADDED_MS = 900;
/** From this save on in a session, only the seek bar's dot and the badge change (§24.3). */
export const QUIET_FROM_SAVE = 4;

type Phase =
  | { kind: 'pick' }
  | { kind: 'loading' }
  | { kind: 'ready'; card: PlayerCard | undefined; note?: string }
  | { kind: 'signin'; waiting: boolean; note?: string }
  | { kind: 'added'; everywhere: boolean }
  | { kind: 'kept' }
  /** The engine is not sure which language the line is in: the learner says (pre-filled with its guess). */
  | { kind: 'askLang'; detected: string | undefined }
  /**
   * The line is in a language none of the notebooks learns: said plainly,
   * with a notebook in it to start; never saved into another language's.
   */
  | {
      kind: 'otherLang';
      route: Extract<WordRoute, { kind: 'otherLanguage' }>;
      creating: boolean;
      note?: string;
      /** The word already waits in the core's queue (it was held through sign-in). */
      queued: boolean;
      /** A plan that keeps one notebook: the way to see it in Lexpad. */
      plan?: boolean;
    };

function meaningField(phase: Phase): { meaning?: string } {
  const meaning = phase.kind === 'ready' ? phase.card?.meanings?.[0]?.meaning : undefined;
  return meaning === undefined ? {} : { meaning };
}

function failureWord(cause: unknown): string {
  return typeof cause === 'string' ? cause : cause instanceof Error ? cause.message : 'error';
}

export function AddWordCard({
  controller,
  request,
}: {
  controller: PlayerController;
  request: CardRequest;
}): React.JSX.Element {
  const host = controller.host;
  // Where the word was picked: the core counts it as desktop.player or desktop.player.transcript.
  const pickedIn = request.from ?? 'subtitles';
  const ref = useRef<HTMLDivElement>(null);
  const addRef = useRef<HTMLButtonElement>(null);
  const [headword, setHeadword] = useState<string | null>(request.headword);
  const [phase, setPhase] = useState<Phase>(
    request.headword === null ? { kind: 'pick' } : { kind: 'loading' },
  );
  const [account, setAccount] = useState<PlayerAccount | null>(null);
  const [notebookId, setNotebookId] = useState<string | null>(null);
  /** The notebooks in the line's language: the card's switcher never offers another language's. */
  const [choices, setChoices] = useState<PlayerNotebook[]>([]);
  /** The line's language; once the learner says it, sure. */
  const [lang, setLang] = useState<string | undefined>(baseLang(request.lang));
  const [langSure, setLangSure] = useState(false);
  /** Read the account and route again (after a notebook was started). */
  const [round, setRound] = useState(0);
  const queuedRef = useRef(false);
  const [adding, setAdding] = useState(false);
  const [pos, setPos] = useState<CardPlace | null>(null);
  const [capped, setCapped] = useState(false);
  const [relayout, setRelayout] = useState(0);
  // A Player under COMPACT_BELOW_PX tall shows the compact card: the headword,
  // the meaning, where it was seen and the buttons; the rest behind "More".
  const compact = useCompactPlayer();
  const [more, setMore] = useState(false);
  const [tight, setTight] = useState(false);
  const full = !(compact || tight) || more;
  const bodyRef = useRef<HTMLDivElement>(null);
  const signInAskDay = usePlayer((s) => s.prefs.signInAskDay);
  const parts = controller.seenInParts(request.at);
  const memo = seenIn(parts.title, parts.episode, parts.time);
  const fromLabel = `${t('player.card.seenIn')} ${[parts.title, parts.episode, clock(request.at)].filter((x) => x !== undefined && x !== '').join(' · ')}`;

  const close = (): void => {
    usePlayer.setState({ card: null });
  };

  const saved = (word: string, everywhere: boolean, id: string | null, nbTitle: string | undefined): void => {
    const s = usePlayer.getState();
    const saves = s.saves + 1;
    usePlayer.setState({
      saves,
      unseen: s.unseen + 1,
      dots: [
        ...s.dots,
        {
          at: request.at,
          word,
          id: nextNoticeId(),
          ...(id !== null ? { wordId: id } : {}),
          ...meaningField(phase),
        },
      ],
    });
    controller.markHint('word');
    setPhase({ kind: 'added', everywhere });
    window.setTimeout(() => {
      close();
      if (saves < QUIET_FROM_SAVE) {
        controller.notice({
          text: t('player.notice.added'),
          strong: word,
          tail: t('player.notice.addedTo', { notebook: nbTitle ?? languageName(request.lang) }),
          icon: 'check',
          action: {
            label: t('player.notice.seeInNotebook'),
            run: () => {
              usePlayer.setState({ unseen: 0 });
              void host.openLexpad(id === null ? undefined : `/words/${id}`);
            },
          },
        });
      }
    }, ADDED_MS);
  };

  // What the core knows: signed in or not, the notebooks; then the meaning.
  useEffect(() => {
    if (headword === null) return;
    const life = { live: true };
    const alive = (): boolean => life.live;
    void (async () => {
      let acc: PlayerAccount;
      try {
        acc = await host.account();
      } catch {
        acc = { connected: false, notebooks: [], notebookId: null };
      }
      if (!life.live) return;
      setAccount(acc);
      const route = routeWord({
        lang,
        confidence: langSure ? 1 : (request.langConfidence ?? 1),
        notebooks: acc.connected ? acc.notebooks : [],
        lastUsed: acc.notebookId,
        own: controller.getLanguages().own,
      });
      if (route.kind === 'askLanguage') {
        setPhase({ kind: 'askLang', detected: route.detected });
        return;
      }
      if (!acc.connected) {
        const askedToday = signInAskDay === localDay(new Date());
        setPhase(
          askedToday
            ? { kind: 'ready', card: undefined, note: t('player.card.keptHere') }
            : { kind: 'signin', waiting: false },
        );
        return;
      }
      if (route.kind === 'otherLanguage') {
        setPhase({ kind: 'otherLang', route, creating: false, queued: queuedRef.current });
        return;
      }
      const nb = route.notebook;
      setNotebookId(nb.id);
      setChoices(route.choices);
      if (queuedRef.current) {
        // A word held through sign-in now has its notebook: the core sends it.
        queuedRef.current = false;
        const sent = await host.words.flush().catch(() => 0);
        if (!alive()) return;
        if (sent > 0) {
          saved(headword, true, null, nb.title);
          return;
        }
      }
      setPhase({ kind: 'loading' });
      try {
        const card = await host.lookup(nb.id, headword, contextHint(request.sentence), pickedIn);
        if (alive()) setPhase({ kind: 'ready', card });
      } catch (cause) {
        if (!alive()) return;
        const word = failureWord(cause);
        setPhase({
          kind: 'ready',
          card: undefined,
          note:
            word === 'offline'
              ? t('player.card.offline')
              : word === 'ai_unavailable' || word === 'limit'
                ? t('player.card.limit')
                : t('player.card.unavailable'),
        });
      }
    })();
    return () => {
      life.live = false;
    };
    // The request is fixed for the card's life; the language and the round are what change.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [headword, lang, langSure, round]);

  // Points at the word: above it when there is room, else below; 12 px from every
  // edge; never over a subtitle (`placeCard`), scrolling inside when it cannot fit.
  useLayoutEffect(() => {
    const el = ref.current;
    if (el === null) return;
    // The clicked words where they are now (they move with their box), else where they were clicked.
    const a = liveAnchor(request) ?? request.anchor;
    const avoid = Array.from(document.querySelectorAll<HTMLElement>('[data-slot]')).flatMap((b) => {
      const r = b.getBoundingClientRect();
      return r.width > 0 && r.height > 0
        ? [{ id: Number(b.dataset.slot), rect: { x: r.left, y: r.top, w: r.width, h: r.height } }]
        : [];
    });
    // The natural height (border box), whatever cap the card has now: the
    // body's whole content in place of the part of it shown.
    const body = bodyRef.current;
    const natural = el.offsetHeight + (body === null ? 0 : body.scrollHeight - body.clientHeight);
    const next = placeCard({
      anchor: a,
      card: { w: CARD_W, h: natural },
      view: { w: window.innerWidth, h: window.innerHeight },
      avoid,
      gap: GAP,
      edge: EDGE,
      // The bars' buttons on screen (the top bar's Lexpad, the caption buttons…).
      controls: Array.from(document.querySelectorAll<HTMLElement>('[data-chrome-zone] button')).flatMap(
        (b) => {
          const r = b.getBoundingClientRect();
          return r.width > 0 && r.height > 0 && getComputedStyle(b).visibility !== 'hidden'
            ? [{ x: r.left, y: r.top, w: r.width, h: r.height }]
            : [];
        },
      ),
    });
    setPos((p) =>
      p !== null &&
      p.left === next.left &&
      p.top === next.top &&
      p.caret === next.caret &&
      p.below === next.below &&
      p.maxH === next.maxH &&
      p.covered.join() === next.covered.join()
        ? p
        : next,
    );
    const short = next.maxH < natural - 0.5;
    setCapped(short);
    // The full card becomes the compact one only when it cannot fit the window
    // at all (taller than the Player less 24 px; build review p1); a card that
    // only needs to scroll beside the lines stays full. "More" opens the rest.
    if (full && !more && natural > window.innerHeight - 2 * EDGE) setTight(true);
  }, [phase, account, request.anchor, relayout, full, more]);

  // The subtitles can move while the card is open (the window resized, a track
  // shown or hidden, a notice stepping a top track down, the bars' lift): the
  // card is placed again whenever a box moves, once a frame at most (code review F4).
  useEffect(() => {
    let frame = 0;
    const again = (): void => {
      if (frame !== 0) return;
      frame = window.requestAnimationFrame(() => {
        frame = 0;
        setRelayout((n) => n + 1);
      });
    };
    const layer = document.querySelector('[data-subtitle-layer]');
    const mo = new MutationObserver(again);
    if (layer !== null)
      mo.observe(layer, { subtree: true, childList: true, attributes: true, attributeFilter: ['style'] });
    window.addEventListener('resize', again);
    return () => {
      mo.disconnect();
      window.removeEventListener('resize', again);
      window.cancelAnimationFrame(frame);
    };
  }, []);

  // In a very small window the tracks the card would cover step aside while it is open.
  const covered = pos?.covered.join() ?? '';
  useEffect(() => {
    const slots = covered === '' ? [] : covered.split(',').map(Number);
    usePlayer.setState({ stepAside: slots as SlotNumber[] });
    return () => {
      usePlayer.setState({ stepAside: [] });
    };
  }, [covered]);

  // Focus goes to "Add to Lexpad" when it is there; Escape closes; a click outside closes.
  useEffect(() => {
    addRef.current?.focus({ preventScroll: true });
  }, [phase.kind]);

  const notebooks = account?.notebooks ?? [];
  const notebook = notebooks.find((n) => n.id === notebookId);

  const add = async (): Promise<void> => {
    if (headword === null || adding) return;
    setAdding(true);
    try {
      if (account?.connected === true && notebookId !== null) {
        const card = phase.kind === 'ready' ? phase.card : undefined;
        const translation = parallelTranslation(request.parallel ?? [], notebook?.meaningLang);
        const id = await host.addWord(
          notebookId,
          compose(headword, request.sentence, memo, card, translation),
          pickedIn,
        );
        // The notebook used last is the one the next word in this language goes to.
        if (notebookId !== account.notebookId) void host.setNotebook(notebookId).catch(() => undefined);
        saved(headword, true, id, notebook?.title);
        return;
      }
      // Signed out ("Not now" earlier today): kept on this computer.
      const result = await host.words.save({
        headword,
        from: pickedIn,
        ...(lang ? { lang } : {}),
        sentence: request.sentence,
        memo,
      });
      if (result.status === 'added') saved(headword, true, result.id, undefined);
      else {
        usePlayer.setState({ pending: result.pending });
        setPhase({ kind: 'kept' });
        window.setTimeout(close, ADDED_MS * 2);
      }
    } catch (cause) {
      const word = failureWord(cause);
      setAdding(false);
      setPhase({
        kind: 'ready',
        card: phase.kind === 'ready' ? phase.card : undefined,
        note:
          word === 'duplicate'
            ? t('player.card.duplicate')
            : word === 'no_notebook'
              ? t('player.card.noNotebook')
              : word === 'no_notebook_for_language'
                ? t('player.card.noNotebookForLanguage')
                : word === 'offline'
                  ? t('player.card.offlineAdd')
                  : t('player.card.failed'),
      });
    }
  };

  useEffect(() => {
    const onKey = (e: KeyboardEvent): void => {
      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        close();
      } else if (
        e.key === 'Enter' &&
        phase.kind === 'ready' &&
        !adding &&
        document.activeElement?.tagName !== 'SELECT'
      ) {
        if (document.activeElement === addRef.current || !ref.current?.contains(document.activeElement)) {
          e.preventDefault();
          e.stopPropagation();
          void add();
        }
      }
    };
    const outside = (e: PointerEvent): void => {
      const target = e.target as HTMLElement;
      if (ref.current?.contains(target) === true) return;
      // A click on another word opens that word's card instead.
      if (target.closest('[data-tok]') !== null) return;
      close();
    };
    window.addEventListener('keydown', onKey, true);
    document.addEventListener('pointerdown', outside, true);
    return () => {
      window.removeEventListener('keydown', onKey, true);
      document.removeEventListener('pointerdown', outside, true);
    };
  });

  const signIn = async (provider: 'google' | 'apple' | undefined): Promise<void> => {
    if (headword === null) return;
    setPhase({ kind: 'signin', waiting: true });
    try {
      await host.connect(provider);
      // Signed in: the held word goes in through the normal path.
      const result = await host.words.save({
        headword,
        from: pickedIn,
        ...(lang ? { lang } : {}),
        sentence: request.sentence,
        memo,
      });
      if (result.status === 'added') saved(headword, true, result.id, undefined);
      else if (result.reason === 'no_notebook_for_language') {
        // No notebook learns this language: the card asks, and the word waits until one does.
        usePlayer.setState({ pending: result.pending });
        queuedRef.current = true;
        setRound((r) => r + 1);
      } else {
        setPhase({ kind: 'kept' });
        window.setTimeout(close, ADDED_MS * 2);
      }
    } catch (cause) {
      const word = failureWord(cause);
      setPhase({
        kind: 'signin',
        waiting: false,
        note: word === 'cancelled' ? t('player.card.signInCancelled') : t('player.card.signInFailed'),
      });
    }
  };

  const notNow = async (): Promise<void> => {
    if (headword === null) return;
    updatePrefs((p) => ({ ...p, signInAskDay: localDay(new Date()) }));
    try {
      const result = await host.words.save({
        headword,
        from: pickedIn,
        ...(lang ? { lang } : {}),
        sentence: request.sentence,
        memo,
      });
      if (result.status === 'queued') usePlayer.setState({ pending: result.pending });
      setPhase({ kind: 'kept' });
      usePlayer.setState((s) => ({
        dots: [...s.dots, { at: request.at, word: headword, id: nextNoticeId() }],
      }));
      window.setTimeout(close, ADDED_MS * 2);
    } catch {
      setPhase({ kind: 'signin', waiting: false, note: t('player.card.failed') });
    }
  };

  /** The learner says which language the line is in; the track keeps it. */
  const confirmLang = (code: string): void => {
    setLang(code);
    setLangSure(true);
    const id = request.trackId;
    if (id !== undefined) {
      usePlayer.setState((s) => {
        const tr = s.tracks[id];
        return tr === undefined
          ? {}
          : { tracks: { ...s.tracks, [id]: { ...tr, lang: code, langConfidence: 1 } } };
      });
    }
    setPhase({ kind: 'loading' });
  };

  /** Starts a notebook in the line's language, then routes the word again: it now has a home. */
  const startNotebook = async (): Promise<void> => {
    if (phase.kind !== 'otherLang' || phase.creating) return;
    const { route } = phase;
    setPhase({ kind: 'otherLang', route, creating: true, queued: phase.queued });
    try {
      const made = await notebooksApi.create({
        title: t('newNotebook.namePlaceholder', { target: languageName(route.start.targetLang) }),
        targetLang: route.start.targetLang as LanguageCode,
        meaningLang: route.start.meaningLang as LanguageCode,
      });
      await host.setNotebook(made.id).catch(() => undefined);
      setPhase({ kind: 'loading' });
      setRound((r) => r + 1);
    } catch (cause) {
      setPhase({
        ...phase,
        creating: false,
        plan: isApiError(cause, 'needsPayment'),
        note: isApiError(cause, 'needsPayment')
          ? t('player.card.notebookPlan')
          : isApiError(cause, 'offline')
            ? t('player.card.offlineAdd')
            : t('player.card.notebookFailed'),
      });
    }
  };

  const cardData = phase.kind === 'ready' ? phase.card : undefined;
  const meta = cardData
    ? [
        cardData.correction && cardData.correction !== headword ? cardData.correction : null,
        cardData.pos,
        cardData.level,
        cardData.pronunciation,
      ]
        .filter((v): v is string => typeof v === 'string' && v !== '')
        .join(' · ')
    : phase.kind === 'loading'
      ? t('player.card.looking')
      : '';
  const style: CSSProperties =
    pos === null
      ? { visibility: 'hidden', left: 0, top: 0 }
      : { left: pos.left, top: pos.top, maxHeight: pos.maxH };
  const senses = (cardData?.meanings ?? []).slice(0, 2);

  return (
    <>
      <div
        ref={ref}
        className={cx(styles.card, capped && styles.capped, !full && styles.compact)}
        style={style}
        role="dialog"
        aria-label={t('player.card.label', { word: headword ?? request.sentence })}
        data-player-overlay=""
      >
        <div className={styles.head}>
          <span className={styles.mark}>
            <LexpadMark size={16} />
          </span>
          <div className={styles.titles}>
            <div className={styles.word} dir="auto">
              {headword ?? t('player.card.pick')}
            </div>
            {meta !== '' ? <div className={styles.meta}>{meta}</div> : null}
            {phase.kind === 'pick' ? <div className={styles.meta}>{t('player.card.pickLead')}</div> : null}
          </div>
          <button type="button" className={styles.x} aria-label={t('player.card.close')} onClick={close}>
            <PIcon name="x" size={16} />
          </button>
        </div>

        <div ref={bodyRef} className={styles.body}>
          {phase.kind === 'pick' && request.pickFrom !== undefined ? (
            <Picker
              words={request.pickFrom}
              onPick={(w) => {
                setHeadword(w);
                setPhase({ kind: 'loading' });
              }}
            />
          ) : null}

          {phase.kind === 'loading' ? (
            <div className={styles.skel} aria-hidden="true">
              <span className={styles.bar60} />
              <span className={styles.bar90} />
            </div>
          ) : null}

          {(full ? senses : senses.slice(0, 1)).map((sense, i) => (
            <div key={i} className={styles.sense}>
              <div className={styles.meaning} dir={isRtlText(sense.meaning) ? 'rtl' : 'ltr'}>
                {sense.meaning}
              </div>
              {sense.gloss && full ? (
                <div className={styles.gloss} dir="auto">
                  {sense.gloss}
                </div>
              ) : null}
              {sense.examples?.[0] && i === 0 && full ? (
                <div className={styles.ex} dir="auto">
                  “{sense.examples[0].sentence}”
                </div>
              ) : null}
            </div>
          ))}
          {cardData !== undefined && senses.length === 0 ? (
            <p className={styles.note}>{t('player.card.noMeaning')}</p>
          ) : null}
          {cardData !== undefined && senses.length > 0 && full ? (
            <button
              type="button"
              className={styles.report}
              aria-label={t('player.card.reportLabel')}
              onClick={() => {
                if (headword !== null) void host.openReport(reportFragment(headword, cardData));
              }}
            >
              <PIcon name="flag" size={12} />
              {t('player.card.report')}
            </button>
          ) : null}

          {phase.kind !== 'pick' ? (
            <div className={cx(styles.from, !full && styles.fromShort)}>
              <b className={styles.fromLabel}>{fromLabel}</b>
              {/* The compact card names where; the line itself is on screen under it. */}
              {full ? <span dir="auto">{request.sentence}</span> : null}
              {!full && cardData !== undefined && senses.length > 0 ? (
                <button
                  type="button"
                  className={styles.more}
                  aria-expanded={false}
                  onClick={() => {
                    setMore(true);
                  }}
                >
                  {t('player.card.more')}
                </button>
              ) : null}
            </div>
          ) : null}

          {phase.kind === 'ready' && account?.connected === true && choices.length > 1 && full ? (
            <label className={styles.nb}>
              {t('player.card.notebook')}
              <span className={styles.selectWrap}>
                <select
                  className={styles.select}
                  value={notebookId ?? ''}
                  onChange={(e) => {
                    setNotebookId(e.target.value);
                    void host.setNotebook(e.target.value);
                  }}
                >
                  {choices.map((n) => (
                    <option key={n.id} value={n.id}>
                      {n.title}
                    </option>
                  ))}
                </select>
                <PIcon name="cd" size={15} className={styles.chev} />
              </span>
            </label>
          ) : null}
          {phase.kind === 'ready' &&
          account?.connected === true &&
          choices.length === 1 &&
          notebook &&
          full ? (
            <div className={styles.nb}>
              {t('player.card.notebook')}
              <span className={styles.nbName}>{notebook.title}</span>
            </div>
          ) : null}

          {phase.kind === 'askLang' ? (
            <div className={styles.ask}>
              <p className={styles.askLead}>
                {phase.detected === undefined
                  ? t('player.card.askLangUnknown')
                  : t('player.card.askLang', { lang: languageName(phase.detected) })}
              </p>
              <AskLanguage detected={phase.detected} onConfirm={confirmLang} onCancel={close} />
            </div>
          ) : null}

          {phase.kind === 'otherLang' ? (
            <div className={styles.ask} role="group" aria-label={t('player.card.otherLangLabel')}>
              <p className={styles.askLead}>
                {phase.route.inView === undefined
                  ? t('player.card.otherLangNone', { lang: languageName(phase.route.lang) })
                  : t('player.card.otherLang', {
                      lang: languageName(phase.route.lang),
                      target: languageName(phase.route.inView.targetLang),
                      meaning: languageName(phase.route.inView.meaningLang),
                    })}
              </p>
              {phase.note !== undefined ? <p className={styles.note}>{phase.note}</p> : null}
              <div className={styles.acts}>
                {TARGET_LANGUAGES.includes(phase.route.start.targetLang as LanguageCode) ? (
                  <button
                    ref={addRef}
                    type="button"
                    className={styles.primary}
                    disabled={phase.creating}
                    onClick={() => void startNotebook()}
                  >
                    {phase.creating
                      ? t('player.card.starting')
                      : t('player.card.startNotebook', {
                          lang: languageName(phase.route.start.targetLang),
                          meaning: languageName(phase.route.start.meaningLang),
                        })}
                  </button>
                ) : (
                  <p className={styles.note}>
                    {t('player.card.noSuchNotebook', { lang: languageName(phase.route.lang) })}
                  </p>
                )}
                {phase.plan === true ? (
                  <button
                    type="button"
                    className={styles.btn}
                    onClick={() => {
                      void host.openLexpad('/settings/plan');
                    }}
                  >
                    {t('player.card.seePlan')}
                  </button>
                ) : null}
                <button type="button" className={styles.btn} onClick={close}>
                  {t('player.card.cancel')}
                </button>
              </div>
            </div>
          ) : null}

          {phase.kind === 'ready' && phase.note !== undefined ? (
            <p className={styles.note}>{phase.note}</p>
          ) : null}

          {phase.kind === 'added' ? (
            <div className={styles.done} role="status">
              <PIcon name="check" size={18} />
              {phase.everywhere && account?.connected !== true
                ? t('player.card.addedEverywhere')
                : t('player.card.added')}
            </div>
          ) : null}
          {phase.kind === 'kept' ? (
            <div className={styles.done} role="status">
              <PIcon name="check" size={18} />
              {t('player.card.keptHere')}
            </div>
          ) : null}

          {phase.kind === 'signin' ? (
            <div className={styles.signin}>
              <div className={styles.signinTitle}>{t('player.card.signInTitle')}</div>
              <div className={styles.signinBody}>
                {phase.waiting ? t('player.card.waitingNote') : t('player.card.signInBody')}
              </div>
              {phase.waiting ? (
                <div className={styles.signinButtons}>
                  <button type="button" className={styles.btn} disabled>
                    {t('player.card.waiting')}
                  </button>
                  <button
                    type="button"
                    className={styles.btn}
                    onClick={() => {
                      void host.cancelConnect();
                    }}
                  >
                    {t('player.card.cancel')}
                  </button>
                </div>
              ) : (
                <div className={styles.signinButtons}>
                  <button
                    ref={addRef}
                    type="button"
                    className={cx(styles.btn, styles.google)}
                    onClick={() => void signIn('google')}
                  >
                    <GoogleMark size={20} />
                    {t('player.first.google')}
                  </button>
                  <button
                    type="button"
                    className={cx(styles.btn, styles.apple)}
                    onClick={() => void signIn('apple')}
                  >
                    <AppleMark size={18} />
                    {t('player.first.apple')}
                  </button>
                </div>
              )}
              {phase.note !== undefined ? <p className={styles.note}>{phase.note}</p> : null}
              {!phase.waiting ? (
                <div className={styles.signinFoot}>
                  <button type="button" className={styles.link} onClick={() => void signIn(undefined)}>
                    {t('player.card.otherWays')}
                  </button>
                  <button type="button" className={styles.quiet} onClick={() => void notNow()}>
                    {t('player.card.notNow')}
                  </button>
                </div>
              ) : null}
            </div>
          ) : null}
        </div>
        {phase.kind === 'ready' || phase.kind === 'loading' ? (
          <div className={cx(styles.acts, styles.foot)}>
            <button
              ref={addRef}
              type="button"
              className={styles.primary}
              onClick={() => void add()}
              disabled={adding || (phase.kind === 'loading' && account?.connected !== true)}
            >
              {adding ? t('player.card.adding') : t('player.card.add')}
            </button>
            <button type="button" className={styles.btn} onClick={close}>
              {t('player.card.cancel')}
            </button>
          </div>
        ) : null}
      </div>
      {/* The caret sits outside the card, which scrolls when it is capped. */}
      {pos !== null ? (
        <i
          className={cx(styles.caret, pos.below && styles.caretUp)}
          style={{
            left: pos.left + pos.caret - 7,
            top: pos.below ? pos.top - 7 : pos.top + pos.maxH - 7,
          }}
          aria-hidden="true"
        />
      ) : null}
    </>
  );
}

/** More than one entry's worth of words: choose up to four in a row (the desktop card's picker). */
function Picker({
  words,
  onPick,
}: {
  words: string[];
  onPick: (headword: string) => void;
}): React.JSX.Element {
  const [from, setFrom] = useState(-1);
  const [to, setTo] = useState(-1);
  const [note, setNote] = useState('');
  const choose = (i: number): void => {
    if (from < 0 || i < from - 3 || i > to + 3 || (i >= from && i <= to && from === to)) {
      setFrom(i);
      setTo(i);
    } else if (i < from) setFrom(i);
    else setTo(i);
  };
  return (
    <div className={styles.picker}>
      <div className={styles.tokens}>
        {words.map((w, i) => (
          <button
            key={`${w}-${String(i)}`}
            type="button"
            className={styles.token}
            aria-pressed={from >= 0 && i >= from && i <= to}
            onClick={() => {
              choose(i);
            }}
            dir="auto"
          >
            {w}
          </button>
        ))}
      </div>
      {note !== '' ? <p className={styles.note}>{note}</p> : null}
      <div className={styles.acts}>
        <button
          type="button"
          className={styles.primary}
          disabled={from < 0}
          onClick={() => {
            const h = asHeadword(words.slice(Math.min(from, to), Math.max(from, to) + 1).join(' '));
            if (h === undefined) setNote(t('player.card.chooseWord'));
            else onPick(h);
          }}
        >
          {t('player.card.lookUp')}
        </button>
      </div>
    </div>
  );
}

/** Which language the line is in, pre-filled with the engine's guess. */
function AskLanguage({
  detected,
  onConfirm,
  onCancel,
}: {
  detected: string | undefined;
  onConfirm: (code: string) => void;
  onCancel: () => void;
}): React.JSX.Element {
  const [code, setCode] = useState<string | undefined>(detected);
  return (
    <>
      <LanguageSelect value={code} unsure={false} onChange={setCode} />
      <div className={styles.acts}>
        <button
          type="button"
          className={styles.primary}
          disabled={code === undefined || code === ''}
          onClick={() => {
            if (code !== undefined && code !== '') onConfirm(code);
          }}
        >
          {t('player.card.useLang', { lang: languageName(code) })}
        </button>
        <button type="button" className={styles.btn} onClick={onCancel}>
          {t('player.card.cancel')}
        </button>
      </div>
    </>
  );
}
