/**
 * The Player with nothing open (spec §4.2, mock-ups 02-empty, -light, -rtl,
 * -small): one drop zone (the whole window takes a drop, not only the zone),
 * "Open file…", three hints that each go once their thing has been done,
 * the one-time default-player offer when it is due (§24.6), and Continue
 * watching.
 */
import type { ReactNode } from 'react';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import type { RecentEntry } from '@/lib/platform/media.js';
import type { PlayerController } from '../controller.js';
import type { Os } from '../model/keys.js';
import { episodeCode, parseTitle } from '../model/title.js';
import { clock, minutesLeft } from '../model/time.js';
import { usePlayer } from '../store.js';
import { PIcon, type IconName } from './icons.js';
import { IconButton, Keys } from './kit.js';
import { LexpadButton } from './TopBar.js';
import styles from './Empty.module.css';

/** The most cards Continue watching shows (§4.2). */
export const MAX_RECENT = 8;

interface Props {
  controller: PlayerController;
  os: Os;
  offer: ReactNode;
  onLexpad: () => void;
  onShortcuts: () => void;
  onSettings: () => void;
}

export function Empty({
  controller,
  os,
  offer,
  onLexpad,
  onShortcuts,
  onSettings,
}: Props): React.JSX.Element {
  const hints = usePlayer((s) => s.prefs.hints);
  const recent = usePlayer((s) => s.recent);
  const small = usePlayer((s) => s.small);
  const rememberRecent = usePlayer((s) => s.prefs.settings.recent);
  const mod = os === 'macos' ? '⌘' : 'Ctrl';
  const showHints = !small && !(hints.drop && hints.move && hints.word);
  const items: { icon: IconName; text: string; done: boolean }[] = [
    { icon: 'drop', text: t('player.empty.hintDrop'), done: hints.drop },
    { icon: 'move', text: t('player.empty.hintMove'), done: hints.move },
    { icon: 'book', text: t('player.empty.hintWord'), done: hints.word },
  ];
  const cards = rememberRecent ? recent.slice(0, MAX_RECENT) : [];
  return (
    <div className={styles.empty}>
      <div className={styles.ground} aria-hidden="true" />
      <div className={styles.titleBar}>
        <span className={styles.lexpad}>
          <LexpadButton onClick={onLexpad} mod={mod} compact={small} />
        </span>
        <h1 className={styles.windowTitle}>{t('player.windowTitle')}</h1>
        <span className={cx(styles.tools, os === 'windows' && styles.toolsWindows)}>
          <IconButton
            icon="kbd"
            label={t('player.top.shortcuts')}
            keys={['?']}
            tipSide="down"
            onClick={onShortcuts}
            className={styles.tool}
          />
          <IconButton
            icon="sliders"
            label={t('player.top.settings')}
            keys={[`${mod},`]}
            tipSide="down"
            onClick={onSettings}
            className={styles.tool}
          />
        </span>
      </div>
      <div className={styles.column}>
        <div className={styles.zone}>
          <div className={styles.tile}>
            <PIcon name="film" size={30} />
          </div>
          <h2 className={styles.drop}>{t('player.empty.drop')}</h2>
          <p className={styles.formats}>{t('player.empty.formats')}</p>
          <div className={styles.openRow}>
            <button
              type="button"
              className={styles.open}
              onClick={() => {
                void controller.pick();
              }}
              aria-keyshortcuts={`${mod === '⌘' ? 'Meta' : 'Control'}+O`}
            >
              <PIcon name="folder" size={18} />
              {t('player.empty.open')}
            </button>
            <span className={styles.keys}>
              <Keys keys={[mod, 'O']} />
            </span>
          </div>
        </div>
        {showHints ? (
          <ul className={styles.hints} aria-label={t('player.empty.hintsLabel')}>
            {items.map((h) =>
              h.done ? (
                <li key={h.icon} className={styles.hintGone} aria-hidden="true" />
              ) : (
                <li key={h.icon} className={styles.hint}>
                  <span className={styles.hintIcon}>
                    <PIcon name={h.icon} size={16} />
                  </span>
                  <span className={styles.hintText}>{h.text}</span>
                </li>
              ),
            )}
          </ul>
        ) : null}
        {offer}
        {cards.length > 0 ? (
          <section className={styles.recent} aria-labelledby="recent-title">
            <div className={styles.recentHead}>
              <h2 id="recent-title" className={styles.recentTitle}>
                {t('player.recent.title')}
              </h2>
              <button
                type="button"
                className={styles.clear}
                onClick={() => {
                  void controller.media.clearRecent().then(() => controller.refreshRecent());
                }}
              >
                {t('player.recent.clear')}
              </button>
            </div>
            <ul className={styles.cards}>
              {cards.map((r) => (
                <RecentCard key={r.key} entry={r} controller={controller} />
              ))}
            </ul>
          </section>
        ) : null}
      </div>
    </div>
  );
}

function RecentCard({
  entry,
  controller,
}: {
  entry: RecentEntry;
  controller: PlayerController;
}): React.JSX.Element {
  const title = parseTitle(entry.name);
  const code = episodeCode({
    ...title,
    ...(entry.season !== undefined ? { season: entry.season } : {}),
    ...(entry.episode !== undefined ? { episode: entry.episode } : {}),
  });
  const name = [
    title.title,
    code !== undefined ? `${code}${title.episodeTitle ? ` ${title.episodeTitle}` : ''}` : undefined,
  ]
    .filter((x): x is string => x !== undefined)
    .join(' · ');
  const pct = entry.duration > 0 ? Math.min(100, (entry.position / entry.duration) * 100) : 0;
  const done = entry.watched;
  const open = (): void => {
    if (entry.fileId === undefined) return;
    void controller.openVideo({ id: entry.fileId, name: entry.name, kind: 'video', size: 0 });
  };
  return (
    <li className={cx(styles.card, entry.missing && styles.missing)}>
      <button
        type="button"
        className={styles.cardButton}
        onClick={open}
        disabled={entry.fileId === undefined}
        aria-label={t('player.recent.open', { title: name, time: clock(entry.position) })}
      >
        <span className={styles.thumb}>
          {entry.thumb !== undefined ? (
            <img src={entry.thumb} alt="" className={styles.thumbImg} draggable={false} />
          ) : (
            <PIcon name="film" size={28} className={styles.thumbIcon} />
          )}
          <span className={styles.resume} aria-hidden="true">
            {t('player.recent.resume', { time: clock(entry.position) })}
          </span>
          <span className={styles.bar} dir="ltr">
            <span
              className={cx(styles.fill, done && styles.fillDone)}
              style={{ width: `${String(done ? 100 : pct)}%` }}
            />
          </span>
        </span>
        <span className={styles.cardTitle}>{name}</span>
        <span className={styles.cardMeta}>
          {entry.missing
            ? t('player.recent.moved')
            : done
              ? t('player.recent.finished')
              : t('player.recent.minLeft', { count: minutesLeft(entry.position, entry.duration) })}
        </span>
      </button>
      <button
        type="button"
        className={styles.remove}
        aria-label={t('player.recent.remove', { title: name })}
        onClick={() => {
          void controller.media.removeRecent(entry.key).then(() => controller.refreshRecent());
        }}
      >
        <PIcon name="x" size={14} />
      </button>
    </li>
  );
}
