/**
 * The languages a subtitle can be in, as the player names them: the English
 * name and the autonym ("فارسی Persian"), which way it reads, and which face
 * draws it by default. The core guesses the language (file name, letters,
 * container tag; local, no AI); this is only how the page says it.
 */

export interface Language {
  code: string;
  name: string;
  autonym: string;
  rtl: boolean;
}

