const BY_CODE = new Map(LIST.map((l) => [l.code, l]));

export const LANGUAGES: readonly Language[] = LIST;

/** The language for an ISO 639-1 code (or a region-tagged one, "pt-BR"). */
export function language(code: string | undefined | null): Language | undefined {
  if (code === undefined || code === null || code === '') return undefined;
  return BY_CODE.get(code.toLowerCase().split(/[-_]/)[0] ?? '');
}

/** The English name, or the code itself in capitals when it is not in the list. */
export function languageName(code: string | undefined | null): string {
  return language(code)?.name ?? (code ?? '').toUpperCase();
}

/** "فارسی · Persian" in menus: the autonym first when it differs. */
export function languageLabel(code: string | undefined | null): string {
  const l = language(code);
  if (l === undefined) return languageName(code);
  return l.autonym === l.name ? l.name : `${l.autonym} · ${l.name}`;
}

/** Whether a language reads right to left. */
export function isRtlLanguage(code: string | undefined | null): boolean {
  return language(code)?.rtl === true;
}

/**
 * Languages written in the Arabic script, whose subtitles take Vazirmatn by
 * default (spec §7.2): Persian, Arabic, Urdu, Pashto, Kurdish (Sorani).
 */
const ARABIC_SCRIPT = new Set(['fa', 'ar', 'ur', 'ps', 'ckb']);

export function usesArabicScript(code: string | undefined | null): boolean {
  if (code === undefined || code === null) return false;
  return ARABIC_SCRIPT.has(code.toLowerCase().split(/[-_]/)[0] ?? '');
}

/** The audio menu's two-letter pill: "EN". */
export function languagePill(code: string | undefined | null): string {
  return (code ?? '').slice(0, 2).toUpperCase();
}
