/**
 * Where a word picked from a subtitle goes (owner, 25 Oct 2026): to a
 * notebook whose learning language is the subtitle's, and never into a
 * notebook of another language. Pure, so every case is a test.
 *
 * - The subtitle's language is a notebook's learning language: that
 *   notebook (the last one used when several are in it), with the others in
 *   that language to switch to.
 * - It is no notebook's learning language (the learner's own language, the
 *   meaning language, or a third one): the card says so and offers to start
 *   a notebook in it; nothing is saved silently.
 * - The language is unknown, or the engine is not sure of it: the card asks,
 *   with its guess filled in.
 *
 * The core keeps to the same rule for words saved before sign-in
 * (lexpad_desktop `word_queue::pick_notebook`).
 */
import type { PlayerNotebook } from '@/lib/platform/types.js';

/**
 * Below this the engine's guess of a subtitle's language is asked about
 * (the same line the drop prompt draws, `UNSURE_BELOW`): a guess from a
 * file name or a container tag is often 0.5, the letters' own guess higher.
 */
export const SURE_LANGUAGE = 0.6;

export function baseLang(code: string | undefined | null): string | undefined {
  const b = code?.toLowerCase().split(/[-_]/)[0];
  return b === undefined || b === '' ? undefined : b;
}

export type WordRoute =
  | {
      kind: 'notebook';
      lang: string;
      notebook: PlayerNotebook;
      /** Every notebook in that language, for the card's switcher (the chosen one among them). */
      choices: PlayerNotebook[];
    }
  | {
      kind: 'otherLanguage';
      lang: string;
      /** The notebook in view, which the card names ("Your notebook is Spanish → English"). */
      inView: PlayerNotebook | undefined;
      /** The notebook the card offers to start: this language, explained in the learner's. */
      start: { targetLang: string; meaningLang: string };
    }
  | { kind: 'askLanguage'; detected: string | undefined };

export interface RouteInput {
  lang: string | undefined;
  /** The engine's confidence in `lang`, 0–1; 1 once the learner said it. */
  confidence: number;
  notebooks: readonly PlayerNotebook[];
  /** The notebook last chosen or used (the core's `notebookId`). */
  lastUsed: string | null;
  /** The learner's own language (the notebook in view's meaning language, else the system's). */
  own: string | undefined;
}

function inViewOf(notebooks: readonly PlayerNotebook[], lastUsed: string | null): PlayerNotebook | undefined {
  return notebooks.find((n) => n.id === lastUsed) ?? notebooks.find((n) => n.isDefault) ?? notebooks[0];
}

/** The meaning language of a notebook started for `lang`: never `lang` itself. */
export function meaningFor(
  lang: string,
  own: string | undefined,
  inView: PlayerNotebook | undefined,
): string {
  const candidates = [own, inView?.meaningLang, inView?.targetLang, 'en', 'es'];
  for (const c of candidates) {
    const b = baseLang(c);
    if (b !== undefined && b !== lang) return b;
  }
  return 'en';
}

export function routeWord(input: RouteInput): WordRoute {
  const lang = baseLang(input.lang);
  if (lang === undefined || input.confidence < SURE_LANGUAGE) return { kind: 'askLanguage', detected: lang };
  const choices = input.notebooks.filter((n) => baseLang(n.targetLang) === lang);
  if (choices.length > 0) {
    const notebook =
      choices.find((n) => n.id === input.lastUsed) ?? choices.find((n) => n.isDefault) ?? choices[0];
    if (notebook !== undefined) return { kind: 'notebook', lang, notebook, choices };
  }
  const inView = inViewOf(input.notebooks, input.lastUsed);
  return {
    kind: 'otherLanguage',
    lang,
    inView,
    start: { targetLang: lang, meaningLang: meaningFor(lang, input.own, inView) },
  };
}

/** A line shown at the same moment on another track. */
export interface ParallelLine {
  lang: string | undefined;
  text: string;
}

/**
 * The example's translation: the line another visible track shows at the
 * same moment, when that track is in the notebook's meaning language. The
 * AI still writes the card; the film's own translation of the line needs
 * no call.
 */
export function parallelTranslation(
  lines: readonly ParallelLine[],
  meaningLang: string | undefined,
): string | undefined {
  const want = baseLang(meaningLang);
  if (want === undefined) return undefined;
  const hit = lines.find((l) => baseLang(l.lang) === want && l.text.trim() !== '');
  return hit?.text.replace(/\s+/g, ' ').trim();
}
