/**
 * Where the word card goes (spec §10): pointing at the word, above it when
 * there is room, else below, 12 px from every edge — and never over a
 * subtitle (desktop first-run audit S1, 26 Oct 2026: in a 960×600 window the
 * card for a word in the bottom track lay over the top track).
 *
 * In order: the whole card clear of every subtitle box; else the card capped
 * to the larger clear room, scrolling inside, when that room still shows a
 * useful card (`MIN_SCROLL_H`); else (a very small window) the whole card
 * clear of the clicked line only, and the other tracks it would cover step
 * aside while it is open (`covered`), so nothing is ever drawn over a line.
 */
import type { Rect } from './layout.js';

export interface Avoid {
  /** The subtitle slot the box belongs to. */
  id: number;
  rect: Rect;
}

export interface CardPlaceInput {
  /** The clicked word. */
  anchor: Rect;
  /** The card's natural size. */
  card: { w: number; h: number };
  /** The window. */
  view: { w: number; h: number };
  /** Every subtitle box on screen (the clicked word's own among them). */
  avoid: readonly Avoid[];
  /** Between the card and the word (or a subtitle). */
  gap: number;
  /** Between the card and the window's edge. */
  edge: number;
  /**
   * The bars' own buttons (the top bar's Lexpad, library, settings…): the card
   * slides sideways to keep clear of them, else takes the line's other side
   * (build review p5, 26 Oct 2026: at 640×360 it covered the Lexpad button).
   */
  controls?: readonly Rect[];
}

export interface CardPlace {
  left: number;
  top: number;
  /** The card's height cap: its natural height when it fits. */
  maxH: number;
  /** Below the word (the caret points up). */
  below: boolean;
  /** The caret's centre, from the card's left edge. */
  caret: number;
  /** Slots whose boxes step aside while the card is open (only in a very small window). */
  covered: number[];
}

/** The caret stays this far inside the card's corners. */
const CARET_INSET = 18;
/**
 * The least a capped card may be: its word, the first meaning and the two
 * buttons with a line to scroll. Below it the other tracks step aside instead.
 */
export const MIN_SCROLL_H = 220;

function spansX(r: Rect, left: number, w: number): boolean {
  return r.x < left + w && left < r.x + r.w;
}

function meets(a: Rect, b: Rect): boolean {
  return a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
}

function placeLines(input: CardPlaceInput): CardPlace {
  const { anchor: a, card, view, avoid, gap, edge } = input;
  const cx = a.x + a.w / 2;
  const left = Math.max(edge, Math.min(view.w - card.w - edge, cx - card.w / 2));
  const caret = Math.max(CARET_INSET, Math.min(card.w - CARET_INSET, cx - left));
  const inColumn = avoid.filter((r) => spansX(r.rect, left, card.w));
  // The clicked word's own line: the card keeps clear of all of it, not only the word.
  const own = inColumn.filter((r) => r.rect.y < a.y + a.h && a.y < r.rect.y + r.rect.h);
  const wordTop = Math.min(a.y, ...own.map((r) => r.rect.y));
  const wordBottom = Math.max(a.y + a.h, ...own.map((r) => r.rect.y + r.rect.h));

  const rooms = (others: readonly Avoid[]): { above: number; below: number } => {
    const ceiling = Math.max(
      edge,
      ...others.filter((r) => r.rect.y + r.rect.h <= wordTop).map((r) => r.rect.y + r.rect.h + gap),
    );
    const floor = Math.min(
      view.h - edge,
      ...others.filter((r) => r.rect.y >= wordBottom).map((r) => r.rect.y - gap),
    );
    return { above: wordTop - gap - ceiling, below: floor - (wordBottom + gap) };
  };
  const at = (below: boolean, h: number, covered: number[] = []): CardPlace => ({
    left,
    top: below ? wordBottom + gap : wordTop - gap - h,
    maxH: h,
    below,
    caret,
    covered,
  });

  // 1. The whole card, clear of every line.
  const clear = rooms(inColumn);
  if (card.h <= clear.above) return at(false, card.h);
  if (card.h <= clear.below) return at(true, card.h);
  // 2. Capped to the larger clear room, scrolling inside.
  const best = Math.max(clear.above, clear.below);
  if (best >= MIN_SCROLL_H) return at(clear.below > clear.above, best);
  // 3. Clear of its own line only; the tracks it would cover step aside.
  const open = rooms([]);
  const below = card.h > open.above && open.below > open.above;
  const h = Math.max(0, Math.min(card.h, below ? open.below : open.above));
  const place = at(below, h);
  const rect = { x: place.left, y: place.top, w: card.w, h };
  const covered = [
    ...new Set(inColumn.filter((r) => !own.includes(r) && meets(rect, r.rect)).map((r) => r.id)),
  ];
  return { ...place, covered };
}

/** The card's rectangle where it is placed. */
function rectOf(p: CardPlace, w: number): Rect {
  return { x: p.left, y: p.top, w, h: p.maxH };
}

/**
 * The card, clear of the subtitle lines (`placeLines`) and then of the bars'
 * buttons: slid sideways as little as it takes, its caret still on the word;
 * else on the other side of the line when that side is clear of them; else
 * where the lines put it.
 */
export function placeCard(input: CardPlaceInput): CardPlace {
  const first = placeLines(input);
  const controls = input.controls ?? [];
  const hits = (p: CardPlace): boolean => controls.some((c) => meets(rectOf(p, input.card.w), c));
  if (!hits(first)) return first;
  const { anchor: a, card, view, edge, gap } = input;
  const cx = a.x + a.w / 2;
  // Sideways: just past a button on either side, nearest first.
  const lefts = controls
    .flatMap((c) => [c.x + c.w + gap, c.x - gap - card.w])
    .filter((l) => l >= edge && l + card.w <= view.w - edge)
    // The caret must still reach the word.
    .filter((l) => cx - l >= CARET_INSET && l + card.w - cx >= CARET_INSET)
    .sort((x, y) => Math.abs(x - first.left) - Math.abs(y - first.left));
  for (const left of lefts) {
    const moved = { ...first, left, caret: cx - left };
    if (!hits(moved)) return moved;
  }
  // The line's other side, when the lines leave it room and it is clear of the buttons.
  const other = flipSide(input, first);
  if (other !== null && !hits(other)) return other;
  return first;
}

/** The same card on the other side of its line, if it fits there clear of every line. */
function flipSide(input: CardPlaceInput, from: CardPlace): CardPlace | null {
  const { anchor: a, avoid, view, gap, edge, card } = input;
  const inColumn = avoid.filter((r) => spansX(r.rect, from.left, card.w));
  const own = inColumn.filter((r) => r.rect.y < a.y + a.h && a.y < r.rect.y + r.rect.h);
  const wordTop = Math.min(a.y, ...own.map((r) => r.rect.y));
  const wordBottom = Math.max(a.y + a.h, ...own.map((r) => r.rect.y + r.rect.h));
  const h = from.maxH;
  const top = from.below ? wordTop - gap - h : wordBottom + gap;
  if (top < edge || top + h > view.h - edge) return null;
  const rect = { x: from.left, y: top, w: card.w, h };
  if (inColumn.some((r) => !own.includes(r) && meets(rect, r.rect) && !from.covered.includes(r.id)))
    return null;
  return { ...from, top, below: !from.below };
}
