/**
 * The player's small parts: an icon button with its tooltip and key caps,
 * key caps, the switch, the glass pop-over and its rows. One look for every
 * menu, as the mock-ups draw them (spec §3, §6).
 */
import {
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type ReactNode,
  type Ref,
} from 'react';
import { cx } from '@/lib/cx.js';
import { PIcon, type IconName } from './icons.js';
import styles from './kit.module.css';

/** Tooltips wait this long, so a pointer passing over the bar shows nothing (§6). */
export const TOOLTIP_DELAY_MS = 500;

export function Kbd({
  children,
  className,
}: {
  children: ReactNode;
  className?: string | undefined;
}): React.JSX.Element {
  return <kbd className={cx(styles.kbd, className)}>{children}</kbd>;
}

/** Key caps for a shortcut: "⌘ O" is two caps. */
export function Keys({ keys }: { keys: readonly string[] }): React.JSX.Element {
  return (
    <span className={styles.keys} dir="ltr">
      {keys.map((k) => (
        <Kbd key={k}>{k}</Kbd>
      ))}
    </span>
  );
}

interface IconButtonProps {
  icon: IconName;
  label: string;
  onClick?: () => void;
  /** The tooltip's key caps. */
  keys?: readonly string[] | undefined;
  /** The tooltip's own words when they differ from the label. */
  tip?: ReactNode | undefined;
  on?: boolean;
  big?: boolean;
  small?: boolean;
  badge?: number | undefined;
  className?: string | undefined;
  /** For a button that opens a menu. */
  menu?: { expanded: boolean | undefined; controls?: string };
  pressed?: boolean | undefined;
  disabled?: boolean | undefined;
  buttonRef?: Ref<HTMLButtonElement> | undefined;
  tipSide?: 'up' | 'down' | undefined;
  style?: CSSProperties | undefined;
  iconSize?: number | undefined;
  tabIndex?: number | undefined;
}

/**
 * A 40×40 icon button: hover wash, press scale, mint when on, and a tooltip
 * with its key after half a second (on focus too, so the keyboard sees it).
 */
export function IconButton({
  icon,
  label,
  onClick,
  keys,
  tip,
  on = false,
  big = false,
  small = false,
  badge,
  className,
  menu,
  pressed,
  disabled = false,
  buttonRef,
  tipSide = 'up',
  style,
  iconSize,
  tabIndex,
}: IconButtonProps): React.JSX.Element {
  const [showTip, setShowTip] = useState(false);
  const timer = useRef(0);
  const tipId = useId();
  const open = (): void => {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => {
      setShowTip(true);
    }, TOOLTIP_DELAY_MS);
  };
  const close = (): void => {
    window.clearTimeout(timer.current);
    setShowTip(false);
  };
  useEffect(
    () => () => {
      window.clearTimeout(timer.current);
    },
    [],
  );
  const hasTip = !(menu?.expanded ?? false);
  return (
    <button
      ref={buttonRef}
      type="button"
      className={cx(styles.ib, big && styles.big, small && styles.small, on && styles.on, className)}
      aria-label={label}
      aria-haspopup={menu ? 'menu' : undefined}
      aria-expanded={menu ? menu.expanded : undefined}
      aria-controls={menu?.controls}
      aria-pressed={pressed}
      aria-keyshortcuts={keys && keys.length > 0 ? keys.join(' ') : undefined}
      disabled={disabled}
      onClick={() => {
        close();
        onClick?.();
      }}
      onPointerEnter={open}
      onPointerLeave={close}
      onFocus={open}
      onBlur={close}
      style={style}
      tabIndex={tabIndex}
    >
      <PIcon name={icon} size={iconSize ?? (big ? 28 : small ? 18 : 22)} />
      {badge !== undefined && badge > 1 ? (
        <span className={styles.badge} aria-hidden="true">
          {badge}
        </span>
      ) : null}
      {showTip && hasTip ? (
        <span role="tooltip" id={tipId} className={cx(styles.tip, tipSide === 'down' && styles.tipDown)}>
          {tip ?? label}
          {keys && keys.length > 0 ? <Keys keys={keys} /> : null}
        </span>
      ) : null}
    </button>
  );
}

interface SwitchProps {
  checked: boolean;
  onChange: (on: boolean) => void;
  label: string;
  small?: boolean;
  describedBy?: string | undefined;
}

/** The 36×22 switch. */
export function Switch({
  checked,
  onChange,
  label,
  small = false,
  describedBy,
}: SwitchProps): React.JSX.Element {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      aria-describedby={describedBy}
      className={cx(styles.switch, checked && styles.switchOn, small && styles.switchSmall)}
      onClick={(e) => {
        e.stopPropagation();
        onChange(!checked);
      }}
    />
  );
}

interface PopoverProps {
  id?: string | undefined;
  label: string;
  onClose: () => void;
  children: ReactNode;
  className?: string | undefined;
  style?: CSSProperties | undefined;
  /** The element that opened it: focus goes back to it, and a click on it is not "outside". */
  anchor?: HTMLElement | null | undefined;
  role?: 'menu' | 'dialog' | undefined;
  /** Move focus into the pop-over when it opens (keyboard use). */
  autoFocus?: boolean;
}

/**
 * A glass pop-over (radius 14, blur 26, the floating shadow). Escape or a
 * click outside closes it; arrow keys move between its rows; focus goes
 * back to what opened it.
 */
export function Popover({
  id,
  label,
  onClose,
  children,
  className,
  style,
  anchor,
  role = 'menu',
  autoFocus = true,
}: PopoverProps): React.JSX.Element {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const root = ref.current;
    if (root === null) return;
    if (autoFocus) {
      const first = root.querySelector<HTMLElement>('[data-row]:not([disabled]), button:not([disabled])');
      first?.focus({ preventScroll: true });
    }
    const outside = (e: PointerEvent): void => {
      const target = e.target as Node;
      if (root.contains(target) || anchor?.contains(target) === true) return;
      onClose();
    };
    document.addEventListener('pointerdown', outside, true);
    return () => {
      document.removeEventListener('pointerdown', outside, true);
    };
  }, [anchor, onClose, autoFocus]);
  useEffect(
    () => () => {
      anchor?.focus({ preventScroll: true });
    },
    [anchor],
  );
  const onKey = (e: KeyboardEvent<HTMLDivElement>): void => {
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      onClose();
      return;
    }
    if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp' && e.key !== 'Home' && e.key !== 'End') return;
    const root = ref.current;
    if (root === null) return;
    const rows = [...root.querySelectorAll<HTMLElement>('[data-row]:not([disabled])')];
    if (rows.length === 0) return;
    e.preventDefault();
    e.stopPropagation();
    const at = rows.indexOf(document.activeElement as HTMLElement);
    const next =
      e.key === 'Home'
        ? 0
        : e.key === 'End'
          ? rows.length - 1
          : e.key === 'ArrowDown'
            ? (at + 1) % rows.length
            : (at - 1 + rows.length) % rows.length;
    rows[next]?.focus();
  };
  return (
    <div
      ref={ref}
      id={id}
      role={role}
      aria-label={label}
      className={cx(styles.pop, className)}
      style={style}
      onKeyDown={onKey}
      data-player-overlay=""
    >
      {children}
    </div>
  );
}

interface RowProps {
  children: ReactNode;
  onClick?: () => void;
  role?: 'menuitem' | 'menuitemradio' | 'menuitemcheckbox' | undefined;
  checked?: boolean | undefined;
  className?: string | undefined;
  disabled?: boolean | undefined;
  label?: string | undefined;
  style?: CSSProperties | undefined;
}

/** One row of a menu: 36 px, its own wash on hover and a mint ring on focus. */
export function Row({
  children,
  onClick,
  role = 'menuitem',
  checked,
  className,
  disabled,
  label,
  style,
}: RowProps): React.JSX.Element {
  return (
    <button
      type="button"
      role={role}
      aria-checked={role === 'menuitem' ? undefined : checked}
      aria-label={label}
      className={cx(styles.mi, className)}
      onClick={onClick}
      disabled={disabled}
      data-row=""
      style={style}
    >
      {children}
    </button>
  );
}

export function MenuTitle({ children }: { children: ReactNode }): React.JSX.Element {
  return <div className={styles.menuTitle}>{children}</div>;
}

export function Hr(): React.JSX.Element {
  return <hr className={styles.hr} />;
}

export { styles as kitStyles };
