/**
 * The Lexpad Player (spec uiux/specs/2026-10-25-video-player.md): its own
 * dark window in the desktop app, all video. Controls fade in on movement
 * and out after 2.5 s; every notice sits in the top-left corner; subtitles
 * are objects you can touch; learning sits on top of a real player.
 *
 * This page is the web app's `/player` route, shown in the desktop app's
 * Player window. Outside the desktop app there is no engine, and the page
 * says where the player is instead of drawing a player that cannot play.
 */
import { useCallback, useEffect, useMemo, useRef, useState, type MouseEvent, type PointerEvent } from 'react';
import { useSearchParams } from 'react-router-dom';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { platform } from '@/lib/platform/index.js';
import type { PlayerHost } from '@/lib/platform/types.js';
import { contextMenuItems, parseMenuCommand } from './contextMenu.js';
import { PlayerController, SPEEDS, VOLUME_STEP } from './controller.js';
import { languageLabel, languageName } from './model/languages.js';
import { commandFor, isMenuKey, isTypingTarget, mayDragWindow, type Command } from './model/keys.js';
import type { SlotNumber } from './model/slots.js';
import { useNotebookWords } from './notebookWords.js';
import { usePlayerSender } from './usePlayerSender.js';
import { slotVisible, trackIn, updatePrefs, usePlayer, type CardRequest } from './store.js';
import { AddWordCard } from './ui/Card.js';
import { ControlBar } from './ui/ControlBar.js';
import { SettingsDialog, ShortcutSheet } from './ui/Dialogs.js';
import { DropPrompt } from './ui/DropPrompt.js';
import { Empty } from './ui/Empty.js';
import { EndSummary } from './ui/EndSummary.js';
import { PIcon } from './ui/icons.js';
import { MiniChrome } from './ui/Mini.js';
import { Notices } from './ui/Notices.js';
import { SidePanel } from './ui/Panel.js';
import { DefaultOffer, DragOverlay, ErrorScreen, FirstOpen, Processing } from './ui/Screens.js';
import { cueTokens, selectionText, SubtitleLayer, type WordSelection } from './ui/Subtitles.js';
import { SyncPicker } from './ui/Sync.js';
import { CaptionButtons, TopBar } from './ui/TopBar.js';
import styles from './PlayerScreen.module.css';

/** The controls hide after this long without movement while playing (§4.4). */
export const HIDE_AFTER_MS = 2500;
/** A pointer must move this far to wake the controls. */
const WAKE_PX = 3;
/**
 * A press on the video that moves this far moves the window instead of
 * playing or pausing (owner, 26 Oct 2026: the frameless window could only be
 * moved by its 10 px top edge). Below it, the press is a click.
 */
export const DRAG_WINDOW_PX = 4;
/** A contextmenu event this soon after the keyboard opened the menu is the same request. */
const KEY_MENU_GRACE_MS = 500;

/** Where a keyboard-opened menu appears: under the focused thing's start, in window CSS px. */
function keyboardMenuPoint(r: DOMRect): { x: number; y: number } {
  return { x: Math.round(r.left), y: Math.round(r.bottom) };
}

function centreOf(r: DOMRect): { x: number; y: number } {
  return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
}
/** The small layout below this width (§6.9). */
export const SMALL_BELOW_PX = 900;
/** The side panel is 380 px wide from this window width, 340 px below it (§3). */
const PANEL_WIDE_FROM_PX = 1200;

/** The host the page plays through: the desktop core's player, when there is one. */
function playerHost(): PlayerHost | undefined {
  return platform.desktop?.player;
}

export function PlayerScreen(): React.JSX.Element {
  const host = playerHost();
  if (host === undefined) return <Unavailable />;
  return <Player host={host} />;
}

function Unavailable(): React.JSX.Element {
  return (
    <div className={styles.unavailable} data-player-theme="dark">
      <PIcon name="watch" size={40} />
      <h1>{t('player.unavailable.title')}</h1>
      <p>{t('player.unavailable.body')}</p>
    </div>
  );
}

function useSystemDark(): boolean {
  const [dark, setDark] = useState(() => window.matchMedia('(prefers-color-scheme: dark)').matches);
  useEffect(() => {
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const on = (): void => {
      setDark(mq.matches);
    };
    mq.addEventListener('change', on);
    return () => {
      mq.removeEventListener('change', on);
    };
  }, []);
  return dark;
}

function Player({ host }: { host: PlayerHost }): React.JSX.Element {
  const [controller] = useState(() => new PlayerController(host));
  // The usage analytics' sender, for this window outside the sign-in gate.
  usePlayerSender(host);
  // How the window was opened: from Lexpad's own window ("app") or with a file ("file").
  const [params] = useSearchParams();
  const from = params.get('from');
  // The core says the Start window was shown (`seen=start`): its sign-in was
  // this Player's first open, so the full-screen one never comes (spec §7).
  const seenStart = params.get('seen') === 'start';
  useEffect(() => {
    if (seenStart && !usePlayer.getState().prefs.firstOpenDone)
      updatePrefs((p) => ({ ...p, firstOpenDone: true }));
  }, [seenStart]);
  const os = host.window.os;
  const mod = os === 'macos' ? '⌘' : 'Ctrl';
  const rootRef = useRef<HTMLElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const noticeRef = useRef<HTMLDivElement>(null);
  const phase = usePlayer((s) => s.phase);
  const file = usePlayer((s) => s.file);
  const chrome = usePlayer((s) => s.chrome);
  const paused = usePlayer((s) => s.paused);
  const small = usePlayer((s) => s.small);
  const panel = usePlayer((s) => s.panel);
  const dialog = usePlayer((s) => s.dialog);
  const card = usePlayer((s) => s.card);
  const summary = usePlayer((s) => s.summary);
  const mini = usePlayer((s) => s.mini);
  const theme = usePlayer((s) => s.prefs.settings.theme);
  const markOn = usePlayer((s) => s.prefs.settings.markNotebook);
  const offerState = usePlayer((s) => s.prefs.offer);
  const readAloud = usePlayer((s) => s.prefs.settings.readAloud);
  const systemDark = useSystemDark();
  const [drag, setDrag] = useState<string[] | null>(null);
  const [glyph, setGlyph] = useState<{ key: number; icon: 'play' | 'pause' } | null>(null);
  const [wordCursor, setWordCursor] = useState<WordSelection | null>(null);
  const [selection, setSelection] = useState<WordSelection | null>(null);
  const [firstOpen, setFirstOpen] = useState(false);
  /** The subtitle word a right-click was on, for the menu's "Add … to Lexpad". */
  const ctxWord = useRef<{ sel: WordSelection; rect: DOMRect } | null>(null);
  const [noticeRect, setNoticeRect] = useState<{ x: number; y: number; w: number; h: number } | null>(null);
  const [offerShown, setOfferShown] = useState(false);
  const learningLang = usePlayer((s) => trackIn(s, 1)?.lang);
  const notebookWords = useNotebookWords(markOn, learningLang);
  const playerTheme = theme === 'system' && !systemDark ? 'light' : 'dark';

  // The page under the window is the video's black, so a resize or a fractional
  // pixel row at the edge never shows the app's light ground (Windows, 26 Oct 2026).
  useEffect(() => {
    const html = document.documentElement;
    html.setAttribute('data-player-page', '');
    return () => {
      html.removeAttribute('data-player-page');
    };
  }, []);

  // The video element belongs to the controller for the page's life.
  useEffect(() => {
    const v = videoRef.current;
    if (v === null) return;
    return controller.attach(v);
  }, [controller]);

  // The learner's languages decide where a new subtitle goes (§9.3).
  useEffect(() => {
    let live = true;
    const read = (): void => {
      void host
        .account()
        .then((a) => {
          if (!live) return;
          const nb =
            a.notebooks.find((n) => n.id === a.notebookId) ??
            a.notebooks.find((n) => n.isDefault) ??
            a.notebooks[0];
          controller.setLanguages({
            learning: nb?.targetLang,
            own: nb?.meaningLang ?? navigator.language.split('-')[0],
          });
          // First open, signed out, not opened from inside the app or with a file (§4.1),
          // and never after the Start window (one sign-in voice, desktop first-run spec §7).
          if (!a.connected && from === null && !seenStart && !usePlayer.getState().prefs.firstOpenDone) {
            setFirstOpen(usePlayer.getState().file === null);
          }
        })
        .catch(() => {
          controller.setLanguages({ learning: undefined, own: navigator.language.split('-')[0] });
        });
    };
    read();
    const stop = platform.desktop?.onSessionChange(read);
    return () => {
      live = false;
      stop?.();
    };
  }, [controller, host, from, seenStart]);

  // Opened to choose a file (the tray's "Open a video…", the Watch page).
  const picked = useRef(false);
  useEffect(() => {
    if (from !== 'pick' || picked.current) return;
    picked.current = true;
    void controller.pick();
  }, [from, controller]);

  // Words waiting for sign-in (the badge and Settings → Account).
  useEffect(
    () =>
      host.words.onPending((n) => {
        usePlayer.setState({ pending: n });
      }),
    [host],
  );

  // The small layout (§6.9) and the notice corner's box (a top subtitle steps below it).
  useEffect(() => {
    const root = rootRef.current;
    if (root === null) return;
    const ro = new ResizeObserver(() => {
      const w = root.clientWidth;
      usePlayer.setState({ small: w < SMALL_BELOW_PX });
      // The side panel: 380 px from a 1200 px window, 340 px below it (§3).
      root.style.setProperty('--pl-panel-w', w >= PANEL_WIDE_FROM_PX ? '380px' : '340px');
    });
    ro.observe(root);
    return () => {
      ro.disconnect();
    };
  }, []);
  const notices = usePlayer((s) => s.notices.length + (s.prompt !== null ? 1 : 0));
  useEffect(() => {
    const el = noticeRef.current;
    if (el === null || notices === 0) {
      setNoticeRect(null);
      return;
    }
    const r = el.getBoundingClientRect();
    const area = rootRef.current?.getBoundingClientRect();
    setNoticeRect(
      r.height > 0
        ? { x: r.left - (area?.left ?? 0), y: r.top - (area?.top ?? 0), w: r.width, h: r.height }
        : null,
    );
  }, [notices]);

  // Full screen follows the window (the Escape key, the green button, F11).
  useEffect(
    () =>
      host.window.onFullscreen((on) => {
        usePlayer.setState({ fullscreen: on });
      }),
    [host],
  );

  // macOS: the system's window buttons come and go with the chrome.
  useEffect(() => {
    if (os === 'macos') void host.window.setButtonsVisible(chrome || paused || file === null);
  }, [chrome, paused, file, os, host]);

  // Dragged files: the overlay says what will happen; the core takes the drop.
  useEffect(
    () =>
      host.window.onDrag((e) => {
        if (e.kind === 'enter') setDrag(e.names);
        else if (e.kind === 'leave' || e.kind === 'drop') setDrag(null);
      }),
    [host],
  );

  // Pause when minimised, if asked (§15).
  useEffect(() => {
    const on = (): void => {
      if (document.hidden && usePlayer.getState().prefs.settings.pauseMinimised) controller.pause();
    };
    document.addEventListener('visibilitychange', on);
    return () => {
      document.removeEventListener('visibilitychange', on);
    };
  }, [controller]);

  /* ---------------------------------------------------------- auto-hide */

  const hideTimer = useRef(0);
  const lastPointer = useRef<{ x: number; y: number } | null>(null);
  const overZone = useRef(false);
  const shouldStay = useCallback((): boolean => {
    const s = usePlayer.getState();
    if (
      s.paused ||
      s.file === null ||
      s.menu !== null ||
      s.card !== null ||
      s.dialog !== null ||
      s.sync !== null ||
      s.summary
    )
      return true;
    if (overZone.current) return true;
    const root = rootRef.current;
    if (
      root?.querySelector('[data-chrome-hold]') !== null &&
      root?.querySelector('[data-chrome-hold]') !== undefined
    )
      return true;
    const active = document.activeElement;
    if (active !== null && active !== document.body && active.closest('[data-chrome-zone]') !== null)
      return true;
    return false;
  }, []);
  const wake = useCallback((): void => {
    if (!usePlayer.getState().chrome) usePlayer.setState({ chrome: true });
    window.clearTimeout(hideTimer.current);
    hideTimer.current = window.setTimeout(function check() {
      if (shouldStay()) {
        hideTimer.current = window.setTimeout(check, HIDE_AFTER_MS);
        return;
      }
      usePlayer.setState({ chrome: false });
    }, HIDE_AFTER_MS);
  }, [shouldStay]);
  useEffect(() => {
    wake();
    return () => {
      window.clearTimeout(hideTimer.current);
    };
  }, [wake, paused]);

  /* ---------------------------------------------------------- the card */

  const openCard = useCallback(
    (request: Omit<CardRequest, 'resume'>): void => {
      const resume = controller.isPlaying();
      if (resume) {
        controller.pause();
        controller.notice({ text: t('player.notice.pausedForWord'), icon: 'pause' });
      }
      usePlayer.setState({ card: { ...request, resume }, menu: null });
    },
    [controller],
  );

  // Closing the card plays on if it paused the video and the setting says so (§10).
  const prevCard = useRef<CardRequest | null>(null);
  useEffect(() => {
    const was = prevCard.current;
    prevCard.current = card;
    if (was !== null && card === null) {
      setSelection(null);
      if (was.resume && usePlayer.getState().prefs.settings.resumeAfterWord) controller.play();
      was.returnFocus?.focus({ preventScroll: true });
    }
  }, [card, controller]);

  const onSelect = useCallback(
    (sel: WordSelection, rect: DOMRect, opts: { keyboard: boolean }): void => {
      const s = usePlayer.getState();
      const tr = trackIn(s, sel.slot);
      if (tr === undefined) return;
      const cue = tr.cues[sel.cue];
      if (cue === undefined) return;
      const what = selectionText(tr, sel);
      if (what.headword === null && what.pickFrom === undefined) return;
      setSelection(sel);
      openCard({
        headword: what.headword,
        from: 'subtitles',
        sentence: what.sentence,
        ...(what.pickFrom !== undefined ? { pickFrom: what.pickFrom } : {}),
        lang: tr.lang,
        langConfidence: tr.langConfidence,
        trackId: tr.id,
        parallel: controller.parallelLines(sel.slot, (cue.start + cue.end) / 2000 + tr.offsetMs / 1000),
        at: (cue.start + tr.offsetMs) / 1000,
        slot: sel.slot,
        anchor: { x: rect.left, y: rect.top, w: rect.width, h: rect.height },
        returnFocus: opts.keyboard ? (document.activeElement as HTMLElement | null) : null,
      });
    },
    [openCard, controller],
  );

  const onTranscriptSelect = useCallback(
    (text: string, sentence: string, at: number, lang: string | undefined, rect: DOMRect): void => {
      const words = text.split(/\s+/).filter(Boolean);
      openCard({
        headword: words.length <= 4 ? text : null,
        from: 'transcript',
        ...(words.length > 4 ? { pickFrom: words } : {}),
        sentence,
        lang,
        at,
        slot: 1,
        anchor: { x: rect.left, y: rect.top, w: rect.width, h: rect.height },
      });
    },
    [openCard],
  );

  /* ---------------------------------------------------------- commands */

  const toggleFullscreen = useCallback((): void => {
    const on = !usePlayer.getState().fullscreen;
    usePlayer.setState({ fullscreen: on });
    void host.window.setFullscreen(on).catch(() => {
      usePlayer.setState({ fullscreen: !on });
    });
  }, [host]);

  const toggleMini = useCallback((): void => {
    const s = usePlayer.getState();
    if (s.file === null) return;
    if (s.mini) {
      usePlayer.setState({ mini: false });
      void host.window.backToBig();
    } else {
      usePlayer.setState({ mini: true, panel: null, menu: null });
      void host.window.openMini();
    }
  }, [host]);

  const openLexpad = useCallback((): void => {
    usePlayer.setState({ unseen: 0 });
    void host.openLexpad();
  }, [host]);

  /** The subtitle line on screen now: the track Z / X act on first, then 1, 2, 3. */
  const lineNow = useCallback((): string => {
    const s = usePlayer.getState();
    const order = [s.focusSlot, 1, 2, 3] as const;
    for (const n of order) {
      const tr = slotVisible(s, n) ? trackIn(s, n) : undefined;
      if (tr === undefined) continue;
      const text = controller
        .activeIn(tr, controller.time())
        .map((i) => tr.cues[i]?.text ?? '')
        .join('\n')
        .trim();
      if (text !== '') return text;
    }
    return '';
  }, [controller]);
  /** Copy through the core when it can (no click needed), else the browser's clipboard. */
  const copy = useCallback(
    async (text: string): Promise<boolean> => {
      try {
        if ((await host.window.copyText?.(text)) === true) return true;
        await platform.share.text(text);
        return true;
      } catch {
        return false;
      }
    },
    [host],
  );

  const run = useCallback(
    (cmd: Command): void => {
      const s = usePlayer.getState();
      const skip = s.prefs.settings.skip;
      switch (cmd) {
        case 'playPause':
          controller.togglePlay();
          break;
        case 'back5':
          controller.skip(-skip);
          break;
        case 'forward5':
          controller.skip(skip);
          break;
        case 'back10':
          controller.skip(-10);
          break;
        case 'forward10':
          controller.skip(10);
          break;
        case 'previousLine':
          controller.stepLine(-1);
          break;
        case 'nextLine':
          controller.stepLine(1);
          break;
        case 'replayLine':
          controller.stepLine(0);
          break;
        case 'slower':
          controller.stepSpeed(-1);
          break;
        case 'faster':
          controller.stepSpeed(1);
          break;
        case 'normalSpeed':
          controller.setSpeed(1);
          break;
        case 'nextEpisode':
          if (s.episodes?.next !== undefined) void controller.openVideo(s.episodes.next);
          break;
        case 'previousEpisode':
          if (s.episodes?.previous !== undefined) void controller.openVideo(s.episodes.previous);
          break;
        case 'toggleSubtitles':
          controller.toggleMaster();
          break;
        case 'toggleTrack1':
        case 'toggleTrack2':
        case 'toggleTrack3':
          controller.toggleSlot(Number(cmd.slice(-1)) as SlotNumber);
          break;
        case 'subtitlesPanel':
          controller.openPanel('subtitles');
          break;
        case 'transcript':
          controller.openPanel('transcript');
          break;
        case 'timingEarlier':
          controller.nudgeOffset(-100);
          break;
        case 'timingLater':
          controller.nudgeOffset(100);
          break;
        case 'timingEarlierBig':
          controller.nudgeOffset(-500);
          break;
        case 'timingLaterBig':
          controller.nudgeOffset(500);
          break;
        case 'heard':
          controller.openSync();
          break;
        case 'pickWord': {
          const tr = trackIn(s, 1) ?? trackIn(s, 2) ?? trackIn(s, 3);
          if (tr === undefined) break;
          controller.pause();
          const slot = (s.slots.indexOf(tr.id) + 1) as SlotNumber;
          const idx = controller.activeIn(tr, controller.time());
          const cueIndex = idx[0];
          if (cueIndex === undefined) break;
          const cue = tr.cues[cueIndex];
          if (cue === undefined) break;
          const first = cueTokens(cue).findIndex((tk) => tk.word);
          if (first >= 0) setWordCursor({ slot, cue: cueIndex, from: first, to: first });
          break;
        }
        case 'fullscreen':
          toggleFullscreen();
          break;
        case 'mini':
          toggleMini();
          break;
        case 'escape':
          if (s.card !== null) usePlayer.setState({ card: null });
          else if (s.dialog !== null) usePlayer.setState({ dialog: null });
          else if (s.menu !== null) usePlayer.setState({ menu: null });
          else if (s.sync !== null) controller.cancelSync();
          else if (s.fullscreen) toggleFullscreen();
          else if (s.mini) toggleMini();
          else if (s.panel !== null) usePlayer.setState({ panel: null });
          break;
        case 'volumeUp':
          controller.setVolume(s.prefs.volume + VOLUME_STEP, { hud: true });
          break;
        case 'volumeDown':
          controller.setVolume(s.prefs.volume - VOLUME_STEP, { hud: true });
          break;
        case 'mute':
          controller.toggleMute();
          break;
        case 'nextAudio':
          controller.nextAudio();
          break;
        case 'open':
          void controller.pick();
          break;
        case 'shortcuts':
          usePlayer.setState((st) => ({ dialog: st.dialog === 'shortcuts' ? null : 'shortcuts' }));
          break;
        case 'settings':
          usePlayer.setState({ dialog: 'settings' });
          break;
        case 'undo':
          controller.undo();
          break;
        case 'search':
          usePlayer.setState({ panel: 'transcript', panelTab: 'transcript' });
          window.setTimeout(() => window.dispatchEvent(new Event('player:search')), 0);
          break;
        case 'lexpad':
          openLexpad();
          break;
        case 'player':
          break;
        case 'addSubtitle':
          void controller.pick();
          break;
        case 'addWord': {
          const w = ctxWord.current;
          ctxWord.current = null;
          if (w !== null) onSelect(w.sel, w.rect, { keyboard: false });
          break;
        }
        case 'copyLine': {
          const text = lineNow();
          if (text === '') break;
          void copy(text).then((ok) => {
            controller.notice({
              text: ok ? t('player.notice.lineCopied') : t('player.notice.lineCopyFailed'),
              icon: ok ? 'check' : 'alert',
            });
          });
          break;
        }
        case 'onTop': {
          const on = !s.onTop;
          usePlayer.setState({ onTop: on });
          void host.window.setOnTop(on).catch(() => {
            usePlayer.setState({ onTop: !on });
          });
          break;
        }
      }
    },
    [controller, copy, host, lineNow, onSelect, openLexpad, toggleFullscreen, toggleMini],
  );

  // The keyboard (§14): a word cursor first (W), then the table.
  useEffect(() => {
    const onKey = (e: KeyboardEvent): void => {
      wake();
      if (e.defaultPrevented) return;
      if (wordCursor !== null && moveCursor(e)) return;
      const s = usePlayer.getState();
      // A held ↑ stops at 100% once; a fresh press goes on (§6.3).
      if (
        e.key === 'ArrowUp' &&
        e.repeat &&
        s.prefs.volume <= 1 &&
        s.prefs.volume + VOLUME_STEP > 1 &&
        !isTypingTarget(e.target)
      ) {
        e.preventDefault();
        controller.setVolume(1, { hud: true });
        return;
      }
      // Arrow keys inside a menu, a slider, a list or a form control belong to it.
      const target = e.target as HTMLElement | null;
      if (
        e.key.startsWith('Arrow') &&
        target?.closest(
          '[role="menu"], [role="slider"], [role="listbox"], [role="radiogroup"], [role="tablist"], select, input',
        ) != null
      )
        return;
      const cmd = commandFor(e, {
        os,
        typing: isTypingTarget(e.target),
        singleKeys: s.prefs.settings.singleKeys,
      });
      if (cmd === undefined) return;
      // While a dialog is open only Escape and its own keys work.
      if (s.dialog !== null && cmd !== 'escape' && cmd !== 'shortcuts') return;
      // Space on a focused button presses that button.
      if (cmd === 'playPause' && e.key === ' ' && target instanceof HTMLButtonElement) return;
      e.preventDefault();
      run(cmd);
    };
    const moveCursor = (e: KeyboardEvent): boolean => {
      const c = wordCursor;
      if (c === null) return false;
      const s = usePlayer.getState();
      const tr = trackIn(s, c.slot);
      const cue = tr?.cues[c.cue];
      if (tr === undefined || cue === undefined) {
        setWordCursor(null);
        return false;
      }
      const tokens = cueTokens(cue);
      const words = tokens.flatMap((tk, i) => (tk.word ? [i] : []));
      const at = words.indexOf(c.to);
      if (e.key === 'Escape') {
        e.preventDefault();
        setWordCursor(null);
        return true;
      }
      if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
        e.preventDefault();
        const dir = e.key === 'ArrowRight' ? 1 : -1;
        const next = words[Math.max(0, Math.min(words.length - 1, at + dir))] ?? c.to;
        setWordCursor(e.shiftKey ? { ...c, to: next } : { ...c, from: next, to: next });
        return true;
      }
      if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
        e.preventDefault();
        const order: SlotNumber[] = e.key === 'ArrowUp' ? [2, 3, 1] : [1, 3, 2];
        for (const slot of order) {
          if (slot === c.slot) continue;
          const other = trackIn(s, slot);
          if (other === undefined) continue;
          const idx = controller.activeIn(other, controller.time())[0];
          const oc = idx === undefined ? undefined : other.cues[idx];
          if (idx === undefined || oc === undefined) continue;
          const first = cueTokens(oc).findIndex((tk) => tk.word);
          if (first >= 0) {
            setWordCursor({ slot, cue: idx, from: first, to: first });
            break;
          }
        }
        return true;
      }
      if (e.key === 'Enter') {
        e.preventDefault();
        const el = rootRef.current?.querySelector<HTMLElement>(
          `[data-slot="${String(c.slot)}"] [data-cue="${String(c.cue)}"][data-tok="${String(c.to)}"]`,
        );
        const rect =
          el?.getBoundingClientRect() ?? new DOMRect(window.innerWidth / 2, window.innerHeight - 160, 1, 1);
        setWordCursor(null);
        onSelect(c, rect, { keyboard: true });
        return true;
      }
      return false;
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  }, [controller, os, run, wake, wordCursor, onSelect]);

  // The menu bar's Playback and Subtitles menus (macOS) and the right-click
  // menu send the same commands; the right-click menu's speeds and audio
  // tracks carry their value.
  useEffect(
    () =>
      host.onMenu((c) => {
        const m = parseMenuCommand(c);
        if (m.kind === 'speed') controller.setSpeed(m.value);
        else if (m.kind === 'audio') void controller.setAudioTrack(m.index);
        else run(m.command as Command);
      }),
    [host, run, controller],
  );

  /* ---------------------------------------------------------- the right-click menu */

  const openContextMenu = useCallback(
    (
      word: { sel: WordSelection; rect: DOMRect; text: string } | null,
      position?: { x: number; y: number },
    ): void => {
      const win = host.window;
      if (win.contextMenu === undefined) return;
      const s = usePlayer.getState();
      ctxWord.current = word;
      const tracks = ([1, 2, 3] as const).flatMap((n) => {
        const tr = trackIn(s, n);
        return tr === undefined ? [] : [{ slot: n, name: languageLabel(tr.lang), on: slotVisible(s, n) }];
      });
      const audio = (s.playback?.info.audio ?? []).map((a, i) => ({
        index: a.index,
        name: audioName(a.language ?? a.languageTag, a.title, i + 1),
        on: (s.audio ?? s.playback?.plan.audio?.index) === a.index,
      }));
      const items = contextMenuItems({
        os,
        hasVideo: s.file !== null && s.phase !== 'error',
        paused: s.paused,
        speed: s.speed,
        speeds: SPEEDS,
        skip: s.prefs.settings.skip,
        tracks,
        subtitlesOn: s.master,
        audio,
        fullscreen: s.fullscreen,
        onTop: s.onTop,
        mini: s.mini,
        word: word?.text ?? null,
        transcriptOpen: s.panel === 'transcript',
        lineShown: lineNow() !== '',
      });
      void win.contextMenu(items, position).catch(() => undefined);
    },
    [host, os, lineNow],
  );
  // The keyboard's menu (the menu key, Shift+F10): drawn for what has focus,
  // at that element, never at wherever the mouse was left.
  const keyMenuAt = useRef(0);
  const openFromKeyboard = useCallback((): void => {
    const root = rootRef.current;
    const c = wordCursor;
    if (c !== null) {
      const el = root?.querySelector<HTMLElement>(
        `[data-slot="${String(c.slot)}"] [data-cue="${String(c.cue)}"][data-tok="${String(c.to)}"]`,
      );
      if (el !== null && el !== undefined) {
        const r = el.getBoundingClientRect();
        openContextMenu({ sel: c, rect: r, text: el.textContent }, keyboardMenuPoint(r));
        return;
      }
    }
    const active = document.activeElement;
    const r =
      active instanceof HTMLElement && active !== document.body && root?.contains(active) === true
        ? active.getBoundingClientRect()
        : (root?.getBoundingClientRect() ?? new DOMRect(0, 0, window.innerWidth, window.innerHeight));
    openContextMenu(null, active === document.body ? centreOf(r) : keyboardMenuPoint(r));
  }, [openContextMenu, wordCursor]);
  useEffect(() => {
    const onKey = (e: KeyboardEvent): void => {
      if (!isMenuKey(e) || isTypingTarget(e.target)) return;
      e.preventDefault();
      keyMenuAt.current = Date.now();
      openFromKeyboard();
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  }, [openFromKeyboard]);
  const onContextMenu = (e: MouseEvent<HTMLElement>): void => {
    // A text field keeps the system's own Cut, Copy and Paste.
    if (isTypingTarget(e.target)) return;
    e.preventDefault();
    // The keyboard's own menu is already up (a browser may still send this event).
    if (e.button !== 2 && Date.now() - keyMenuAt.current < KEY_MENU_GRACE_MS) return;
    // A dialog, the card or a panel is not the video: only the system menu is kept away.
    const target = e.target as HTMLElement;
    if (target.closest('[role="dialog"], [role="menu"], [data-player-overlay]') !== null) return;
    openContextMenu(null);
  };

  /* ---------------------------------------------------------- the video's own clicks */

  // A press that moves becomes a window drag, and then never a click.
  const press = useRef<{ x: number; y: number; dragged: boolean } | null>(null);
  const onVideoDown = (e: PointerEvent<HTMLDivElement>): void => {
    // Full screen has no window to move, and a finger on a touch screen taps.
    if (
      e.button !== 0 ||
      e.target !== e.currentTarget ||
      !mayDragWindow(e.pointerType, usePlayer.getState().fullscreen)
    ) {
      press.current = null;
      return;
    }
    press.current = { x: e.clientX, y: e.clientY, dragged: false };
  };
  const onVideoMove = (e: PointerEvent<HTMLDivElement>): void => {
    const p = press.current;
    if (p === null || p.dragged || (e.buttons & 1) === 0) return;
    if (!mayDragWindow(e.pointerType, usePlayer.getState().fullscreen)) return;
    if (Math.hypot(e.clientX - p.x, e.clientY - p.y) < DRAG_WINDOW_PX) return;
    p.dragged = true;
    void host.window.startDragging().catch(() => undefined);
  };
  const dragged = (): boolean => press.current?.dragged === true;
  const onVideoClick = (e: MouseEvent<HTMLDivElement>): void => {
    if (e.target !== e.currentTarget) return;
    if (dragged()) return;
    if (usePlayer.getState().file === null) return;
    controller.togglePlay();
    setGlyph({ key: Date.now(), icon: controller.isPlaying() ? 'play' : 'pause' });
  };
  const onVideoDouble = (e: MouseEvent<HTMLDivElement>): void => {
    if (e.target !== e.currentTarget) return;
    if (dragged()) return;
    // The two clicks of a double-click toggled play twice: it is as it was.
    toggleFullscreen();
  };

  /* ---------------------------------------------------------- the one-time offer (§24.6) */

  useEffect(() => {
    if (phase === 'empty' && offerState.earned && !offerState.done && !offerShown) {
      void controller.media.defaultPlayer
        .status(['mkv', 'mp4'])
        .then((st) => {
          if (st.types.every((x) => x.isDefault))
            updatePrefs((p) => ({ ...p, offer: { ...p.offer, done: true } }));
          else setOfferShown(true);
        })
        .catch(() => undefined);
    }
  }, [phase, offerState, offerShown, controller]);

  const playing = file !== null && phase !== 'error';
  // The end summary stands alone over the blurred picture (mock-up 16); the window's own buttons stay.
  const showChrome = !summary && (chrome || paused);
  const hasPanel = panel !== null && !small && playing && !mini;

  const subtitleReader = useMemo(
    () => (readAloud ? <ReadAloud controller={controller} /> : null),
    [readAloud, controller],
  );

  return (
    // The whole window is the page's one landmark: the Player has no header or navigation of its own.
    <main
      ref={rootRef}
      className={cx(
        styles.win,
        hasPanel && styles.hasPanel,
        !showChrome && playing && !summary && styles.idle,
        mini && styles.mini,
      )}
      data-player-theme={playerTheme}
      data-os={os}
      data-small={small ? '' : undefined}
      onPointerMove={(e) => {
        const last = lastPointer.current;
        lastPointer.current = { x: e.clientX, y: e.clientY };
        overZone.current =
          (e.target as HTMLElement).closest('[data-chrome-zone], [data-player-overlay]') !== null;
        if (last === null || Math.abs(last.x - e.clientX) > WAKE_PX || Math.abs(last.y - e.clientY) > WAKE_PX)
          wake();
      }}
      onFocusCapture={wake}
      onContextMenu={onContextMenu}
    >
      <div className={styles.area}>
        <video
          ref={videoRef}
          className={cx(styles.video, summary && styles.blurred, !playing && styles.hidden)}
          playsInline
          disablePictureInPicture
        />
        {summary ? <div className={styles.summaryScrim} aria-hidden="true" /> : null}
        {playing && !mini ? (
          <div
            className={styles.hit}
            onPointerDown={onVideoDown}
            onPointerMove={onVideoMove}
            onClick={onVideoClick}
            onDoubleClick={onVideoDouble}
            aria-hidden="true"
          />
        ) : null}
        {playing ? (
          <SubtitleLayer
            controller={controller}
            notebookWords={notebookWords}
            selection={selection}
            onSelect={onSelect}
            onWordContext={(sel, rect, text) => {
              openContextMenu({ sel, rect, text });
            }}
            noticeRect={noticeRect}
            wordCursor={wordCursor}
          />
        ) : null}
        {playing ? <Processing /> : null}
        {glyph !== null ? (
          <div key={glyph.key} className={styles.glyph} aria-hidden="true">
            <PIcon name={glyph.icon} size={28} />
          </div>
        ) : null}
        {playing && !mini ? (
          <div className={cx(styles.chrome, showChrome && styles.chromeShown)}>
            <div className={styles.scrimTop} aria-hidden="true" />
            <div className={styles.scrimBottom} aria-hidden="true" />
            <TopBar
              controller={controller}
              os={os}
              onLexpad={openLexpad}
              onShortcuts={() => {
                usePlayer.setState({ dialog: 'shortcuts' });
              }}
              onSettings={() => {
                usePlayer.setState({ dialog: 'settings' });
              }}
            />
            <ControlBar controller={controller} onFullscreen={toggleFullscreen} onMini={toggleMini} />
          </div>
        ) : null}
        {playing && mini ? <MiniChrome controller={controller} onBack={toggleMini} /> : null}
        {!mini ? (
          <>
            <Notices controller={controller} mod={mod} boxRef={noticeRef} />
            <DropPrompt controller={controller} />
          </>
        ) : null}
        <SyncPicker controller={controller} />
      </div>
      {phase === 'empty' ? (
        <Empty
          controller={controller}
          os={os}
          offer={
            offerShown && !offerState.done ? (
              <DefaultOffer
                controller={controller}
                os={os}
                onDone={() => {
                  updatePrefs((p) => ({ ...p, offer: { ...p.offer, done: true } }));
                  setOfferShown(false);
                }}
              />
            ) : null
          }
          onLexpad={openLexpad}
          onShortcuts={() => {
            usePlayer.setState({ dialog: 'shortcuts' });
          }}
          onSettings={() => {
            usePlayer.setState({ dialog: 'settings' });
          }}
        />
      ) : null}
      {phase === 'empty' ? <Notices controller={controller} mod={mod} /> : null}
      {phase === 'error' ? <ErrorScreen controller={controller} /> : null}
      {playing && !mini ? (
        <SidePanel
          controller={controller}
          onSelectText={onTranscriptSelect}
          notebookWords={notebookWords}
          onToggleNotebookWords={() => {
            updatePrefs((p) => ({
              ...p,
              settings: { ...p.settings, markNotebook: !p.settings.markNotebook },
            }));
          }}
        />
      ) : null}
      {card !== null ? (
        <AddWordCard
          key={`${card.sentence}-${String(card.at)}-${card.headword ?? ''}`}
          controller={controller}
          request={card}
        />
      ) : null}
      <EndSummary controller={controller} proLine={null} showPhone />
      {dialog === 'settings' ? (
        <SettingsDialog
          controller={controller}
          os={os}
          onClose={() => {
            usePlayer.setState({ dialog: null });
          }}
        />
      ) : null}
      {dialog === 'shortcuts' ? (
        <ShortcutSheet
          os={os}
          onClose={() => {
            usePlayer.setState({ dialog: null });
          }}
        />
      ) : null}
      {os === 'windows' && !mini && (showChrome || !playing || summary) ? (
        <CaptionButtons controller={controller} />
      ) : null}
      {drag !== null ? <DragOverlay names={drag} at={controller.time()} /> : null}
      {firstOpen ? (
        <FirstOpen
          controller={controller}
          onDone={() => {
            updatePrefs((p) => ({ ...p, firstOpenDone: true }));
            setFirstOpen(false);
          }}
        />
      ) : null}
      {subtitleReader}
      {playing ? <div className={styles.dragRegion} data-tauri-drag-region="" aria-hidden="true" /> : null}
    </main>
  );
}

/** An audio stream in the right-click menu: its language, its title in brackets, else its number. */
function audioName(lang: string | null, title: string | null, n: number): string {
  const name = lang !== null ? languageName(lang) : t('player.ctx.audioN', { n });
  return title !== null && title !== '' ? `${name} (${title})` : name;
}

/** "Read Subtitle 1 aloud with my screen reader" (§18): a polite live region mirroring it. */
function ReadAloud({ controller }: { controller: PlayerController }): React.JSX.Element {
  const [line, setLine] = useState('');
  useEffect(() => {
    let last = '';
    return controller.onTick((time) => {
      const tr = trackIn(usePlayer.getState(), 1);
      if (tr === undefined) return;
      const text = controller
        .activeIn(tr, time)
        .map((i) => tr.cues[i]?.text ?? '')
        .join(' ');
      if (text !== last) {
        last = text;
        setLine(text);
      }
    });
  }, [controller]);
  return (
    <div className={styles.srOnly} aria-live="polite">
      {line}
    </div>
  );
}
