function useModal(onClose: () => void): {
  ref: React.RefObject<HTMLDivElement | null>;
  onKeyDown: (e: KeyboardEvent<HTMLDivElement>) => void;
} {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const back = document.activeElement as HTMLElement | null;
    const first = ref.current?.querySelector<HTMLElement>(
      'button, [href], input, select, [tabindex]:not([tabindex="-1"])',
    );
    first?.focus({ preventScroll: true });
    return () => {
      back?.focus({ preventScroll: true });
    };
  }, []);
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>): void => {
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      onClose();
      return;
    }
    if (e.key !== 'Tab') return;
    const items = [
      ...(ref.current?.querySelectorAll<HTMLElement>(
        'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])',
      ) ?? []),
    ];
    const first = items[0];
    const last = items[items.length - 1];
    if (first === undefined || last === undefined) return;
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  };
  return { ref, onKeyDown };
}

/* ================================================================ Shortcuts */

export function ShortcutSheet({ os, onClose }: { os: Os; onClose: () => void }): React.JSX.Element {
  const { ref, onKeyDown } = useModal(onClose);
  const mod = os === 'macos' ? '⌘' : 'Ctrl';
  return (
    <div className={styles.scrimLight} onClick={onClose}>
      <div
        ref={ref}
        className={styles.sheet}
        role="dialog"
        aria-modal="true"
        aria-labelledby="keys-title"
        onClick={(e) => {
          e.stopPropagation();
        }}
        onKeyDown={onKeyDown}
        data-player-overlay=""
      >
        <div className={styles.sheetHead}>
          <h2 id="keys-title" className={styles.h2}>
            {t('player.keys.title')}
          </h2>
          <span className={styles.small}>{t('player.keys.windowsNote')}</span>
          <span className={styles.close}>
            <IconButton icon="x" label={t('player.keys.close')} small onClick={onClose} tipSide="down" />
          </span>
        </div>
        <div className={styles.cols}>
          {sheet(mod).map((g) => (
            <div key={g.title}>
              <h3 className={styles.group}>{t(g.title as MessageKey)}</h3>
              <dl className={styles.list}>
                {g.rows.map((r) => (
                  <div key={r.label} className={styles.keyRow}>
                    <dt className={styles.keyLabel}>{t(r.label as MessageKey)}</dt>
                    <dd className={styles.keyCaps} dir="ltr">
                      {r.keys.map((k) => (
                        <Kbd key={k}>{k}</Kbd>
                      ))}
                    </dd>
                  </div>
                ))}
              </dl>
            </div>
          ))}
        </div>
        <p className={styles.sheetFoot}>
          {t('player.keys.press')} <Kbd>?</Kbd> {t('player.keys.anyTime')} {t('player.keys.foot')}
        </p>
      </div>
    </div>
  );
}

/* ================================================================ Settings */

type Section = 'playback' | 'subtitles' | 'audio' | 'files' | 'shortcuts' | 'account';

const SECTIONS: { id: Section; label: MessageKey }[] = [
  { id: 'playback', label: 'player.set.playback' },
  { id: 'subtitles', label: 'player.set.subtitles' },
  { id: 'audio', label: 'player.set.audio' },
  { id: 'files', label: 'player.set.files' },
  { id: 'shortcuts', label: 'player.set.shortcuts' },
  { id: 'account', label: 'player.set.account' },
];

interface SettingsProps {
  controller: PlayerController;
  os: Os;
  onClose: () => void;
  initial?: Section;
}

export function SettingsDialog({
  controller,
  os,
  onClose,
  initial = 'playback',
}: SettingsProps): React.JSX.Element {
  const [section, setSection] = useState<Section>(initial);
  const { ref, onKeyDown } = useModal(onClose);
  const settings = usePlayer((s) => s.prefs.settings);
  const audioGraph = usePlayer((s) => s.audioGraph);
  const set = <K extends keyof PlayerSettings>(key: K, value: PlayerSettings[K]): void => {
    updatePrefs((p) => ({ ...p, settings: { ...p.settings, [key]: value } }));
  };
  const toggle = (key: keyof PlayerSettings, label: MessageKey, sub?: MessageKey): ReactNode => (
    <SettingRow key={key} title={t(label)} sub={sub ? t(sub) : undefined}>
      <Switch
        checked={settings[key] === true}
        label={t(label)}
        onChange={(on) => {
          set(key, on as never);
          if (key === 'boost' || key === 'evenOut') controller.setVolume(usePlayer.getState().prefs.volume);
        }}
      />
    </SettingRow>
  );
  return (
    <div className={styles.scrim} onClick={onClose}>
      <div
        ref={ref}
        className={styles.settings}
        role="dialog"
        aria-modal="true"
        aria-labelledby="settings-title"
        onClick={(e) => {
          e.stopPropagation();
        }}
        onKeyDown={onKeyDown}
        data-player-overlay=""
      >
        <nav className={styles.nav} aria-label={t('player.set.title')}>
          <h2 id="settings-title" className={styles.navTitle}>
            {t('player.set.title')}
          </h2>
          {SECTIONS.map((s) => (
            <button
              key={s.id}
              type="button"
              className={cx(styles.navItem, section === s.id && styles.navOn)}
              aria-current={section === s.id ? 'page' : undefined}
              onClick={() => {
                setSection(s.id);
              }}
            >
              {t(s.label)}
            </button>
          ))}
        </nav>
        <div className={styles.pane}>
          <div className={styles.paneHead}>
            <h3 className={styles.paneTitle}>
              {t(SECTIONS.find((s) => s.id === section)?.label ?? 'player.set.playback')}
            </h3>
            <span className={styles.close}>
              <IconButton icon="x" label={t('player.set.close')} small onClick={onClose} tipSide="down" />
            </span>
          </div>
          <div className={styles.rows}>
            {section === 'playback' ? (
              <>
                {toggle('resume', 'player.set.resume', 'player.set.resumeSub')}
                <SettingRow title={t('player.set.next')} sub={t('player.set.nextSub')}>
                  <Choice
                    value={String(settings.nextDelay)}
                    options={['5', '10', '15'].map((v) => ({
                      value: v,
                      label: t('player.set.seconds', { count: v }),
                    }))}
                    label={t('player.set.nextDelay')}
                    disabled={!settings.nextEpisode}
                    onChange={(v) => {
                      set('nextDelay', Number(v) as 5 | 10 | 15);
                    }}
                  />
                  <Switch
                    checked={settings.nextEpisode}
                    label={t('player.set.next')}
                    onChange={(on) => {
                      set('nextEpisode', on);
                    }}
                  />
                </SettingRow>
                <SettingRow title={t('player.set.skip')} sub={t('player.set.skipSub')}>
                  <Choice
                    value={String(settings.skip)}
                    options={['5', '10'].map((v) => ({
                      value: v,
                      label: t('player.set.seconds', { count: v }),
                    }))}
                    label={t('player.set.skip')}
                    onChange={(v) => {
                      set('skip', Number(v) as 5 | 10);
                    }}
                  />
                </SettingRow>
                {toggle('resumeAfterWord', 'player.set.resumeAfterWord', 'player.set.resumeAfterWordSub')}
                {toggle('rememberSpeed', 'player.set.rememberSpeed')}
                {toggle('pauseMinimised', 'player.set.pauseMinimised')}
                <SettingRow title={t('player.set.theme')} sub={t('player.set.themeSub')}>
                  <Choice
                    value={settings.theme}
                    options={[
                      { value: 'dark', label: t('player.set.themeDark') },
                      { value: 'system', label: t('player.set.themeSystem') },
                    ]}
                    label={t('player.set.theme')}
                    onChange={(v) => {
                      set('theme', v === 'system' ? 'system' : 'dark');
                    }}
                  />
                </SettingRow>
              </>
            ) : null}
            {section === 'subtitles' ? <SubtitleSettings controller={controller} toggle={toggle} /> : null}
            {section === 'audio' ? (
              <>
                <SettingRow title={t('player.set.preferredAudio')}>
                  <Choice
                    value={settings.preferredAudio}
                    options={[
                      { value: 'original', label: t('player.set.audioOriginal') },
                      { value: 'learning', label: t('player.set.audioLearning') },
                      { value: 'own', label: t('player.set.audioOwn') },
                    ]}
                    label={t('player.set.preferredAudio')}
                    onChange={(v) => {
                      set('preferredAudio', v === 'learning' || v === 'own' ? v : 'original');
                    }}
                  />
                </SettingRow>
                {audioGraph ? toggle('boost', 'player.set.boost', 'player.set.boostSub') : null}
                {audioGraph ? toggle('evenOut', 'player.set.evenOut') : null}
              </>
            ) : null}
            {section === 'files' ? (
              <>
                {toggle('previews', 'player.set.previews', 'player.set.previewsSub')}
                <SettingRow title={t('player.set.recent')} sub={t('player.set.recentSub')}>
                  <button
                    type="button"
                    className={styles.btn}
                    onClick={() => {
                      void controller.media.clearRecent().then(() => controller.refreshRecent());
                    }}
                  >
                    {t('player.set.clearList')}
                  </button>
                  <Switch
                    checked={settings.recent}
                    label={t('player.set.recent')}
                    onChange={(on) => {
                      set('recent', on);
                      void controller.media.setRememberRecent(on);
                    }}
                  />
                </SettingRow>
                <AboutRow />
                <SettingRow title={t('player.set.openWith')} sub={t('player.set.openWithSub')}>
                  <button
                    type="button"
                    className={styles.btn}
                    onClick={() => {
                      void controller.host.openLexpad('/settings/video');
                    }}
                  >
                    {t('player.set.choose')}
                  </button>
                </SettingRow>
              </>
            ) : null}
            {section === 'shortcuts' ? (
              <>
                {toggle('singleKeys', 'player.set.singleKeys', 'player.set.singleKeysSub')}
                <ShortcutTable os={os} />
              </>
            ) : null}
            {section === 'account' ? <AccountSettings controller={controller} /> : null}
          </div>
        </div>
      </div>
    </div>
  );
}

/** The bundled FFmpeg's notice (LGPL): its version, its licence and where its source is. */
function AboutRow(): React.JSX.Element | null {
  const about = usePlayer((s) => s.engineAbout);
  if (about === null) return null;
  return (
    <SettingRow
      title={t('player.set.about')}
      sub={t('player.set.aboutBody', {
        version:
          about.version !== undefined && about.version !== ''
            ? ` ${about.version.replace(/^ffmpeg version\s*/i, '')}`
            : '',
        licence: about.licence,
      })}
    >
      <button
        type="button"
        className={styles.link}
        onClick={() => {
          platform.openExternal(FFMPEG_LEGAL);
        }}
      >
        {t('player.set.aboutLink')}
      </button>
    </SettingRow>
  );
}

/** FFmpeg's own page on its licence and where its source is (a fixed address). */
const FFMPEG_LEGAL = 'https://ffmpeg.org/legal.html';

function SettingRow({
  title,
  sub,
  children,
}: {
  title: string;
  sub?: string | undefined;
  children: ReactNode;
}): React.JSX.Element {
  return (
    <div className={styles.row}>
      <div className={styles.rowText}>
        <div className={styles.rowTitle}>{title}</div>
        {sub !== undefined ? <div className={styles.rowSub}>{sub}</div> : null}
      </div>
      <div className={styles.rowCtl}>{children}</div>
    </div>
  );
}

function Choice({
  value,
  options,
  label,
  onChange,
  disabled = false,
}: {
  value: string;
  options: { value: string; label: string }[];
  label: string;
  onChange: (v: string) => void;
  disabled?: boolean;
}): React.JSX.Element {
  return (
    <span className={styles.selectWrap}>
      <select
        className={styles.select}
        value={value}
        aria-label={label}
        disabled={disabled}
        onChange={(e) => {
          onChange(e.target.value);
        }}
      >
        {options.map((o) => (
          <option key={o.value} value={o.value}>
            {o.label}
          </option>
        ))}
      </select>
    </span>
  );
}

function SubtitleSettings({
  controller,
  toggle,
}: {
  controller: PlayerController;
  toggle: (key: keyof PlayerSettings, label: MessageKey, sub?: MessageKey) => ReactNode;
}): React.JSX.Element {
  const langs = controller.getLanguages();
  return (
    <>
      <SettingRow title={t('player.set.languages')} sub={t('player.set.languagesSub')}>
        <span className={styles.value} dir="auto">
          {langs.learning !== undefined
            ? `${languageLabel(langs.learning)} → ${languageLabel(langs.own)}`
            : t('player.set.languagesNone')}
        </span>
      </SettingRow>
      <SettingRow title={t('player.set.defaultStyle')} sub={t('player.set.defaultStyleSub')}>
        <button
          type="button"
          className={styles.link}
          onClick={() => {
            usePlayer.setState({ dialog: null, panel: 'subtitles', panelTab: 'subtitles' });
          }}
        >
          {t('player.set.editStyles')}
        </button>
      </SettingRow>
      {toggle('markNotebook', 'player.set.markNotebook', 'player.set.markNotebookSub')}
      {toggle('pauseOnPoint', 'player.set.pauseOnPoint', 'player.set.pauseOnPointSub')}
      {toggle('askEachFile', 'player.set.askEachFile', 'player.set.askEachFileSub')}
      {toggle('fixText', 'player.set.fixText', 'player.set.fixTextSub')}
      {toggle('myStyleForAss', 'player.set.myStyleForAss', 'player.set.myStyleForAssSub')}
      {toggle('readAloud', 'player.set.readAloud')}
      <SettingRow title={t('player.set.positions')} sub={t('player.set.positionsSub')}>
        <button
          type="button"
          className={styles.btn}
          onClick={() => {
            updatePrefs((p) => ({
              ...p,
              layouts: { 1: defaultLayout(1), 2: defaultLayout(2), 3: defaultLayout(3) },
            }));
            controller.notice({ text: t('player.notice.layoutReset'), icon: 'check' });
          }}
        >
          {t('player.panel.resetLayout')}
        </button>
      </SettingRow>
    </>
  );
}

function ShortcutTable({ os }: { os: Os }): React.JSX.Element {
  const mod = os === 'macos' ? '⌘' : 'Ctrl';
  return (
    <div className={styles.table}>
      {sheet(mod).map((g) => (
        <div key={g.title}>
          <h4 className={styles.group}>{t(g.title as MessageKey)}</h4>
          {g.rows.map((r) => (
            <div key={r.label} className={styles.keyRow}>
              <span className={styles.keyLabel}>{t(r.label as MessageKey)}</span>
              <span className={styles.keyCaps} dir="ltr">
                {r.keys.map((k) => (
                  <Kbd key={k}>{k}</Kbd>
                ))}
              </span>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

/** The core's reason for a word saved signed out more than a day ago (word_queue.rs `TOO_OLD`). */
export const TOO_OLD = 'too_old_to_move';

/** Why a tap on "Add to my notebook" did not send the word, in the learner's words. */
function tooOldReason(reason: string): string {
  switch (reason) {
    case 'offline':
      return t('player.set.tooOldOffline');
    case 'no_notebook_for_language':
      return t('player.set.tooOldNoNotebook');
    case 'signed_out':
      return t('player.set.tooOldSignedOut');
    default:
      return t('player.set.tooOldFailed');
  }
}

export function AccountSettings({ controller }: { controller: PlayerController }): React.JSX.Element {
  const [account, setAccount] = useState<PlayerAccount | null>(null);
  const [pending, setPending] = useState<PendingWord[] | null>(null);
  useEffect(() => {
    let live = true;
    void controller.host
      .account()
      .then((a) => {
        if (live) setAccount(a);
      })
      .catch(() => undefined);
    void controller.host.words
      .pending()
      .then((p) => {
        if (live) setPending(p);
      })
      .catch(() => undefined);
    return () => {
      live = false;
    };
  }, [controller]);
  const waiting = pending?.length ?? 0;
  const [note, setNote] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  // Words kept before sign-in whose language no notebook learns: never put in another's (§ word routing).
  const homeless = new Map<string, number>();
  if (account?.connected === true) {
    for (const p of pending ?? []) {
      const l = baseLang(p.lang);
      if (p.waiting === 'no_notebook_for_language' && l !== undefined)
        homeless.set(l, (homeless.get(l) ?? 0) + 1);
    }
  }
  // Words saved signed out more than a day ago: never moved to an account by
  // themselves (the 24 h rule, lexpad_desktop word_queue.rs); the learner
  // adds or deletes each one here.
  const tooOld = account?.connected === true ? (pending ?? []).filter((p) => p.waiting === TOO_OLD) : [];
  const [oldNote, setOldNote] = useState<Record<string, string>>({});
  const decide = async (word: PendingWord, add: boolean): Promise<void> => {
    setBusy(word.id);
    try {
      if (add) {
        const result = await controller.host.words.sendOne(word.id);
        // A failed try keeps the word here (the core keeps it too old to
        // move), with why it did not go next to it.
        setOldNote((n) => ({
          ...n,
          [word.id]: result.status === 'added' ? t('player.set.tooOldAdded') : tooOldReason(result.reason),
        }));
      } else {
        await controller.host.words.discard(word.id);
      }
    } catch (cause) {
      // Already in the notebook: it left the queue, which is what was wanted.
      if (cause !== 'duplicate') setOldNote((n) => ({ ...n, [word.id]: t('player.set.tooOldFailed') }));
    } finally {
      setBusy(null);
      setPending(await controller.host.words.pending().catch(() => pending));
    }
  };
  const start = async (lang: string): Promise<void> => {
    if (account === null) return;
    setBusy(lang);
    setNote(null);
    const inView =
      account.notebooks.find((n) => n.id === account.notebookId) ??
      account.notebooks.find((n) => n.isDefault) ??
      account.notebooks[0];
    try {
      await notebooksApi.create({
        title: t('newNotebook.namePlaceholder', { target: languageName(lang) }),
        targetLang: lang as LanguageCode,
        meaningLang: meaningFor(lang, inView?.meaningLang, inView) as LanguageCode,
      });
      await controller.host.words.flush();
      setAccount(await controller.host.account());
      setPending(await controller.host.words.pending());
    } catch (cause) {
      setNote(
        isApiError(cause, 'needsPayment')
          ? t('player.card.notebookPlan')
          : isApiError(cause, 'offline')
            ? t('player.card.offlineAdd')
            : t('player.card.notebookFailed'),
      );
    } finally {
      setBusy(null);
    }
  };
  return (
    <>
      <SettingRow
        title={account?.connected === true ? t('player.set.signedIn') : t('player.set.signedOut')}
        sub={
          pending === null
            ? undefined
            : waiting > 0
              ? account?.connected === true
                ? plural(waiting, 'player.set.keptWordsOne', 'player.set.keptWords', { count: waiting })
                : plural(waiting, 'player.set.waitingWordsOne', 'player.set.waitingWords', { count: waiting })
              : t('player.set.noWaiting')
        }
      >
        {account?.connected === true ? (
          <button
            type="button"
            className={styles.btn}
            onClick={() => {
              void controller.host.openLexpad();
            }}
          >
            {t('player.set.openLexpad')}
          </button>
        ) : (
          <button
            type="button"
            className={styles.primary}
            onClick={() => {
              void controller.host
                .connect()
                .then(() => controller.host.words.flush())
                .then(() => controller.host.account())
                .then(setAccount)
                .catch(() => undefined);
            }}
          >
            {t('player.set.signIn')}
          </button>
        )}
      </SettingRow>
      {tooOld.map((word) => (
        <SettingRow key={word.id} title={word.headword} sub={oldNote[word.id] ?? t('player.set.tooOldSub')}>
          <button
            type="button"
            className={styles.primary}
            disabled={busy !== null}
            onClick={() => void decide(word, true)}
          >
            {t('player.set.tooOldAdd')}
          </button>
          <button
            type="button"
            className={styles.btn}
            disabled={busy !== null}
            onClick={() => void decide(word, false)}
          >
            {t('player.set.tooOldDelete')}
          </button>
        </SettingRow>
      ))}
      {[...homeless.entries()].map(([lang, count]) => (
        <SettingRow
          key={lang}
          title={plural(count, 'player.set.homelessOne', 'player.set.homeless', {
            count,
            lang: languageName(lang),
          })}
          sub={note ?? t('player.set.homelessSub', { lang: languageName(lang) })}
        >
          {TARGET_LANGUAGES.includes(lang as LanguageCode) ? (
            <button
              type="button"
              className={styles.primary}
              disabled={busy !== null}
              onClick={() => void start(lang)}
            >
              {busy === lang
                ? t('player.card.starting')
                : t('player.set.startNotebook', { lang: languageName(lang) })}
            </button>
          ) : null}
        </SettingRow>
      ))}
    </>
  );
}

export type { Section };
