/**
 * The desktop app's media engine, as the Player sees it. Mirrored type for
 * type from lexpad_desktop `src/lib/media/api.ts` (the engine owns that file;
 * keep both in step, and note a change in its NOTES-player-ui.md). Files are
 * opaque ids the core handed out for what the learner dropped or chose; the
 * page never passes a path.
 *
 * Times: the `<video>` element's seconds minus `Playback.timeOffset` is the
 * file's time; cues are in the file's milliseconds.
 */

export type MediaError =
  | 'unknown_file'
  | 'ffmpeg_missing'
  | 'unreadable'
  | 'no_video'
  | 'no_encoder'
  | 'unsupported_subtitle'
  | 'unreadable_subtitle'
  | 'empty_subtitle'
  | 'too_big'
  | 'file_gone'
  | 'no_session'
  | 'timeout'
  | 'cancelled';

export type FileKind = 'video' | 'subtitle' | 'unsupportedSubtitle' | 'other';

export interface FileRef {
  id: string;
  name: string;
  kind: FileKind;
  size: number;
}

/** A drop or an open: play the first video (it replaces the current one), ask about each subtitle. */
export interface Dropped {
  videos: FileRef[];
  subtitles: FileRef[];
  unsupported: string[];
}

export type Encoder = 'videoToolbox' | 'nvenc' | 'qsv' | 'amf' | 'mediaFoundation' | 'openH264';

export interface Engine {
  available: boolean;
  version?: string;
  caps?: { h264: Encoder | null; hwaccel: string | null; zscale: boolean };
  licence: string;
  baseUrl: string;
}

export type Hdr = 'pq' | 'hlg' | 'dolbyVisionOnly';

export interface VideoStream {
  index: number;
  codec: string;
  profile: string | null;
  level: number | null;
  pixFmt: string | null;
  width: number;
  height: number;
  sar: [number, number];
  fps: number | null;
  bitDepth: number;
  interlaced: boolean;
  hdr?: Hdr;
  default: boolean;
}

export interface AudioStream {
  index: number;
  codec: string;
  profile: string | null;
  channels: number;
  layout: string | null;
  sampleRate: number | null;
  /** ISO 639-1, when the container's tag is a language the core knows. */
  language: string | null;
  languageTag: string | null;
  title: string | null;
  default: boolean;
}

export type SubtitleFormat = 'srt' | 'vtt' | 'ass';

export interface SubtitleStream {
  index: number;
  codec: string;
  kind: 'text' | 'image' | 'unknown';
  extractAs: SubtitleFormat | null;
  language: string | null;
  languageTag: string | null;
  title: string | null;
  default: boolean;
  /** Signs only. A full track the file flags forced (its only one in that language, hundreds of lines) comes as false. */
  forced: boolean;
  hearingImpaired: boolean;
  /** How many lines the container says the track holds (Matroska's statistics), when it says. */
  events?: number;
}

/** `media:subtitle-progress`: an embedded track being read out of a big file or one on a slow drive. */
export interface SubtitleProgress {
  fileId: string;
  stream: number;
  /** 0..1 of the film's length. */
  fraction: number;
}

export interface Chapter {
  /** The file's seconds (add `timeOffset` for the element's). */
  start: number;
  end: number;
  title: string | null;
}

export interface MediaInfo {
  container: string;
  brand?: string;
  duration: number | null;
  startTime: number;
  size: number;
  bitRate: number | null;
  video: VideoStream[];
  audio: AudioStream[];
  subtitles: SubtitleStream[];
  chapters: Chapter[];
}

export type Mode = 'direct' | 'remux' | 'audioTranscode' | 'videoTranscode';

export interface Plan {
  mode: Mode;
  video: {
    index: number;
    copy: boolean;
    encoder?: Encoder;
    width: number;
    height: number;
    tonemap: boolean;
    deinterlace: boolean;
  };
  audio?: { index: number; copy: boolean; delayMs: number; downmix: boolean };
  mime: string;
  timeOffset: number;
  reasons: string[];
}

export type Unplayable = { reason: 'noVideo' } | { reason: 'noEncoder' };

export interface Probe {
  info: MediaInfo;
  plan?: Plan;
  unplayable?: Unplayable;
}

/** Where a video was left, and the learner's choices for it. */
export interface Saved {
  position: number;
  duration: number;
  watched: boolean;
  updated: number;
  audio?: number;
  audioDelayMs?: number;
  subtitleOffsets?: Record<string, number>;
}

export interface Run {
  /** Pull with `?from=<offset>`. */
  url?: string;
  /** Where the run starts, in the element's seconds. */
  start: number;
}

export interface Playback {
  session: string;
  file: FileRef;
  mode: Mode;
  /** `direct`: the `<video src>`. */
  src?: string;
  /** Streamed modes: the first run. */
  run?: Run;
  mime: string;
  /** Element seconds = file seconds + timeOffset. */
  timeOffset: number;
  duration: number | null;
  plan: Plan;
  info: MediaInfo;
  /** The file's seconds where playback starts. */
  resumeAt: number;
  saved: Saved;
}

export interface Span {
  text: string;
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  strike?: boolean;
  color?: string;
}

/**
 * A picture subtitle's line (PGS, VobSub): drawn as the image it is, never
 * read as text (spec §24.8). Requested from the engine (NOTES, item 4).
 */
export interface CueImage {
  src: string;
  /** Fractions of the frame: left, top, width, height. */
  box: [number, number, number, number];
}

export interface Cue {
  /** Milliseconds of the file's timeline. */
  start: number;
  end: number;
  text: string;
  spans: Span[];
  /** Keypad position (1-9); absent is bottom centre. */
  align?: number;
  /** An exact place, fractions of the frame. */
  position?: [number, number];
  style?: string;
  image?: CueImage;
}

export interface Style {
  name: string;
  font: string;
  /** Fraction of the frame's height. */
  size: number;
  color: string;
  outlineColor: string;
  bold: boolean;
  italic: boolean;
  align: number;
}

export interface LanguageGuess {
  code: string;
  name: string;
  confidence: number;
  source: 'text' | 'fileName' | 'track';
}

export interface Track {
  key: string;
  format: SubtitleFormat;
  cues: Cue[];
  styles: Style[];
  encoding: { encoding: string; how: 'bom' | 'utf8' | 'utf16' | 'detected'; replaced: boolean };
  language: { best?: LanguageGuess; text?: LanguageGuess; fileName?: string; track?: string };
  persianLettersFixed: boolean;
  /** Punctuation typed at the start of right-to-left lines was put back at their end. */
  punctuationMoved?: boolean;
  /** Picture subtitles: every cue is an image (NOTES, item 4). */
  picture?: boolean;
}

export interface EmbeddedSubtitle {
  key: string;
  stream: number;
  codec: string;
  supported: boolean;
  language?: string;
  title?: string;
  default: boolean;
  forced: boolean;
  hearingImpaired: boolean;
}

export interface ExternalSubtitle {
  key: string;
  file: FileRef;
  /** 2 named after the video, 1 the same episode, 0 only beside it. */
  fit: number;
  hint: { lang?: string; forced: boolean; sdh: boolean };
}

export interface Subtitles {
  embedded: EmbeddedSubtitle[];
  external: ExternalSubtitle[];
}

export interface Episode {
  file: FileRef;
  season?: number;
  episode?: number;
  position: number;
  duration: number;
  watched: boolean;
}

export interface Episodes {
  items: Episode[];
  current: number;
  next?: FileRef;
  previous?: FileRef;
}

export interface DefaultPlayerStatus {
  types: { ext: string; subtitle: boolean; isDefault: boolean; current?: string; caution: boolean }[];
  /** `direct`: `request` sets it (macOS). `systemSettings`: it opens the system's page (Windows). */
  method: 'direct' | 'systemSettings';
}

/** Where in the Player a word was picked: its subtitles or the transcript panel (the surface the core sends). */
export type PickedIn = 'subtitles' | 'transcript';

export interface NewWord {
  headword: string;
  /** Where it was picked; the core sends desktop.player or desktop.player.transcript. */
  from?: PickedIn;
  /** ISO 639-1 of the subtitle it came from. */
  lang?: string;
  sentence?: string;
  memo?: string;
}

export type SavedWord =
  { status: 'added'; id: string; notebookId: string } | { status: 'queued'; pending: number; reason: string };

export interface PendingWord {
  id: string;
  headword: string;
  lang?: string;
  sentence?: string;
  memo?: string;
  savedAt: number;
  account?: string;
  waiting?: string;
}

/** One video in Continue watching (requested from the engine: NOTES, item 2). */
export interface RecentEntry {
  key: string;
  /** Granted again when the remembered file still exists. */
  fileId?: string;
  name: string;
  position: number;
  duration: number;
  watched: boolean;
  updated: number;
  missing: boolean;
  season?: number;
  episode?: number;
  /** A frame at `position`, when the engine has made one. */
  thumb?: string;
}

/** While a run converts (the engine's `media:progress`, every half second). */
export interface Progress {
  session: string;
  run: number;
  /** The element's seconds converted so far. */
  readyUntil: number;
  /** Until the first 3 s are ready: how long that will take. */
  etaSeconds?: number;
}

/** The engine's own settings file (media-settings.json). */
export interface MediaPrefs {
  rememberRecent: boolean;
  previousHandlers: Record<string, string>;
}

/** Seek-preview frames are made every this many seconds of the file (the core's thumbs::STEP_S). */
export const FRAME_STEP_S = 10;

/** The seek bar's preview frame of a file at `seconds` (the file's time): the engine's `frameUrl`. */
export function frameUrl(baseUrl: string, fileId: string, seconds: number): string {
  const s = Math.max(0, Math.floor(seconds / FRAME_STEP_S) * FRAME_STEP_S);
  return `${baseUrl}/t/${fileId}/${String(s * 1000)}.jpg`;
}
