/**
 * The Player's whole-window states: the error screen and "Getting this
 * video ready" (spec §16, mock-ups 19 and 20), the drag-over overlay (§4.3,
 * mock-up 03), the first-open soft sign-in (§4.1, mock-up 01) and the
 * one-time default-player offer (§24.6, mock-up 34).
 */
import { useEffect, useRef, useState } from 'react';
import { t } from '@/i18n/index.js';
import { AppleMark, GoogleMark } from '@/components/ui/Icon.js';
import { cx } from '@/lib/cx.js';
import type { PlayerController } from '../controller.js';
import { languageName } from '../model/languages.js';
import type { Os } from '../model/keys.js';
import { clock } from '../model/time.js';
import { usePlayer } from '../store.js';
import { LexpadMark, PIcon } from './icons.js';
import styles from './Screens.module.css';

/* ================================================================ error */

export function ErrorScreen({ controller }: { controller: PlayerController }): React.JSX.Element | null {
  const error = usePlayer((s) => s.error);
  const [copied, setCopied] = useState(false);
  if (error === null) return null;
  const open = (): void => {
    void controller.pick();
  };
  const content = ((): {
    title: string;
    body?: string;
    steps?: string[];
    actions: { label: string; run: () => void; primary?: boolean; icon?: 'folder' }[];
  } => {
    switch (error.kind) {
      case 'codec':
        return {
          title: t('player.error.codecTitle'),
          body: error.codec
            ? t('player.error.codecBody', { codec: codecName(error.codec) })
            : t('player.error.codecBodyPlain'),
          steps: [t('player.error.codecStep1'), t('player.error.codecStep2')],
          actions: [{ label: t('player.error.openAnother'), run: open, primary: true, icon: 'folder' }],
        };
      case 'damaged':
        return {
          title: t('player.error.damagedTitle', { time: clock(error.stopsAt ?? 0) }),
          body: t('player.error.damagedBody'),
          actions: [
            {
              label: t('player.error.playUpTo', { time: clock(error.stopsAt ?? 0) }),
              run: () => {
                usePlayer.setState({ phase: 'playing', error: null });
                controller.play();
              },
              primary: true,
            },
            { label: t('player.error.openAnother'), run: open },
          ],
        };
      case 'missing':
        return {
          title: t('player.error.missingTitle'),
          body: t('player.error.missingBody'),
          actions: [
            { label: t('player.error.locate'), run: open, primary: true, icon: 'folder' },
            {
              label: t('player.error.removeFromList'),
              run: () => {
                controller.library();
              },
            },
          ],
        };
      case 'noAccess':
        return {
          title: t('player.error.noAccessTitle'),
          body: t('player.error.noAccessBody'),
          actions: [{ label: t('player.error.chooseAgain'), run: open, primary: true, icon: 'folder' }],
        };
      case 'protected':
        return {
          title: t('player.error.protectedTitle'),
          body: t('player.error.protectedBody'),
          actions: [{ label: t('player.error.openAnother'), run: open, primary: true, icon: 'folder' }],
        };
      case 'engine':
        return {
          title: t('player.error.engineTitle'),
          body: t('player.error.engineBody'),
          actions: [{ label: t('player.error.openAnother'), run: open, primary: true, icon: 'folder' }],
        };
      default:
        return {
          title: t('player.error.converterTitle'),
          actions: [
            {
              label: t('player.error.tryAgain'),
              run: () => {
                const file = usePlayer.getState().file;
                if (file !== null) void controller.openVideo(file);
              },
              primary: true,
            },
            { label: t('player.error.openAnother'), run: open },
          ],
        };
    }
  })();
  return (
    <div className={styles.error} role="alert">
      <div className={styles.errorTitleBar}>{error.file ?? t('player.windowTitle')}</div>
      <div className={styles.errorBox}>
        <div className={styles.errorTile}>
          <PIcon name="alert" size={28} />
        </div>
        <h1 className={styles.errorTitle}>{content.title}</h1>
        {content.body !== undefined ? <p className={styles.errorBody}>{content.body}</p> : null}
        {content.steps !== undefined ? (
          <div className={styles.whatToDo}>
            <div className={styles.whatTitle}>{t('player.error.whatToDo')}</div>
            <ol className={styles.steps}>
              {content.steps.map((s) => (
                <li key={s}>{s}</li>
              ))}
            </ol>
          </div>
        ) : null}
        <div className={styles.errorActions}>
          {content.actions.map((a) => (
            <button
              key={a.label}
              type="button"
              className={a.primary === true ? styles.primary : styles.secondary}
              onClick={a.run}
            >
              {a.icon !== undefined ? <PIcon name={a.icon} size={18} /> : null}
              {a.label}
            </button>
          ))}
        </div>
        <button
          type="button"
          className={styles.copy}
          onClick={() => {
            void navigator.clipboard.writeText(controller.supportDetails()).then(() => {
              setCopied(true);
            });
          }}
        >
          <PIcon name="copy" size={14} />
          {copied ? t('player.error.copied') : t('player.error.copyDetails')}
        </button>
      </div>
    </div>
  );
}

function codecName(codec: string): string {
  const c = codec.toLowerCase();
  const known: Record<string, string> = {
    vp6f: 'On2 VP6',
    vp6: 'On2 VP6',
    flv1: 'Sorenson Spark',
    rv40: 'RealVideo 4',
    rv30: 'RealVideo 3',
    wmv3: 'Windows Media Video 9',
    msmpeg4v3: 'MS-MPEG4 v3',
    cinepak: 'Cinepak',
    indeo5: 'Indeo 5',
  };
  return known[c] ?? codec.toUpperCase();
}

/* ================================================================ processing */

export function Processing(): React.JSX.Element | null {
  const phase = usePlayer((s) => s.phase);
  const p = usePlayer((s) => s.playback);
  const eta = usePlayer((s) =>
    s.progress?.etaSeconds !== undefined ? Math.max(1, Math.round(s.progress.etaSeconds)) : null,
  );
  if (phase !== 'processing' || p === null) return null;
  const audio = p.info.audio.find((a) => a.index === p.plan.audio?.index);
  const video = p.info.video[0];
  const what =
    p.mode === 'audioTranscode'
      ? t('player.processing.audio', {
          codec: `${(audio?.codec ?? '').toUpperCase()}${audio && audio.channels >= 6 ? ` ${String(audio.channels - 1)}.1` : ''}`,
        })
      : t('player.processing.video', { codec: (video?.codec ?? '').toUpperCase() });
  return (
    <div className={styles.processing} role="status">
      <div className={styles.procScrim} aria-hidden="true" />
      <div className={styles.procBox}>
        <svg width="64" height="64" viewBox="0 0 64 64" className={styles.ring} aria-hidden="true">
          <circle cx="32" cy="32" r="27" className={styles.ringTrack} />
          <circle
            cx="32"
            cy="32"
            r="27"
            className={styles.ringArc}
            strokeDasharray="169.6"
            strokeDashoffset="110"
            transform="rotate(-90 32 32)"
          />
        </svg>
        <h2 className={styles.procTitle}>{t('player.processing.title')}</h2>
        <p className={styles.procLine}>
          {what}
          {eta !== null ? ` ${t('player.processing.startsIn', { count: eta })}` : ''}
        </p>
        <p className={styles.procSub}>{t('player.processing.whole')}</p>
      </div>
    </div>
  );
}

/* ================================================================ drag over */

const VIDEO_EXT =
  /\.(mkv|mp4|m4v|avi|mov|webm|wmv|asf|flv|f4v|ts|m2ts|mts|mpg|mpeg|vob|ogv|3gp|3g2|divx|rm|rmvb|mxf)$/i;
const SUB_EXT = /\.(srt|vtt|ass|ssa|sub|txt)$/i;

/** What a drag holds, by name (the drop itself is sorted by the core): videos, subtitles, the rest. */
export function sortDrag(names: readonly string[]): {
  videos: string[];
  subtitles: string[];
  other: string[];
} {
  const videos: string[] = [];
  const subtitles: string[] = [];
  const other: string[] = [];
  for (const n of names) {
    if (VIDEO_EXT.test(n)) videos.push(n);
    else if (SUB_EXT.test(n)) subtitles.push(n);
    else other.push(n);
  }
  return { videos, subtitles, other };
}

/** A subtitle's language tag in its file name ("movie.fa.srt" → "fa"), for the chip. */
export function langTagOf(name: string): string | undefined {
  const m = /[._-]([a-z]{2,3})(?:[._-](?:sdh|forced|cc))?\.(?:srt|vtt|ass|ssa|sub|txt)$/i.exec(name);
  return m?.[1]?.toLowerCase();
}

export function DragOverlay({ names, at }: { names: string[]; at: number }): React.JSX.Element {
  const playing = usePlayer((s) => s.file !== null);
  const title = usePlayer((s) => s.title?.title ?? '');
  const sorted = sortDrag(names);
  const nothing = sorted.videos.length === 0 && sorted.subtitles.length === 0;
  const verb = nothing
    ? t('player.drag.cant')
    : sorted.videos.length > 0
      ? playing
        ? t('player.drag.playInstead')
        : t('player.drag.play')
      : t('player.drag.addSubs');
  return (
    <div className={cx(styles.drag, nothing && styles.dragBad)} aria-live="polite">
      <div className={styles.dragBox}>
        <div className={styles.dragTile}>
          <PIcon name="drop" size={34} />
        </div>
        <div className={styles.dragVerb}>{verb}</div>
        <div className={styles.chips}>
          {sorted.videos.slice(0, 1).map((n) => (
            <span key={n} className={styles.chip}>
              <PIcon name="film" size={13} />
              {n}
            </span>
          ))}
          {sorted.subtitles.map((n) => {
            const tag = langTagOf(n);
            return (
              <span key={n} className={cx(styles.chip, styles.chipNeutral)}>
                <PIcon name="file" size={13} />
                {tag !== undefined ? `.${tag}${n.slice(n.lastIndexOf('.'))} · ${languageName(tag)}` : n}
              </span>
            );
          })}
          {nothing
            ? sorted.other.slice(0, 3).map((n) => (
                <span key={n} className={cx(styles.chip, styles.chipNeutral)}>
                  {n}
                </span>
              ))
            : null}
        </div>
        <div className={styles.dragLine}>
          {nothing
            ? t('player.drag.cantBody')
            : sorted.videos.length > 0 && playing
              ? t('player.drag.keeps', { title, time: clock(at) })
              : sorted.videos.length > 0 && sorted.subtitles.length > 0
                ? t('player.drag.playBody')
                : ''}
        </div>
      </div>
    </div>
  );
}

/* ================================================================ first open */

export function FirstOpen({
  controller,
  onDone,
}: {
  controller: PlayerController;
  onDone: () => void;
}): React.JSX.Element {
  const [waiting, setWaiting] = useState(false);
  // Focus goes to the dialog itself, so no button shows a ring until a key is pressed.
  const dialogRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    dialogRef.current?.focus({ preventScroll: true });
  }, []);
  const go = (provider: 'google' | 'apple'): void => {
    setWaiting(true);
    void controller.host
      .connect(provider)
      .then(() => controller.host.words.flush())
      .catch(() => undefined)
      .finally(() => {
        setWaiting(false);
        onDone();
      });
  };
  return (
    <div
      ref={dialogRef}
      tabIndex={-1}
      className={styles.first}
      role="dialog"
      aria-modal="true"
      aria-labelledby="player-first-title"
      onKeyDown={(e) => {
        if (e.key === 'Escape') onDone();
      }}
    >
      <div className={styles.firstGlow} aria-hidden="true" />
      <div className={styles.firstBox}>
        <div className={styles.firstMark}>
          <LexpadMark size={30} weight={2.2} />
        </div>
        <h1 id="player-first-title" className={styles.firstTitle}>
          {t('player.first.title')}
        </h1>
        <p className={styles.firstLead}>{t('player.first.lead')}</p>
        <div className={styles.firstButtons}>
          <button
            type="button"
            className={cx(styles.lg, styles.google)}
            disabled={waiting}
            onClick={() => {
              go('google');
            }}
          >
            <GoogleMark size={20} />
            {waiting ? t('player.card.waiting') : t('player.first.google')}
          </button>
          <button
            type="button"
            className={cx(styles.lg, styles.apple)}
            disabled={waiting}
            onClick={() => {
              go('apple');
            }}
          >
            <AppleMark size={20} />
            {t('player.first.apple')}
          </button>
          <button type="button" className={styles.skip} onClick={onDone}>
            {t('player.first.skip')}
          </button>
        </div>
        <p className={styles.firstFoot}>
          {t('player.first.foot1')}
          <br />
          {t('player.first.foot2')}
        </p>
      </div>
    </div>
  );
}

/* ================================================================ the one-time offer */

/** The six types the offer sets (§24.6). */
export const OFFER_TYPES = ['mkv', 'mp4', 'avi', 'mov', 'webm', 'm4v'] as const;

export function typesSentence(types: readonly string[]): string {
  const up = types.map((x) => (x === 'webm' ? 'WebM' : x.toUpperCase()));
  if (up.length <= 2)
    return up.length === 2 ? t('player.types.and', { first: up[0] ?? '', last: up[1] ?? '' }) : (up[0] ?? '');
  return t('player.types.andMore', { first: `${up[0] ?? ''}, ${up[1] ?? ''}`, count: up.length - 2 });
}

export function DefaultOffer({
  controller,
  os,
  onDone,
}: {
  controller: PlayerController;
  os: Os;
  onDone: () => void;
}): React.JSX.Element {
  const [busy, setBusy] = useState(false);
  const yes = async (): Promise<void> => {
    setBusy(true);
    try {
      const status = await controller.media.defaultPlayer.request([...OFFER_TYPES]);
      const now = status.types.filter((x) => x.isDefault).map((x) => x.ext);
      if (now.length > 0) {
        controller.notice({
          text: t('player.notice.defaultsSet', { types: typesSentence(now) }),
          icon: 'check',
          ...(os === 'macos'
            ? {
                action: {
                  label: t('action.undo'),
                  run: () => {
                    void controller.media.defaultPlayer.restore(now).catch(() => {
                      controller.notice({ text: t('player.offer.failed'), icon: 'alert' });
                    });
                  },
                },
              }
            : {}),
        });
      }
      onDone();
    } catch {
      controller.notice({ text: t('player.offer.failed'), icon: 'alert' });
      setBusy(false);
    }
  };
  return (
    <section className={styles.offer} role="region" aria-label={t('player.offer.label')}>
      <div className={styles.offerTop}>
        <span className={styles.offerTile}>
          <PIcon name="film" size={22} />
        </span>
        <div className={styles.offerText}>
          <h2 className={styles.offerTitle}>{t('player.offer.title')}</h2>
          <p className={styles.offerBody}>
            {os === 'windows' ? t('player.offer.bodyWindows') : t('player.offer.bodyMac')}
          </p>
          <div className={styles.fchips}>
            {OFFER_TYPES.map((x) => (
              <span key={x} className={styles.fchip}>
                {x === 'webm' ? 'WebM' : x.toUpperCase()}
              </span>
            ))}
          </div>
        </div>
        <button type="button" className={styles.offerX} aria-label={t('player.offer.close')} onClick={onDone}>
          <PIcon name="x" size={16} />
        </button>
      </div>
      <div className={styles.offerFoot}>
        <button
          type="button"
          className={styles.offerLink}
          onClick={() => {
            onDone();
            void controller.host.openLexpad('/settings/video');
          }}
        >
          {t('player.offer.choose')}
        </button>
        <span className={styles.spacer} />
        <button type="button" className={styles.offerNot} onClick={onDone}>
          {t('player.offer.notNow')}
        </button>
        <button type="button" className={styles.offerYes} disabled={busy} onClick={() => void yes()}>
          {os === 'windows' ? t('player.offer.windows') : t('player.offer.yes')}
        </button>
      </div>
    </section>
  );
}
