/**
 * "Mark words already in my notebook" (spec §11.1, off by default): the
 * headwords of the notebook in a subtitle's language, read from this
 * computer's copy of the notebook (the learning window keeps it in the same
 * IndexedDB). Nothing is fetched for it; signed out or before the first
 * sync there is nothing to mark, and nothing is marked.
 */
import { useEffect, useState } from 'react';
import { listNotebooks, listWords } from '@/db/repo.js';

/** Up to this many headwords are matched; a bigger notebook keeps its newest. */
const MAX_MARKED = 20_000;

export async function notebookHeadwords(lang: string): Promise<Set<string>> {
  const base = lang.split(/[-_]/)[0];
  const notebooks = (await listNotebooks()).filter((n) => n.targetLang.split(/[-_]/)[0] === base);
  const out = new Set<string>();
  for (const nb of notebooks) {
    for (const w of await listWords(nb.id)) {
      if (out.size >= MAX_MARKED) return out;
      out.add(w.headword.toLocaleLowerCase());
    }
  }
  return out;
}

export function useNotebookWords(enabled: boolean, lang: string | undefined): ReadonlySet<string> | null {
  const [words, setWords] = useState<ReadonlySet<string> | null>(null);
  useEffect(() => {
    if (!enabled || lang === undefined) return;
    let live = true;
    void notebookHeadwords(lang)
      .then((set) => {
        if (live) setWords(set);
      })
      .catch(() => {
        if (live) setWords(null);
      });
    return () => {
      live = false;
    };
  }, [enabled, lang]);
  return enabled && lang !== undefined ? words : null;
}
