/**
 * The control bar's menus (spec §6.4–6.6, §6.9), drawn as the mock-ups
 * 08-subtitles-menu, 22-windows-speed and 23-audio-volume: glass, 36 px rows,
 * a check on the current choice, switches for the two sound options.
 */
import { t } from '@/i18n/index.js';
import type { AudioStream, SubtitleStream } from '@/lib/platform/media.js';
import { cx } from '@/lib/cx.js';
import { SPEEDS, type PlayerController } from '../controller.js';
import { embeddedTrackName } from '../model/embedded.js';
import { language, languageLabel } from '../model/languages.js';
import type { SlotNumber } from '../model/slots.js';
import { slotVisible, usePlayer } from '../store.js';
import { VolumeSlider } from './ControlBar.js';
import { PIcon } from './icons.js';
import { Hr, Kbd, MenuTitle, Popover, Row, Switch } from './kit.js';
import { trackColourVar } from './subtitleStyle.js';
import styles from './menus.module.css';

interface MenuProps {
  controller: PlayerController;
  anchor: HTMLElement | null;
  onClose: () => void;
}

export function SpeedMenu({ controller, anchor, onClose }: MenuProps): React.JSX.Element {
  const speed = usePlayer((s) => s.speed);
  const keep = usePlayer((s) => s.prefs.settings.keepVoice);
  return (
    <Popover
      label={t('player.speed.title')}
      onClose={onClose}
      anchor={anchor}
      className={cx(styles.menu, styles.speed)}
    >
      <MenuTitle>{t('player.speed.title')}</MenuTitle>
      {SPEEDS.map((s) => {
        const on = Math.abs(s - speed) < 0.001;
        return (
          <Row
            key={s}
            role="menuitemradio"
            checked={on}
            onClick={() => {
              controller.setSpeed(s);
              onClose();
            }}
          >
            <span className={styles.lead}>
              {on ? <PIcon name="check" size={18} className={styles.ck} /> : null}
            </span>
            <span className={styles.num}>{`${String(s)}×`}</span>
            {s === 1 ? <span className={styles.sub}>{t('player.speed.normal')}</span> : null}
          </Row>
        );
      })}
      <Hr />
      <div className={styles.switchRow}>
        <span>{t('player.speed.keepVoice')}</span>
        <span className={styles.sub}>
          <Switch
            small
            checked={keep}
            label={t('player.speed.keepVoice')}
            onChange={(on) => {
              controller.setKeepVoice(on);
            }}
          />
        </span>
      </div>
    </Popover>
  );
}

/** "5.1 · converted from DTS", "Stereo · AAC", "Commentary · Stereo" (§6.5). */
export function audioLine(a: AudioStream, converted: boolean): string {
  const layout =
    a.channels >= 6
      ? t('player.audio.channels', { count: a.channels - 1 })
      : a.channels === 1
        ? t('player.audio.mono')
        : t('player.audio.stereo');
  if (a.title !== null && /comment/i.test(a.title)) return t('player.audio.commentary', { layout });
  const codec = codecName(a.codec);
  return converted
    ? t('player.audio.converted', { layout, codec })
    : t('player.audio.plain', { layout, codec });
}

function codecName(codec: string): string {
  const c = codec.toLowerCase();
  if (c === 'dts' || c.startsWith('dts')) return 'DTS';
  if (c === 'ac3') return 'AC-3';
  if (c === 'eac3') return 'E-AC-3';
  if (c === 'truehd') return 'TrueHD';
  return codec.toUpperCase();
}

export function AudioMenu({ controller, anchor, onClose }: MenuProps): React.JSX.Element {
  const list = usePlayer((s) => s.playback?.info.audio ?? []);
  const current = usePlayer((s) => s.audio);
  const copied = usePlayer((s) => s.playback?.plan.audio?.copy ?? true);
  const evenOut = usePlayer((s) => s.prefs.settings.evenOut);
  const audioGraph = usePlayer((s) => s.audioGraph);
  return (
    <Popover
      label={t('player.audio.title')}
      onClose={onClose}
      anchor={anchor}
      className={cx(styles.menu, styles.audio)}
    >
      <MenuTitle>{t('player.audio.title')}</MenuTitle>
      {list.map((a) => {
        const on = a.index === current;
        const lang = language(a.language ?? a.languageTag);
        return (
          <Row
            key={a.index}
            role="menuitemradio"
            checked={on}
            onClick={() => {
              void controller.setAudioTrack(a.index);
              onClose();
            }}
          >
            <span className={styles.lead}>
              {on ? <PIcon name="check" size={18} className={styles.ck} /> : null}
            </span>
            <span className={styles.stack}>
              <span>{lang?.autonym ?? a.title ?? t('player.audio.unknown')}</span>
              <span className={styles.small}>{audioLine(a, on && !copied)}</span>
            </span>
            {a.default ? <span className={styles.sub}>{t('player.audio.original')}</span> : null}
          </Row>
        );
      })}
      {audioGraph ? <Hr /> : null}
      {audioGraph ? (
        <div className={styles.switchRow}>
          <span>{t('player.audio.evenOut')}</span>
          <span className={styles.sub}>
            <Switch
              small
              checked={evenOut}
              label={t('player.audio.evenOut')}
              onChange={(on) => {
                controller.setEvenOut(on);
              }}
            />
          </span>
        </div>
      ) : null}
    </Popover>
  );
}

export function VolumeMenu({ controller, anchor, onClose }: MenuProps): React.JSX.Element {
  return (
    <Popover
      label={t('player.ctl.volume')}
      onClose={onClose}
      anchor={anchor}
      className={cx(styles.menu, styles.volume)}
      role="dialog"
    >
      <div className={styles.volumeBox}>
        <VolumeSlider controller={controller} />
      </div>
    </Popover>
  );
}

export function SubtitlesMenu({ controller, anchor, onClose }: MenuProps): React.JSX.Element {
  const master = usePlayer((s) => s.master);
  const slots = usePlayer((s) => s.slots);
  const tracks = usePlayer((s) => s.tracks);
  const state = usePlayer();
  const embedded = usePlayer((s) => s.playback?.info.subtitles ?? []);
  const reads = usePlayer((s) => s.reading);
  const usedStreams = new Set(
    Object.values(tracks)
      .map((tr) => tr.source.stream)
      .filter((x): x is number => x !== undefined),
  );
  const unused = embedded.filter((e) => e.kind !== 'unknown' && !usedStreams.has(e.index));
  return (
    <Popover
      label={t('player.ctl.subtitles')}
      onClose={onClose}
      anchor={anchor}
      className={cx(styles.menu, styles.subs)}
    >
      <div className={cx(styles.switchRow, styles.bold)}>
        <span>{t('player.subs.show')}</span>
        <span className={styles.sub}>
          <Kbd>C</Kbd>
          <Switch
            checked={master}
            label={t('player.subs.show')}
            onChange={(on) => {
              controller.setMaster(on);
            }}
          />
        </span>
      </div>
      <Hr />
      {([1, 2, 3] as const).map((n) => {
        const id = slots[n - 1];
        const tr = id === null || id === undefined ? undefined : tracks[id];
        if (tr === undefined) return null;
        const on = slotVisible(state, n);
        const place =
          n === 1 ? t('player.place.bottom') : n === 2 ? t('player.place.top') : t('player.place.above1');
        // The file's own title for the track is shown as it is (owner, 31 Oct 2026), unless it only repeats the language.
        const fileTitle =
          tr.source.kind === 'embedded' ? ownTitle(tr.source.name, languageLabel(tr.lang)) : null;
        const source =
          tr.source.kind === 'embedded'
            ? [fileTitle === null ? null : `\u2068${fileTitle}\u2069`, t('player.subs.embedded')]
                .filter((x): x is string => x !== null)
                .join(' · ')
            : tr.source.name;
        const line = tr.picture
          ? t('player.subs.pictureLine')
          : `${t('player.subs.trackLine', { place, source })}${tr.textFixed ? ` · ${t('player.subs.textFixed')}` : ''}`;
        return (
          <Row
            key={n}
            role="menuitemcheckbox"
            checked={on}
            onClick={() => {
              controller.toggleSlot(n);
            }}
          >
            <span
              className={styles.chip}
              style={{ background: trackColourVar(state.prefs.styles[n].colour) }}
            >
              {n}
            </span>
            <span className={styles.stack}>
              <span className={styles.name}>
                <span dir="auto">{languageLabel(tr.lang)}</span>
                {tr.picture ? <span className={styles.picture}>{t('player.subs.picture')}</span> : null}
              </span>
              <span className={cx(styles.small, styles.ellip)} title={line}>
                {line}
              </span>
            </span>
            <span className={styles.sub}>
              <Kbd>{n}</Kbd>
              <span className={on ? styles.eyeOn : styles.eyeOff}>
                <PIcon name={on ? 'eye' : 'eyeOff'} size={22} />
              </span>
            </span>
          </Row>
        );
      })}
      {slots.every((x) => x === null) ? (
        <p className={styles.none}>
          {t(unused.some((e) => e.kind !== 'image') ? 'player.subs.noneButInFile' : 'player.subs.none')}
        </p>
      ) : null}
      <Row
        className={styles.dimRow}
        onClick={() => {
          onClose();
          void controller.pick();
        }}
      >
        <span className={styles.lead}>
          <PIcon name="plus" size={18} />
        </span>
        {t('player.subs.addFile')}
      </Row>
      {unused.length > 0 ? (
        <>
          <MenuTitle>{t('player.subs.inThisFile')}</MenuTitle>
          {unused.map((e) => {
            const picture = e.kind === 'image';
            const reading = reads[e.index];
            const busy = e.index in reads;
            return (
              <Row
                key={e.index}
                className={styles.dimRow}
                disabled={picture || busy}
                onClick={() => {
                  void controller.useEmbedded(e.index);
                }}
              >
                <span className={styles.lead} />
                <span className={styles.ellip} title={rowText(e, embedded, picture)}>
                  <span dir="auto">{embeddedName(e, embedded)}</span>
                  {rowTitle(e, embedded) !== null ? (
                    <>
                      {' · '}
                      <span dir="auto">{rowTitle(e, embedded)}</span>
                    </>
                  ) : null}
                  {' · '}
                  {picture ? t('player.subs.pictureRow') : t('player.subs.embedded')}
                </span>
                {picture ? (
                  <span className={styles.sub}>{t('player.subs.cantShow')}</span>
                ) : (
                  <span className={cx(styles.sub, busy ? undefined : styles.link)}>
                    {!busy
                      ? t('player.subs.use')
                      : reading === null || reading === undefined
                        ? t('player.subs.readingNow')
                        : t('player.subs.readingPercent', { percent: Math.round(reading * 100) })}
                  </span>
                )}
              </Row>
            );
          })}
        </>
      ) : null}
      <Hr />
      <Row
        onClick={() => {
          onClose();
          controller.openPanel('subtitles');
        }}
      >
        <PIcon name="sliders" size={18} />
        {t('player.subs.manage')}
        <span className={styles.sub}>
          <Kbd>S</Kbd>
        </span>
      </Row>
    </Popover>
  );
}

/** The file's own title for a track, as written, or null when it is empty or only repeats `shown`. */
function ownTitle(title: string | null | undefined, shown: string): string | null {
  const x = title?.trim() ?? '';
  if (x === '' || shown.toLowerCase().includes(x.toLowerCase())) return null;
  return x;
}

/** The title shown after a track's name in the "In this file" rows: "Persian · ValaMovie.Com". */
function rowTitle(e: SubtitleStream, all: readonly SubtitleStream[]): string | null {
  return ownTitle(e.title, embeddedName(e, all));
}

/** The whole row as one line, for its tooltip. */
function rowText(e: SubtitleStream, all: readonly SubtitleStream[], picture: boolean): string {
  return [
    embeddedName(e, all),
    rowTitle(e, all),
    picture ? t('player.subs.pictureRow') : t('player.subs.embedded'),
  ]
    .filter((x): x is string => x !== null)
    .join(' · ');
}

/** "Persian", "English (SDH)", "English (Commentary, forced)": the language from the tag, the title only to tell twins apart. */
function embeddedName(e: SubtitleStream, all: readonly SubtitleStream[]): string {
  const name = embeddedTrackName(e, all, t('player.subs.trackWord'));
  const tags = [
    e.hearingImpaired ? t('player.subs.sdh') : null,
    e.forced ? t('player.subs.forced') : null,
  ].filter((x): x is string => x !== null);
  return tags.length > 0 ? `${name} (${tags.join(', ')})` : name;
}

export function MoreMenu({
  controller,
  anchor,
  onClose,
  onMini,
}: MenuProps & { onMini: () => void }): React.JSX.Element {
  const previous = usePlayer((s) => s.episodes?.previous);
  const audioCount = usePlayer((s) => s.playback?.info.audio.length ?? 0);
  return (
    <Popover
      label={t('player.ctl.more')}
      onClose={onClose}
      anchor={anchor}
      className={cx(styles.menu, styles.more)}
    >
      <Row
        onClick={() => {
          onClose();
          controller.stepLine(0);
        }}
      >
        <PIcon name="replay" size={18} />
        {t('player.ctl.replay')}
        <span className={styles.sub}>
          <Kbd>R</Kbd>
        </span>
      </Row>
      {previous !== undefined ? (
        <Row
          onClick={() => {
            onClose();
            void controller.openVideo(previous);
          }}
        >
          <PIcon name="prev" size={18} />
          {t('player.ctl.previousEpisode')}
        </Row>
      ) : null}
      <Row
        onClick={() => {
          usePlayer.setState({ menu: 'speed' });
        }}
      >
        <PIcon name="speed" size={18} />
        {t('player.ctl.speed')}
      </Row>
      {audioCount > 1 ? (
        <Row
          onClick={() => {
            usePlayer.setState({ menu: 'audio' });
          }}
        >
          <PIcon name="audio" size={18} />
          {t('player.ctl.audio')}
        </Row>
      ) : null}
      <Row
        onClick={() => {
          onClose();
          controller.openPanel('transcript');
        }}
      >
        <PIcon name="transcript" size={18} />
        {t('player.ctl.transcript')}
        <span className={styles.sub}>
          <Kbd>T</Kbd>
        </span>
      </Row>
      <Row
        onClick={() => {
          onClose();
          onMini();
        }}
      >
        <PIcon name="mini" size={18} />
        {t('player.ctl.mini')}
        <span className={styles.sub}>
          <Kbd>I</Kbd>
        </span>
      </Row>
    </Popover>
  );
}

export type { SlotNumber };
