/**
 * The player's keys (spec §14). One table, read by the key handler and by
 * the "?" sheet, so the two can never disagree. ⌘ is Ctrl on Windows.
 * Single-key shortcuts are off while a text field has focus, and can be
 * turned off in Settings (WCAG 2.1.4); the modified ones always work.
 */

export type Command =
  | 'playPause'
  | 'back5'
  | 'forward5'
  | 'back10'
  | 'forward10'
  | 'previousLine'
  | 'nextLine'
  | 'replayLine'
  | 'slower'
  | 'faster'
  | 'normalSpeed'
  | 'nextEpisode'
  | 'previousEpisode'
  | 'toggleSubtitles'
  | 'toggleTrack1'
  | 'toggleTrack2'
  | 'toggleTrack3'
  | 'subtitlesPanel'
  | 'timingEarlier'
  | 'timingLater'
  | 'timingEarlierBig'
  | 'timingLaterBig'
  | 'heard'
  | 'pickWord'
  | 'transcript'
  | 'fullscreen'
  | 'escape'
  | 'mini'
  | 'volumeUp'
  | 'volumeDown'
  | 'mute'
  | 'nextAudio'
  | 'open'
  | 'shortcuts'
  | 'settings'
  | 'undo'
  | 'search'
  | 'lexpad'
  | 'player'
  // The right-click menu's own, with no key (contextMenu.ts).
  | 'addSubtitle'
  | 'addWord'
  | 'onTop'
  | 'copyLine';

export interface KeyLike {
  key: string;
  code?: string;
  shiftKey: boolean;
  altKey: boolean;
  metaKey: boolean;
  ctrlKey: boolean;
}

export type Os = 'macos' | 'windows' | 'linux';

/** Whether the platform's command modifier is held: ⌘ on a Mac, Ctrl elsewhere. */
export function commandKey(e: KeyLike, os: Os): boolean {
  return os === 'macos' ? e.metaKey && !e.ctrlKey : e.ctrlKey && !e.metaKey;
}

/** The modified shortcuts, which work even with single keys off. */
function modified(e: KeyLike, os: Os): Command | undefined {
  if (!commandKey(e, os) || e.altKey) return undefined;
  const k = e.key.toLowerCase();
  if (k === 'o' && !e.shiftKey) return 'open';
  if (k === ',' && !e.shiftKey) return 'settings';
  if (k === 'z' && !e.shiftKey) return 'undo';
  if (k === 'f' && !e.shiftKey) return 'search';
  if (k === '1' && !e.shiftKey) return 'lexpad';
  if (k === '2' && !e.shiftKey) return 'player';
  return undefined;
}

/** The single keys (with Shift where the table says so). */
function single(e: KeyLike): Command | undefined {
  if (e.metaKey || e.ctrlKey || e.altKey) return undefined;
  const key = e.key;
  if (e.shiftKey) {
    switch (key) {
      case 'ArrowLeft':
        return 'previousLine';
      case 'ArrowRight':
        return 'nextLine';
      case 'N':
      case 'n':
        return 'nextEpisode';
      case 'P':
      case 'p':
        return 'previousEpisode';
      case 'Z':
      case 'z':
        return 'timingEarlierBig';
      case 'X':
      case 'x':
        return 'timingLaterBig';
      case '?':
        return 'shortcuts';
      default:
        return undefined;
    }
  }
  switch (key) {
    case ' ':
    case 'k':
      return 'playPause';
    case 'ArrowLeft':
      return 'back5';
    case 'ArrowRight':
      return 'forward5';
    case 'j':
      return 'back10';
    case 'l':
      return 'forward10';
    case 'r':
      return 'replayLine';
    case '[':
      return 'slower';
    case ']':
      return 'faster';
    case '\\':
      return 'normalSpeed';
    case 'c':
      return 'toggleSubtitles';
    case '1':
      return 'toggleTrack1';
    case '2':
      return 'toggleTrack2';
    case '3':
      return 'toggleTrack3';
    case 's':
      return 'subtitlesPanel';
    case 'z':
      return 'timingEarlier';
    case 'x':
      return 'timingLater';
    case 'h':
      return 'heard';
    case 'w':
      return 'pickWord';
    case 't':
      return 'transcript';
    case 'f':
      return 'fullscreen';
    case 'Escape':
      return 'escape';
    case 'i':
      return 'mini';
    case 'ArrowUp':
      return 'volumeUp';
    case 'ArrowDown':
      return 'volumeDown';
    case 'm':
      return 'mute';
    case 'a':
      return 'nextAudio';
    case '?':
      return 'shortcuts';
    default:
      return undefined;
  }
}

export interface KeyContext {
  os: Os;
  /** A text field has focus: single keys type there. */
  typing: boolean;
  /** Settings → Shortcuts → "Single-key shortcuts". */
  singleKeys: boolean;
}

/** The command a key press asks for here, or undefined. */
export function commandFor(e: KeyLike, ctx: KeyContext): Command | undefined {
  const m = modified(e, ctx.os);
  if (m !== undefined) return m;
  // Windows: F11 is full screen too (§19). Escape always works.
  if (e.key === 'F11' && ctx.os === 'windows') return 'fullscreen';
  if (e.key === 'Escape') return 'escape';
  if (ctx.typing || !ctx.singleKeys) return undefined;
  return single(e);
}

/** Whether a press on the video may move the window: never in full screen, never by touch. */
export function mayDragWindow(pointerType: string, fullscreen: boolean): boolean {
  return !fullscreen && pointerType !== 'touch';
}

/** The menu key or Shift+F10 (Windows' and Linux's keyboard menu). */
export function isMenuKey(e: {
  key: string;
  shiftKey: boolean;
  ctrlKey: boolean;
  metaKey: boolean;
  altKey: boolean;
}): boolean {
  if (e.ctrlKey || e.metaKey || e.altKey) return false;
  return e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10');
}

/** Whether a keyboard event's target is a place to type. */
export function isTypingTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  if (target.isContentEditable) return true;
  if (target instanceof HTMLTextAreaElement) return true;
  if (target instanceof HTMLSelectElement) return false;
  if (target instanceof HTMLInputElement) {
    return !['button', 'checkbox', 'radio', 'range', 'submit', 'reset', 'color', 'file'].includes(
      target.type,
    );
  }
  return false;
}

/** A group of the "?" sheet: its title and rows of key caps with what they do. */
export interface SheetRow {
  keys: string[];
  /** A message key in `player.keys.*`. */
  label: string;
}

/**
 * The "?" sheet, three columns of eight (the mock-up's order). `mod` is the
 * platform's command key cap: ⌘ on a Mac, Ctrl elsewhere.
 */
export function sheet(mod: string): { title: string; rows: SheetRow[] }[] {
  return [
    {
      title: 'player.keys.groupPlay',
      rows: [
        { keys: ['Space', 'K'], label: 'player.keys.playPause' },
        { keys: ['←', '→'], label: 'player.keys.seek5' },
        { keys: ['J', 'L'], label: 'player.keys.seek10' },
        { keys: ['⇧←', '⇧→'], label: 'player.keys.lines' },
        { keys: ['R'], label: 'player.keys.replay' },
        { keys: ['[', ']'], label: 'player.keys.speed' },
        { keys: ['\\'], label: 'player.keys.normalSpeed' },
        { keys: ['⇧N', '⇧P'], label: 'player.keys.episodes' },
      ],
    },
    {
      title: 'player.keys.groupSubtitles',
      rows: [
        { keys: ['C'], label: 'player.keys.hideAll' },
        { keys: ['1', '2', '3'], label: 'player.keys.hideOne' },
        { keys: ['S'], label: 'player.keys.panel' },
        { keys: ['Z', 'X'], label: 'player.keys.timing' },
        { keys: ['⇧Z', '⇧X'], label: 'player.keys.timingBig' },
        { keys: ['H'], label: 'player.keys.heard' },
        { keys: ['W'], label: 'player.keys.pickWord' },
        { keys: ['T'], label: 'player.keys.transcript' },
      ],
    },
    {
      title: 'player.keys.groupWindow',
      rows: [
        { keys: ['F'], label: 'player.keys.fullscreen' },
        { keys: ['Esc'], label: 'player.keys.escape' },
        { keys: ['I'], label: 'player.keys.mini' },
        { keys: ['↑', '↓'], label: 'player.keys.volume' },
        { keys: ['M'], label: 'player.keys.mute' },
        { keys: ['A'], label: 'player.keys.audio' },
        { keys: [`${mod}O`], label: 'player.keys.open' },
        { keys: ['?'], label: 'player.keys.list' },
      ],
    },
  ];
}

/** The command key's cap: "⌘" on a Mac, "Ctrl" elsewhere. */
export function modCap(os: Os): string {
  return os === 'macos' ? '⌘' : 'Ctrl';
}
