/**
 * The words of a subtitle line, for clicking and dragging across (spec §10),
 * and what a selection becomes: the headword, the sentence it was met in,
 * and the "Seen in" note. Pure, so it is tested plainly.
 *
 * The headword rules are the browser extension's and the desktop card's
 * (lexpad_extension `src/lib/text.ts`, copied into lexpad_desktop): at most
 * four words, sixty characters, at least one letter.
 */
import { SEEN_IN } from '@/lib/seenIn.js';

/** The longest selection that is one entry (the extension's and the card's rule). */
export const MAX_WORDS = 4;
const MAX_CHARS = 60;
/** The most a private note may hold, as the API allows. */
export const MAX_MEMO = 500;

export interface Token {
  text: string;
  /** A word you can click; spaces and punctuation are not. */
  word: boolean;
}

interface Segmenter {
  segment(text: string): Iterable<{ segment: string; isWordLike?: boolean }>;
}

function segmenter(): Segmenter | undefined {
  const S = (Intl as unknown as { Segmenter?: new (l?: string, o?: { granularity: string }) => Segmenter })
    .Segmenter;
  return S === undefined ? undefined : new S(undefined, { granularity: 'word' });
}

const WORDY = /[\p{L}\p{M}\p{N}]/u;

/**
 * Splits a line into words and what lies between them. `Intl.Segmenter`
 * where the webview has it (it knows Thai and Japanese have no spaces);
 * otherwise runs of letters, marks and digits, with an apostrophe or hyphen
 * inside a word kept in it ("don't", "well-known").
 */
export function tokenize(text: string): Token[] {
  const seg = segmenter();
  const out: Token[] = [];
  if (seg !== undefined) {
    for (const s of seg.segment(text)) {
      const word = s.isWordLike === true || WORDY.test(s.segment);
      const prev = out[out.length - 1];
      // Join "don" + "'" + "t" and "well" + "-" + "known" back into one word.
      if (prev !== undefined && /^['’-]$/.test(s.segment)) {
        out.push({ text: s.segment, word: false });
        continue;
      }
      const before = out[out.length - 2];
      if (word && prev !== undefined && !prev.word && /^['’-]$/.test(prev.text) && before?.word === true) {
        before.text += prev.text + s.segment;
        out.pop();
        continue;
      }
      out.push({ text: s.segment, word });
    }
    return out;
  }
  // A zero-width non-joiner or joiner inside a word belongs to it (Persian "می‌خواهم", "خانه‌ها").
  const re = /[\p{L}\p{M}\p{N}]+(?:(?:['’-]|[\u200c\u200d])[\p{L}\p{M}\p{N}]+)*/gu;
  let last = 0;
  for (const m of text.matchAll(re)) {
    const at = m.index;
    if (at > last) out.push({ text: text.slice(last, at), word: false });
    out.push({ text: m[0], word: true });
    last = at + m[0].length;
  }
  if (last < text.length) out.push({ text: text.slice(last), word: false });
  return out;
}

/** Trims a selection and says whether it is a word or a short phrase (the card's rule). */
export function asHeadword(selection: string): string | undefined {
  const text = selection
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^[\s"'“”‘’([{«»]+|[\s"'“”‘’)\]},.;:!?«»،؛؟]+$/gu, '');
  if (text === '' || [...text].length > MAX_CHARS) return undefined;
  if (!/\p{L}/u.test(text)) return undefined;
  if (text.split(' ').length > MAX_WORDS) return undefined;
  return text;
}

/** The text of tokens `from`..`to` (inclusive, in either order). */
export function textBetween(tokens: readonly Token[], from: number, to: number): string {
  const a = Math.max(0, Math.min(from, to));
  const b = Math.min(tokens.length - 1, Math.max(from, to));
  return tokens
    .slice(a, b + 1)
    .map((t) => t.text)
    .join('');
}

/** How many words lie between two tokens (inclusive). */
export function wordsBetween(tokens: readonly Token[], from: number, to: number): number {
  const a = Math.max(0, Math.min(from, to));
  const b = Math.min(tokens.length - 1, Math.max(from, to));
  return tokens.slice(a, b + 1).filter((t) => t.word).length;
}

/** A cue's text on one line: the sentence a word was met in. */
export function lineOf(text: string): string {
  return text.replace(/\s+/g, ' ').trim();
}

/** One line, no control characters, short: what may go in a note. */
export function noteSafe(text: string, max = 120): string {
  // Line breaks become spaces first; every other control character goes.
  const one = text
    .replace(/\s+/g, ' ')
    .replace(/[\p{Cc}\p{Cf}]/gu, '')
    .trim();
  return [...one].slice(0, max).join('');
}

/**
 * "Seen in The Terrace · S1 E3 · 26:58": the video's title (from its file
 * name), the episode when it is one, and the cue's time. The note names the
 * video and never the file's folder or path.
 */
export function seenIn(title: string, episode: string | undefined, time: string): string {
  const parts = [noteSafe(title, 80), episode, time].filter((p): p is string => p !== undefined && p !== '');
  return [...`${SEEN_IN}${parts.join(' · ')}`].slice(0, MAX_MEMO).join('');
}

/** A hint for the model: the line the word was met in, within the API's limit (the card's rule). */
export function contextHint(sentence: string, max = 200): string | null {
  const lead = 'Seen in: ';
  const room = max - lead.length - 4;
  const s = sentence.trim();
  if (s === '' || room <= 20) return null;
  const clipped = [...s].length <= room ? s : `${[...s].slice(0, room - 1).join('')}…`;
  return `${lead}“${clipped}”`;
}
