/**
 * The Player's state that the screen draws from: what is open, the
 * subtitle tracks and their slots, which panel, menu, dialog or prompt is
 * up, the notices in the corner. Things that change every frame (the
 * playhead, the buffered range) never come through here: the seek bar and
 * the subtitle overlay read them from the controller (`controller.ts`) and
 * touch the DOM only when something they show changes (spec §17).
 */
import { create } from 'zustand';
import type {
  Chapter,
  Cue,
  Dropped,
  Episodes,
  FileRef,
  PickedIn,
  Playback,
  Progress,
  RecentEntry,
} from '@/lib/platform/media.js';
import type { Rect } from './model/layout.js';
import type { ParallelLine } from './model/route.js';
import { loadPrefs, parsePrefs, PREFS_KEY, savePrefs, type PlayerPrefs } from './model/prefs.js';
import type { ManyChoice, SlotNumber } from './model/slots.js';
import type { VideoTitle } from './model/title.js';

export type Phase = 'empty' | 'opening' | 'processing' | 'playing' | 'error';

export type ErrorKind = 'codec' | 'damaged' | 'missing' | 'noAccess' | 'protected' | 'converter' | 'engine';

export interface PlayerError {
  kind: ErrorKind;
  file?: string;
  /** The codec named in "an old format ({codec})". */
  codec?: string;
  /** Where a damaged file stops, in seconds. */
  stopsAt?: number;
  /** What "Copy details for support" copies. */
  details: string;
}

export interface TrackSource {
  kind: 'file' | 'embedded';
  /** The subtitle file's id, or the video's for an embedded track. */
  fileId: string;
  stream?: number;
  /** "The.Terrace.S01E03.fa.srt" or the embedded track's codec and number. */
  name: string;
  codec?: string;
}

export interface TrackState {
  /** Unique in this playback: the engine's key. */
  id: string;
  source: TrackSource;
  lang: string | undefined;
  langConfidence: number;
  langSource: 'fileName' | 'text' | 'track' | undefined;
  cues: Cue[];
  picture: boolean;
  /** "text fixed": an old encoding was read, or Persian letters were put right (§7.3). */
  textFixed: boolean;
  /** "old Persian encoding fixed", for the prompt's line. */
  encodingFixed: boolean;
  offsetMs: number;
  format: 'srt' | 'vtt' | 'ass';
}

export interface Notice {
  id: number;
  /** A message key, or plain text the notice owns. */
  text: string;
  /** Words in the notice that are bold ("Added **ephemeral** to English"). */
  strong?: string;
  tail?: string;
  icon: 'check' | 'info' | 'pause' | 'alert' | 'undo';
  action?: { label: string; run: () => void; keys?: string[] };
  /** A keyboard readout: one at a time, 900 ms, replacing each other (§5). */
  hud?: boolean;
  /** Milliseconds on screen: 4 s, 8 s with an action. */
  ms: number;
}

/** The drop prompt (§9.4, §9.5): one subtitle, or several at once. */
export type DropPrompt =
  | {
      kind: 'one';
      trackId: string;
      slot: SlotNumber;
      replaces: string | null;
      /** The track the default replaced, kept so Remove can put it back. */
      startedAt: number;
      keyboard: boolean;
    }
  | { kind: 'many'; choices: ManyChoice[]; before: Occupancy; startedAt: number; keyboard: boolean };

export type Occupancy = [string | null, string | null, string | null];

/** What the add-word card is open on (§10). */
export interface CardRequest {
  headword: string | null;
  /** Picked in the subtitles or the transcript panel: the surface the word is counted under. */
  from?: PickedIn;
  /** The whole line: the sentence the word was met in. */
  sentence: string;
  /** When there are more words than one entry holds: the picker's words. */
  pickFrom?: string[];
  lang: string | undefined;
  /** The engine's confidence in `lang` (1 once the learner said it); asked about when low. */
  langConfidence?: number;
  /** The subtitle track the word came from, so a language the learner gives is kept on it. */
  trackId?: string;
  /** What the other visible tracks show at that moment: a translation of the line. */
  parallel?: ParallelLine[];
  /** The cue's start, the file's seconds: the time in "Seen in". */
  at: number;
  slot: SlotNumber | null;
  /** Where the selection is, in the window, so the card points at it. */
  anchor: Rect;
  /** The video was playing and the card paused it. */
  resume: boolean;
  /** Where focus goes back on close. */
  returnFocus?: HTMLElement | null;
}

export interface SyncState {
  slot: SlotNumber;
  /** "now", frozen when H was pressed: the file's milliseconds. */
  at: number;
  resume: boolean;
}

export interface SavedDot {
  at: number;
  word: string;
  /** For React's list only. */
  id: number;
  /** The word's id in the notebook, when it reached it (not while it waits for sign-in). */
  wordId?: string;
  /** The card's first meaning, for the end summary. */
  meaning?: string;
}

export type Panel = 'subtitles' | 'transcript' | null;
export type Menu = 'subtitles' | 'speed' | 'audio' | 'volume' | 'more' | 'episodes' | null;
export type Dialog = 'settings' | 'shortcuts' | null;

export interface PlayerState {
  phase: Phase;
  error: PlayerError | null;
  playback: Playback | null;
  file: FileRef | null;
  title: VideoTitle | null;
  chapters: Chapter[];
  duration: number;
  paused: boolean;
  speed: number;
  /** Which audio stream (its index), when there are several. */
  audio: number | undefined;
  episodes: Episodes | null;
  tracks: Record<string, TrackState>;
  /** The tracks showing in Subtitle 1, 2 and 3. */
  slots: Occupancy;
  /** Loaded tracks that wait "Off" in the panel. */
  off: string[];
  /** The master switch (C): positions and styles are kept while off. */
  master: boolean;
  /** Each slot's own eye (1, 2, 3). */
  shown: [boolean, boolean, boolean];
  /** The track Z / X act on: the last one touched (§8). */
  focusSlot: SlotNumber;
  panel: Panel;
  panelTab: 'subtitles' | 'transcript';
  menu: Menu;
  dialog: Dialog;
  /** The controls and top bar are up (§4.4). */
  chrome: boolean;
  /**
   * Whether Web Audio can take the video's sound here (boost above 100%,
   * evening out). Not in WKWebView (macOS): WebKit gives a
   * MediaElementAudioSourceNode nothing but silence for a Media Source
   * stream, so routing the video through it muted the film.
   */
  audioGraph: boolean;
  notices: Notice[];
  prompt: DropPrompt | null;
  card: CardRequest | null;
  sync: SyncState | null;
  summary: boolean;
  dots: SavedDot[];
  recent: RecentEntry[];
  /** Words saved in this session the learning window has not shown yet (the Lexpad button's badge). */
  unseen: number;
  /** Saves in this session, for "from the 4th save only the dot" (§24.3). */
  saves: number;
  pending: number;
  dragging: Dropped | null;
  prefs: PlayerPrefs;
  /** The window is narrower than 900 px (§6.9). */
  small: boolean;
  fullscreen: boolean;
  /** The window is the mini player (spec §13): small, on top, Subtitle 1 only. */
  mini: boolean;
  /** The big window kept above other windows (the right-click menu's Float on Top). */
  onTop: boolean;
  /** Tracks that step aside while the word card is open (a window too small to hold it clear of them). */
  stepAside: SlotNumber[];
  online: boolean;
  /** The engine's own: no player in this core, or FFmpeg is missing. */
  engineMissing: boolean;
  /** Where the engine serves media and frames (`lexmedia`), once it answered. */
  engineBase: string | null;
  /** The bundled FFmpeg's version and licence, for the About line (LGPL). */
  engineAbout: { version: string | undefined; licence: string } | null;
  /** How far the current conversion is, while one runs. */
  progress: Progress | null;
  /**
   * Embedded tracks being read out of the file (a big film or a slow drive
   * can take a while), by stream: how far, 0..1, once the core has said.
   */
  reading: Record<number, number | null>;
}

let noticeId = 1;
export function nextNoticeId(): number {
  noticeId += 1;
  return noticeId;
}

export function initialState(): PlayerState {
  return {
    phase: 'empty',
    error: null,
    playback: null,
    file: null,
    title: null,
    chapters: [],
    duration: 0,
    paused: true,
    speed: 1,
    audio: undefined,
    episodes: null,
    tracks: {},
    slots: [null, null, null],
    off: [],
    master: true,
    shown: [true, true, true],
    focusSlot: 1,
    panel: null,
    panelTab: 'subtitles',
    menu: null,
    dialog: null,
    chrome: true,
    audioGraph: true,
    notices: [],
    prompt: null,
    card: null,
    sync: null,
    summary: false,
    dots: [],
    recent: [],
    unseen: 0,
    saves: 0,
    pending: 0,
    dragging: null,
    reading: {},
    prefs: loadPrefs(),
    small: false,
    fullscreen: false,
    mini: false,
    onTop: false,
    stepAside: [],
    online: true,
    engineMissing: false,
    engineBase: null,
    engineAbout: null,
    progress: null,
  };
}

export const usePlayer = create<PlayerState>(() => initialState());

// The learning window's Settings → Video player writes the same prefs (one
// origin, one localStorage): a change there reaches an open Player.
if (typeof window !== 'undefined') {
  window.addEventListener('storage', (e) => {
    if (e.key === PREFS_KEY) usePlayer.setState({ prefs: parsePrefs(e.newValue) });
  });
}

/** Changes the prefs and writes them through. */
export function updatePrefs(change: (p: PlayerPrefs) => PlayerPrefs): void {
  const next = change(usePlayer.getState().prefs);
  usePlayer.setState({ prefs: next });
  savePrefs(next);
}

/** The track showing in a slot, if any. */
export function trackIn(state: PlayerState, slot: SlotNumber): TrackState | undefined {
  const id = state.slots[slot - 1];
  return id === null || id === undefined ? undefined : state.tracks[id];
}

/** The slot a track is in, or null when Off. */
export function slotOf(state: PlayerState, id: string): SlotNumber | null {
  const i = state.slots.indexOf(id);
  return i < 0 ? null : ((i + 1) as SlotNumber);
}

/** Whether a slot's subtitle is on screen now (the master switch and its own eye). */
export function slotVisible(state: PlayerState, slot: SlotNumber): boolean {
  return state.master && state.shown[slot - 1] === true && state.slots[slot - 1] !== null;
}

/** How many tracks show now, for the subtitles button's badge. */
export function shownCount(state: PlayerState): number {
  return ([1, 2, 3] as const).filter((n) => slotVisible(state, n)).length;
}

/** Volume above 100% is offered only where the sound can go through Web Audio. */
export function boostHere(s: Pick<PlayerState, 'audioGraph' | 'prefs'>): boolean {
  return s.audioGraph && s.prefs.settings.boost;
}
