/**
 * The Player's engine room: the `<video>`, the stream from the core, the
 * playhead, volume and speed, audio tracks, subtitle tracks and their slots,
 * resume points, episodes and the corner notices. The screen asks it to do
 * things and draws the store; anything that changes every frame (the
 * playhead) is handed to subscribers by `onTick`, never through React state.
 *
 * Times: "file seconds" everywhere in the page; the element's own time is
 * file seconds + `Playback.timeOffset` (spec: engine `cues.ts`).
 */
import { t, type MessageKey } from '@/i18n/index.js';
import type { MediaEngine, PlayerHost } from '@/lib/platform/types.js';
import type { Cue, Dropped, FileRef, MediaError, Playback, Track } from '@/lib/platform/media.js';
import { activeIndices, lastCueIndexBefore, offsetToStartNow } from './model/cues.js';
import { embeddedTrackName, pickEmbedded } from './model/embedded.js';
import { languageName } from './model/languages.js';
import type { ParallelLine } from './model/route.js';
import { localDay, videoKey } from './model/prefs.js';
import { chooseMany, chooseOne, MAX_SHOWN, type Languages, type SlotNumber } from './model/slots.js';
import { episodeShort, parseTitle } from './model/title.js';
import { clock, offsetLabel } from './model/time.js';
import { StreamPlayer } from './stream.js';
import { PlayerActivity } from './activity.js';
import { flushEvents } from '@/features/activity/events.js';

/** The longest closing the window waits for its last events. */
const CLOSE_FLUSH_MS = 800;
import {
  boostHere,
  initialState,
  nextNoticeId,
  slotOf,
  slotVisible,
  trackIn,
  updatePrefs,
  usePlayer,
  type ErrorKind,
  type Notice,
  type Occupancy,
  type TrackState,
} from './store.js';

/** How often the resume point is written while playing. */
const RESUME_EVERY_MS = 5000;
/** A notice's time on screen: 4 s, 8 s with an action, 900 ms for a key's readout (§5). */
export const NOTICE_MS = 4000;
export const NOTICE_ACTION_MS = 8000;
export const HUD_MS = 900;
/** At most this many notices stack in the corner. */
export const MAX_NOTICES = 3;
/** The audio-only conversion shows its screen only if it takes longer than this (§16). */
const AUDIO_SCREEN_AFTER_MS = 700;
/** Reading a track out of the film says so after this long (a big file, a slow drive); faster, nothing is said. */
const READING_NOTICE_AFTER_MS = 1500;
/** A video that plays this long earns the default-player offer (§24.6). */
export const OFFER_AFTER_S = 180;
/** The end summary comes this long after the last line, if nothing else ended it first (§12). */
export const SUMMARY_AFTER_LAST_CUE_S = 20;
/** Volume steps of the arrow keys and the wheel (§6.3). */
export const VOLUME_STEP = 0.05;
export const MAX_VOLUME = 2;

/**
 * Whether a MediaElementAudioSourceNode hears the video in this webview.
 * WKWebView (macOS) gives one only silence for a Media Source stream (and a
 * `lexmedia` file is another origin), so the film went mute as soon as boost
 * or evening out took the sound; WebView2 (Windows) is Chromium and hears it.
 */
export function webAudioTakesVideo(os: 'macos' | 'windows' | 'linux'): boolean {
  return os !== 'macos';
}
/** The speeds the menu offers and [ / ] step through (§6.4). */
export const SPEEDS = [0.5, 0.75, 0.9, 1, 1.1, 1.25, 1.5, 2] as const;

type Tick = (fileSeconds: number) => void;

function mediaError(cause: unknown): MediaError | 'other' {
  const word = typeof cause === 'string' ? cause : cause instanceof Error ? cause.message : '';
  const known: MediaError[] = [
    'unknown_file',
    'ffmpeg_missing',
    'unreadable',
    'no_video',
    'no_encoder',
    'unsupported_subtitle',
    'unreadable_subtitle',
    'empty_subtitle',
    'too_big',
    'file_gone',
    'no_session',
    'timeout',
    'cancelled',
  ];
  return known.includes(word as MediaError) ? (word as MediaError) : 'other';
}

export class PlayerController {
  private video: HTMLVideoElement | null = null;
  private stream: StreamPlayer | null = null;
  private ticks = new Set<Tick>();
  private frameHandle = 0;
  private resumeTimer = 0;
  private noticeTimers = new Map<number, number>();
  private playedSeconds = 0;
  private lastTickAt = 0;
  private audioCtx: AudioContext | null = null;
  private gain: GainNode | null = null;
  private compressor: DynamicsCompressorNode | null = null;
  private stopFiles: (() => void) | null = null;
  private generation = 0;
  private boostStopped = false;
  private stopFirstGesture: (() => void) | null = null;
  private languages: Languages = { learning: undefined, own: undefined };
  /** What the operators are told about watching (features/player/activity.ts). */
  readonly activity = new PlayerActivity();

  constructor(readonly host: PlayerHost) {
    const audioGraph = webAudioTakesVideo(host.window.os);
    usePlayer.setState({ audioGraph });
    // A volume above 100% kept from before cannot be played here: say 100%.
    if (!audioGraph && usePlayer.getState().prefs.volume > 1) updatePrefs((p) => ({ ...p, volume: 1 }));
  }

  get media(): MediaEngine {
    return this.host.media;
  }

  /* ------------------------------------------------------------ wiring */

  attach(video: HTMLVideoElement): () => void {
    this.video = video;
    this.stream = new StreamPlayer(video, this.media, {
      onFirstFrame: () => {
        const s = usePlayer.getState();
        if (s.phase === 'opening' || s.phase === 'processing') usePlayer.setState({ phase: 'playing' });
      },
      onError: (message) => {
        this.fail('converter', message);
      },
    });
    const onPlay = (): void => {
      usePlayer.setState({ paused: false });
      this.loop();
    };
    const onPause = (): void => {
      usePlayer.setState({ paused: true });
      this.saveResume();
      this.emitTick();
    };
    const onSeeked = (): void => {
      this.activity.jumped();
      this.emitTick();
    };
    // Minutes watched come from the playhead's own progress (§10), about
    // four times a second, never from the wall clock.
    const onTime = (): void => {
      this.activity.tick(video);
    };
    const onHidden = (): void => {
      if (document.visibilityState === 'hidden') void this.sendActivity(false);
    };
    document.addEventListener('visibilitychange', onHidden);
    const stopClose = this.bindClose();
    const onEnded = (): void => {
      this.saveResume(true);
      this.showSummary();
    };
    const onRate = (): void => {
      usePlayer.setState({ speed: video.playbackRate });
    };
    const onError = (): void => {
      const s = usePlayer.getState();
      if (s.file === null) return;
      this.fail('converter', video.error?.message ?? 'media error');
    };
    video.addEventListener('play', onPlay);
    video.addEventListener('pause', onPause);
    video.addEventListener('seeked', onSeeked);
    video.addEventListener('ended', onEnded);
    video.addEventListener('ratechange', onRate);
    video.addEventListener('error', onError);
    video.addEventListener('timeupdate', onTime);
    // No graph yet: an AudioContext made without the learner's gesture starts
    // suspended, and the video routed into it would be silent. The first
    // press or click builds it when boost or evening out is wanted.
    this.applyVolume({ gesture: false });
    const firstGesture = (): void => {
      this.applyVolume();
    };
    window.addEventListener('pointerdown', firstGesture, { once: true, capture: true });
    window.addEventListener('keydown', firstGesture, { once: true, capture: true });
    this.stopFirstGesture = () => {
      window.removeEventListener('pointerdown', firstGesture, { capture: true });
      window.removeEventListener('keydown', firstGesture, { capture: true });
    };
    this.stopFiles = this.media.onFiles((d) => {
      void this.dropped(d, false);
    });
    void this.media
      .takePending()
      .then((d) => {
        if (d !== null) void this.dropped(d, false);
      })
      .catch(() => undefined);
    void this.refreshRecent();
    void this.media
      .engine()
      .then((e) => {
        usePlayer.setState({
          engineBase: e.baseUrl,
          engineMissing: !e.available,
          engineAbout: { version: e.version, licence: e.licence },
        });
      })
      .catch(() => {
        usePlayer.setState({ engineMissing: true });
      });
    const stopProgress = this.media.onProgress((p) => {
      if (p.session === usePlayer.getState().playback?.session) usePlayer.setState({ progress: p });
    });
    const stopReading = this.media.onSubtitleProgress((p) => {
      const s = usePlayer.getState();
      if (s.file?.id !== p.fileId || !(p.stream in s.reading)) return;
      usePlayer.setState({ reading: { ...s.reading, [p.stream]: p.fraction } });
    });
    // A Continue watching card on the learning window's Watch page.
    void this.host
      .takePlay()
      .then((id) => {
        if (id !== null) void this.playById(id);
      })
      .catch(() => undefined);
    const stopPlay = this.host.onPlay((id) => {
      void this.playById(id);
    });
    return () => {
      stopProgress();
      stopReading();
      stopPlay();
      video.removeEventListener('play', onPlay);
      video.removeEventListener('pause', onPause);
      video.removeEventListener('seeked', onSeeked);
      video.removeEventListener('ended', onEnded);
      video.removeEventListener('ratechange', onRate);
      video.removeEventListener('error', onError);
      video.removeEventListener('timeupdate', onTime);
      document.removeEventListener('visibilitychange', onHidden);
      stopClose();
      this.stopFiles?.();
      this.stopFiles = null;
      this.stopFirstGesture?.();
      this.stopFirstGesture = null;
      this.close();
      this.video = null;
    };
  }

  setLanguages(langs: Languages): void {
    this.languages = langs;
  }

  getLanguages(): Languages {
    return this.languages;
  }

  /** The file's seconds at the playhead. */
  time(): number {
    const v = this.video;
    const p = usePlayer.getState().playback;
    if (v === null || p === null) return 0;
    return Math.max(0, v.currentTime - p.timeOffset);
  }

  /** The element's buffered ranges, in file seconds (the seek bar's converted part). */
  buffered(): [number, number][] {
    const v = this.video;
    const p = usePlayer.getState().playback;
    if (v === null || p === null) return [];
    const out: [number, number][] = [];
    for (let i = 0; i < v.buffered.length; i++) {
      out.push([v.buffered.start(i) - p.timeOffset, v.buffered.end(i) - p.timeOffset]);
    }
    return out;
  }

  element(): HTMLVideoElement | null {
    return this.video;
  }

  onTick(fn: Tick): () => void {
    this.ticks.add(fn);
    fn(this.time());
    return () => this.ticks.delete(fn);
  }

  private emitTick(): void {
    const now = this.time();
    for (const fn of this.ticks) fn(now);
  }

  /** One callback per presented frame while playing (requestVideoFrameCallback where it exists). */
  private loop(): void {
    const v = this.video;
    if (v === null) return;
    cancelAnimationFrame(this.frameHandle);
    // WKWebView before Safari 15.4 has no requestVideoFrameCallback.
    const rvfc: ((cb: () => void) => number) | undefined =
      'requestVideoFrameCallback' in v ? (cb) => v.requestVideoFrameCallback(cb) : undefined;
    const step = (): void => {
      if (this.video === null || this.video.paused) return;
      this.countPlayed();
      this.emitTick();
      this.checkSummary();
      if (rvfc !== undefined) rvfc(step);
      else this.frameHandle = requestAnimationFrame(step);
    };
    this.lastTickAt = performance.now();
    if (rvfc !== undefined) rvfc(step);
    else this.frameHandle = requestAnimationFrame(step);
    window.clearInterval(this.resumeTimer);
    this.resumeTimer = window.setInterval(() => {
      if (this.video !== null && !this.video.paused) this.saveResume();
    }, RESUME_EVERY_MS);
  }

  private countPlayed(): void {
    const now = performance.now();
    const dt = (now - this.lastTickAt) / 1000;
    this.lastTickAt = now;
    if (dt > 0 && dt < 1) this.playedSeconds += dt;
    if (this.playedSeconds >= OFFER_AFTER_S) {
      const prefs = usePlayer.getState().prefs;
      if (!prefs.offer.earned) updatePrefs((p) => ({ ...p, offer: { ...p.offer, earned: true } }));
    }
  }

  /* ------------------------------------------------------------ files */

  /** Videos and subtitles dropped or opened: the first video plays, subtitles join it (§9). */
  async dropped(d: Dropped, keyboard: boolean): Promise<void> {
    usePlayer.setState({ dragging: null });
    if (d.unsupported.length > 0 && d.videos.length === 0 && d.subtitles.length === 0) {
      this.notice({ text: t('player.drop.cantUse'), icon: 'alert' });
      return;
    }
    const video = d.videos[0];
    if (video !== undefined) {
      await this.openVideo(video, { withSubtitles: d.subtitles });
      return;
    }
    if (d.subtitles.length > 0) await this.addSubtitleFiles(d.subtitles, keyboard);
  }

  /** Plays a file the engine already knows, by id, named from Continue watching. */
  async playById(id: string): Promise<void> {
    let name = '';
    try {
      name = (await this.media.recent()).find((r) => r.fileId === id)?.name ?? '';
    } catch {
      // Named from the file once it opens.
    }
    await this.openVideo({ id, name, kind: 'video', size: 0 });
  }

  async pick(): Promise<void> {
    try {
      const d = await this.media.pick();
      await this.dropped(d, true);
    } catch (cause) {
      if (mediaError(cause) !== 'cancelled')
        this.notice({ text: t('player.error.pickFailed'), icon: 'alert' });
    }
  }

  async openVideo(file: FileRef, opts: { withSubtitles?: FileRef[]; at?: number } = {}): Promise<void> {
    const before = usePlayer.getState();
    if (before.episodes?.next?.id === file.id) this.activity.nextEpisode();
    const previous = before.file;
    const previousAt = this.time();
    this.close();
    const gen = ++this.generation;
    const title = parseTitle(file.name);
    usePlayer.setState({
      ...resetForVideo(before),
      phase: 'opening',
      file,
      title,
      progress: null,
      reading: {},
    });
    this.playedSeconds = 0;
    let playback: Playback;
    try {
      playback = await this.media.open(file.id, opts.at === undefined ? {} : { at: opts.at });
    } catch (cause) {
      if (gen !== this.generation) return;
      this.failFromEngine(cause, file);
      return;
    }
    if (gen !== this.generation) {
      void this.media.close(playback.session).catch(() => undefined);
      return;
    }
    const resumeAt = usePlayer.getState().prefs.settings.resume ? playback.resumeAt : 0;
    const p: Playback = { ...playback, resumeAt };
    const duration = p.duration ?? p.info.duration ?? 0;
    const prefs = usePlayer.getState().prefs;
    const key = videoKey(file.name, file.size);
    const hidden = prefs.hidden[key];
    usePlayer.setState({
      playback: p,
      duration,
      chapters: p.info.chapters,
      audio: p.plan.audio?.index,
      ...(hidden !== undefined ? { master: hidden.master, shown: hidden.slots } : {}),
    });
    if (p.mode === 'videoTranscode') usePlayer.setState({ phase: 'processing' });
    else if (p.mode === 'audioTranscode') {
      window.setTimeout(() => {
        if (gen === this.generation && usePlayer.getState().phase === 'opening')
          usePlayer.setState({ phase: 'processing' });
      }, AUDIO_SCREEN_AFTER_MS);
    }
    await this.stream?.load(p);
    const v = this.video;
    if (v !== null) {
      const remembered = prefs.settings.rememberSpeed ? prefs.speeds[key] : undefined;
      v.playbackRate = remembered ?? 1;
      (v as HTMLVideoElement & { preservesPitch?: boolean }).preservesPitch = prefs.settings.keepVoice;
      void v.play().catch(() => {
        usePlayer.setState({ paused: true });
      });
    }
    if (previous !== null && previous.id !== file.id && previousAt > 0) {
      const name = parseTitle(previous.name).title;
      this.notice({
        text: t('player.notice.savedAt', { title: name, time: clock(previousAt) }),
        icon: 'check',
      });
    }
    this.activity.opened(p, p.info.subtitles.length + (opts.withSubtitles?.length ?? 0));
    void this.loadEpisodes(file, gen);
    await this.loadMatchedSubtitles(file, opts.withSubtitles ?? [], gen);
  }

  private async loadEpisodes(file: FileRef, gen: number): Promise<void> {
    try {
      const episodes = await this.media.episodes(file.id);
      if (gen !== this.generation) return;
      const ep = episodes.items[episodes.current];
      const t0 = usePlayer.getState().title;
      // The folder's numbering wins over a name that has none.
      if (ep?.episode !== undefined && t0 !== null && t0.episode === undefined) {
        usePlayer.setState({
          title: { ...t0, episode: ep.episode, ...(ep.season !== undefined ? { season: ep.season } : {}) },
        });
      }
      usePlayer.setState({ episodes: episodes.items.length > 1 ? episodes : null });
    } catch {
      // A single file: no episode controls.
    }
  }

  /**
   * Subtitles named after the video (dropped with it, or lying beside it)
   * are placed without a prompt; with none, the file's own text tracks are
   * ("soft subs": the learning language and your own, else the file's
   * default or first, `pickEmbedded`). One notice says where each went,
   * with Change (§9.3).
   */
  private async loadMatchedSubtitles(file: FileRef, dropped: FileRef[], gen: number): Promise<void> {
    let beside: FileRef[] = [];
    let embedded: number[] = [];
    try {
      const subs = await this.media.subtitles(file.id);
      beside = subs.external.filter((x) => x.fit > 0).map((x) => x.file);
      embedded = pickEmbedded(subs.embedded, this.languages);
    } catch {
      // No list: only what was dropped.
    }
    if (gen !== this.generation) return;
    const files = [...dropped, ...beside.filter((b) => !dropped.some((d) => d.id === b.id))];
    const loaded: TrackState[] = [];
    for (const f of files) {
      const tr = await this.loadTrack(f.id, undefined, f.name);
      if (gen !== this.generation) return;
      if (tr !== null) loaded.push(tr);
    }
    if (loaded.length === 0) {
      // Every track in the queue reads as "Reading…" in the menu from the start, so
      // its Use cannot start a second read of it (it would be placed twice).
      usePlayer.setState((st) => ({
        reading: { ...st.reading, ...Object.fromEntries(embedded.map((x) => [x, null])) },
      }));
      for (const stream of embedded) {
        const tr = await this.loadTrack(file.id, stream, undefined);
        if (gen !== this.generation) return;
        if (tr !== null) loaded.push(tr);
      }
    }
    if (loaded.length === 0) return;
    this.placeMany(loaded, { prompt: false });
  }

  /** Reads one track through the engine; a failure is a notice, never a silent nothing. */
  async loadTrack(
    fileId: string,
    stream: number | undefined,
    name: string | undefined,
  ): Promise<TrackState | null> {
    const s = usePlayer.getState();
    const embedded = stream !== undefined;
    const meta = embedded ? s.playback?.info.subtitles.find((x) => x.index === stream) : undefined;
    const label =
      name ??
      (meta ? embeddedTrackName(meta, s.playback?.info.subtitles ?? [], t('player.subs.trackWord')) : '');
    let track: Track;
    let slow: number | undefined;
    if (stream !== undefined) {
      usePlayer.setState((st) => ({ reading: { ...st.reading, [stream]: null } }));
      // A big film or a slow drive: say what is happening once it takes a moment.
      slow = window.setTimeout(() => {
        if (usePlayer.getState().file?.id === fileId && stream in usePlayer.getState().reading)
          this.notice({ text: t('player.subs.reading', { name: label }), icon: 'info' });
      }, READING_NOTICE_AFTER_MS);
    }
    try {
      track = await this.media.loadSubtitle(fileId, stream);
    } catch (cause) {
      const word = mediaError(cause);
      const key: MessageKey =
        word === 'unsupported_subtitle'
          ? embedded
            ? 'player.subs.trackPicture'
            : 'player.subs.notText'
          : word === 'empty_subtitle'
            ? 'player.subs.empty'
            : word === 'timeout'
              ? 'player.subs.tooSlow'
              : embedded
                ? 'player.subs.trackUnreadable'
                : 'player.subs.unreadable';
      this.notice({ text: t('player.subs.couldntRead', { name: label }), tail: t(key), icon: 'alert' });
      return null;
    } finally {
      window.clearTimeout(slow);
      if (stream !== undefined)
        usePlayer.setState((st) => ({
          reading: Object.fromEntries(Object.entries(st.reading).filter(([k]) => Number(k) !== stream)),
        }));
    }
    const id = embedded ? `e${String(stream)}:${track.key}` : `f:${track.key}`;
    const best = track.language.best;
    const state: TrackState = {
      id,
      source: {
        kind: embedded ? 'embedded' : 'file',
        fileId,
        ...(embedded ? { stream } : {}),
        name: name ?? meta?.title ?? '',
        ...(meta ? { codec: meta.codec } : {}),
      },
      lang: best?.code ?? meta?.language ?? undefined,
      langConfidence: best?.confidence ?? (meta?.language ? 1 : 0),
      langSource: best?.source ?? (meta?.language ? 'track' : undefined),
      cues: track.cues,
      picture: track.picture === true || track.cues.some((c) => c.image !== undefined),
      textFixed:
        track.encoding.replaced ||
        track.persianLettersFixed ||
        track.punctuationMoved === true ||
        track.encoding.how === 'detected',
      encodingFixed: track.encoding.replaced || track.encoding.how === 'detected',
      offsetMs: s.playback?.saved.subtitleOffsets?.[track.key] ?? 0,
      format: track.format,
    };
    usePlayer.setState((st) => ({ tracks: { ...st.tracks, [id]: state } }));
    if (state.encodingFixed) this.activity.encodingFixed(track.key);
    return state;
  }

  /** Subtitle files dropped while a video plays (§9.4, §9.5). */
  async addSubtitleFiles(files: FileRef[], keyboard: boolean): Promise<void> {
    const s0 = usePlayer.getState();
    if (s0.file === null) {
      this.notice({ text: t('player.drop.videoFirst'), icon: 'info' });
      return;
    }
    const loaded: TrackState[] = [];
    for (const f of files) {
      const tr = await this.loadTrack(f.id, undefined, f.name);
      if (tr !== null) loaded.push(tr);
    }
    if (loaded.length === 0) return;
    const ask = usePlayer.getState().prefs.settings.askEachFile;
    if (loaded.length === 1) {
      const tr = loaded[0];
      if (tr === undefined) return;
      const state = usePlayer.getState();
      const choice = chooseOne(tr.lang, this.languages, state.slots);
      this.put(tr.id, choice.slot);
      if (ask) {
        usePlayer.setState({
          prompt: {
            kind: 'one',
            trackId: tr.id,
            slot: choice.slot,
            replaces: choice.replaces,
            startedAt: Date.now(),
            keyboard,
          },
        });
      }
      this.markHint('drop');
      return;
    }
    this.placeMany(loaded, { prompt: ask, keyboard });
    this.markHint('drop');
  }

  private placeMany(loaded: TrackState[], opts: { prompt: boolean; keyboard?: boolean }): void {
    const state = usePlayer.getState();
    const before: Occupancy = [...state.slots];
    const choices = chooseMany(
      loaded.map((tr) => ({ id: tr.id, lang: tr.lang, source: tr.langSource })),
      this.languages,
      state.slots,
    );
    for (const c of choices) {
      if (c.slot === null) this.toOff(c.id);
      else this.put(c.id, c.slot);
    }
    if (opts.prompt) {
      usePlayer.setState({
        prompt: { kind: 'many', choices, before, startedAt: Date.now(), keyboard: opts.keyboard === true },
      });
      return;
    }
    const placed = choices.filter((c) => c.slot !== null);
    const where = placed
      .map((c) => {
        const tr = usePlayer.getState().tracks[c.id];
        const place =
          c.slot === 1
            ? t('player.place.bottom')
            : c.slot === 2
              ? t('player.place.top')
              : t('player.place.above1');
        return `${languageName(tr?.lang)} ${place.toLowerCase()}`;
      })
      .join(', ');
    this.notice({
      text: t('player.notice.subtitlesAdded', { count: placed.length }),
      tail: where,
      icon: 'check',
      action: {
        label: t('player.action.change'),
        run: () => {
          this.openPanel('subtitles');
        },
      },
    });
  }

  /** Puts a track in a slot, moving whatever was there to Off. */
  put(id: string, slot: SlotNumber): void {
    usePlayer.setState((s) => {
      const slots: Occupancy = [...s.slots];
      const was = slots.indexOf(id);
      if (was >= 0) slots[was] = null;
      const displaced = slots[slot - 1];
      slots[slot - 1] = id;
      const off = s.off.filter((x) => x !== id);
      if (displaced !== null && displaced !== undefined && displaced !== id) off.unshift(displaced);
      const shown: [boolean, boolean, boolean] = [...s.shown];
      shown[slot - 1] = true;
      // The slot timing keys and H act on stays the learner's, unless it was empty.
      const focusSlot = (slots[s.focusSlot - 1] ?? null) === null ? slot : s.focusSlot;
      return { slots, off, shown, focusSlot };
    });
  }

  toOff(id: string): void {
    usePlayer.setState((s) => {
      const slots: Occupancy = [...s.slots];
      const was = slots.indexOf(id);
      if (was >= 0) slots[was] = null;
      return { slots, off: s.off.includes(id) ? s.off : [id, ...s.off] };
    });
  }

  removeTrack(id: string): void {
    usePlayer.setState((s) => {
      const slots: Occupancy = [...s.slots];
      const was = slots.indexOf(id);
      if (was >= 0) slots[was] = null;
      const tracks = Object.fromEntries(Object.entries(s.tracks).filter(([k]) => k !== id));
      return { slots, tracks, off: s.off.filter((x) => x !== id) };
    });
  }

  /** Puts the slots back as they were before a prompt (Undo, Remove). */
  restoreSlots(before: Occupancy, drop: string[]): void {
    usePlayer.setState((s) => {
      const tracks = Object.fromEntries(Object.entries(s.tracks).filter(([k]) => !drop.includes(k)));
      const kept = before.map((id) => (id !== null && tracks[id] !== undefined ? id : null)) as Occupancy;
      return { slots: kept, tracks, off: s.off.filter((x) => !drop.includes(x) && !kept.includes(x)) };
    });
  }

  /** Swaps the order of the showing tracks: renumbers slots and keys (§8). */
  reorder(from: SlotNumber, to: SlotNumber): void {
    usePlayer.setState((s) => {
      const slots: Occupancy = [...s.slots];
      const a = slots[from - 1] ?? null;
      slots[from - 1] = slots[to - 1] ?? null;
      slots[to - 1] = a;
      return { slots };
    });
  }

  async useEmbedded(stream: number): Promise<void> {
    const s = usePlayer.getState();
    if (s.file === null) return;
    const tr = await this.loadTrack(s.file.id, stream, undefined);
    if (tr === null) return;
    const free = ([1, 2, 3] as const).find((n) => usePlayer.getState().slots[n - 1] === null);
    if (free === undefined) this.toOff(tr.id);
    else this.put(tr.id, free);
  }

  /* ------------------------------------------------------------ playback */

  togglePlay(): void {
    const v = this.video;
    if (v === null || usePlayer.getState().file === null) return;
    if (v.paused) void v.play().catch(() => undefined);
    else v.pause();
  }

  play(): void {
    void this.video?.play().catch(() => undefined);
  }

  pause(): void {
    this.video?.pause();
  }

  isPlaying(): boolean {
    return this.video !== null && !this.video.paused;
  }

  /** Seeks to the file's seconds. */
  seek(fileSeconds: number): void {
    const v = this.video;
    const p = usePlayer.getState().playback;
    if (v === null || p === null) return;
    const duration = usePlayer.getState().duration;
    const to = Math.max(0, duration > 0 ? Math.min(fileSeconds, duration - 0.05) : fileSeconds);
    v.currentTime = to + p.timeOffset;
    if (usePlayer.getState().summary && to < duration - 1) usePlayer.setState({ summary: false });
    this.emitTick();
  }

  skip(seconds: number): void {
    this.seek(this.time() + seconds);
  }

  /** Subtitle 1's lines: replay this one, or go to the one before or after (R, ⇧← ⇧→). */
  stepLine(direction: -1 | 0 | 1): void {
    const s = usePlayer.getState();
    const tr = trackIn(s, 1) ?? trackIn(s, 2) ?? trackIn(s, 3);
    if (tr === undefined) {
      this.skip(direction === 0 ? -5 : direction * 5);
      return;
    }
    const nowMs = this.time() * 1000;
    const i = lastCueIndexBefore(tr.cues, nowMs, tr.offsetMs);
    const target = i + direction;
    const cue = tr.cues[Math.max(0, Math.min(tr.cues.length - 1, target))];
    if (cue === undefined) return;
    this.seek((cue.start + tr.offsetMs) / 1000);
    this.play();
  }

  setSpeed(speed: number): void {
    const v = this.video;
    if (v === null) return;
    v.playbackRate = speed;
    usePlayer.setState({ speed });
    const s = usePlayer.getState();
    if (s.prefs.settings.rememberSpeed && s.file !== null) {
      const key = videoKey(s.file.name, s.file.size);
      updatePrefs((p) => ({ ...p, speeds: { ...p.speeds, [key]: speed } }));
    }
    this.hud(t('player.hud.speed', { speed: speedLabel(speed) }));
  }

  stepSpeed(direction: -1 | 1): void {
    const now = usePlayer.getState().speed;
    const i = SPEEDS.findIndex((x) => Math.abs(x - now) < 0.001);
    const at = i < 0 ? SPEEDS.indexOf(1) : i;
    const next = SPEEDS[Math.max(0, Math.min(SPEEDS.length - 1, at + direction))] ?? 1;
    this.setSpeed(next);
  }

  setKeepVoice(on: boolean): void {
    const v = this.video;
    if (v !== null) v.preservesPitch = on;
    updatePrefs((p) => ({ ...p, settings: { ...p.settings, keepVoice: on } }));
  }

  /* ------------------------------------------------------------ volume */

  /**
   * 0–100% is the element's own volume; above it (boost, §6.3) the sound goes
   * through Web Audio: a gain and a limiter so it never clips. The graph is
   * made the first time boost or evening-out is wanted, on a click or a key,
   * so the audio context starts with the learner's own gesture.
   */
  private applyVolume(opts: { gesture?: boolean } = {}): void {
    const v = this.video;
    if (v === null) return;
    const s = usePlayer.getState();
    const { volume, muted, settings } = s.prefs;
    v.muted = muted;
    const wantsGraph = s.audioGraph && ((settings.boost && volume > 1) || settings.evenOut);
    if (wantsGraph && opts.gesture !== false) this.ensureGraph();
    if (this.gain !== null && this.audioCtx !== null) {
      v.volume = 1;
      this.gain.gain.setTargetAtTime(Math.min(volume, MAX_VOLUME), this.audioCtx.currentTime, 0.01);
      if (this.compressor !== null) {
        // Evening out: a gentle compressor; boost alone: a limiter.
        this.compressor.threshold.value = settings.evenOut ? -24 : -1;
        this.compressor.ratio.value = settings.evenOut ? 4 : 20;
      }
    } else {
      v.volume = Math.min(1, Math.max(0, volume));
    }
  }

  private ensureGraph(): void {
    if (this.audioCtx !== null || this.video === null || this.boostStopped) return;
    if (!usePlayer.getState().audioGraph) return;
    try {
      const ctx = new AudioContext();
      const source = ctx.createMediaElementSource(this.video);
      const gain = ctx.createGain();
      const comp = ctx.createDynamicsCompressor();
      comp.knee.value = 0;
      comp.attack.value = 0.003;
      comp.release.value = 0.25;
      source.connect(gain).connect(comp).connect(ctx.destination);
      void ctx.resume();
      this.audioCtx = ctx;
      this.gain = gain;
      this.compressor = comp;
    } catch {
      // No Web Audio here: the volume stops at 100%.
      this.boostStopped = true;
    }
  }

  setVolume(volume: number, opts: { hud?: boolean } = {}): void {
    const max = boostHere(usePlayer.getState()) ? MAX_VOLUME : 1;
    const v = Math.round(Math.max(0, Math.min(max, volume)) * 100) / 100;
    updatePrefs((p) => ({ ...p, volume: v, muted: v === 0 ? p.muted : false }));
    this.applyVolume();
    if (opts.hud === true) {
      const pct = Math.round(v * 100);
      this.hud(pct > 100 ? t('player.hud.volumeBoost', { pct }) : t('player.hud.volume', { pct }));
    }
  }

  toggleMute(): void {
    updatePrefs((p) => ({ ...p, muted: !p.muted }));
    this.applyVolume();
    this.hud(
      usePlayer.getState().prefs.muted
        ? t('player.hud.muted')
        : t('player.hud.volume', { pct: Math.round(usePlayer.getState().prefs.volume * 100) }),
    );
  }

  setEvenOut(on: boolean): void {
    updatePrefs((p) => ({ ...p, settings: { ...p.settings, evenOut: on } }));
    this.applyVolume();
  }

  /* ------------------------------------------------------------ audio tracks */

  async setAudioTrack(index: number): Promise<void> {
    const s = usePlayer.getState();
    const p = s.playback;
    const v = this.video;
    if (p === null || v === null || s.audio === index) return;
    const wasPlaying = !v.paused;
    const at = v.currentTime;
    try {
      const next = await this.media.setAudio(p.session, index, p.plan.audio?.delayMs ?? 0, at);
      usePlayer.setState({ playback: next, audio: index });
      await this.stream?.load({ ...next, resumeAt: at - next.timeOffset });
      if (wasPlaying) this.play();
      const a = next.info.audio.find((x) => x.index === index);
      this.hud(t('player.hud.audio', { name: languageName(a?.language ?? a?.languageTag ?? undefined) }));
    } catch {
      this.notice({ text: t('player.audio.failed'), icon: 'alert' });
    }
  }

  nextAudio(): void {
    const s = usePlayer.getState();
    const list = s.playback?.info.audio ?? [];
    if (list.length < 2) return;
    const i = list.findIndex((a) => a.index === s.audio);
    const next = list[(i + 1) % list.length];
    if (next !== undefined) void this.setAudioTrack(next.index);
  }

  /* ------------------------------------------------------------ subtitles */

  toggleMaster(): void {
    const master = !usePlayer.getState().master;
    usePlayer.setState({ master });
    this.rememberHidden();
    this.hud(master ? t('player.hud.subtitlesShown') : t('player.hud.subtitlesHidden'));
    this.markHint('move');
  }

  setMaster(on: boolean): void {
    usePlayer.setState({ master: on });
    this.rememberHidden();
  }

  toggleSlot(slot: SlotNumber): void {
    const s = usePlayer.getState();
    if (s.slots[slot - 1] === null) return;
    const shown: [boolean, boolean, boolean] = [...s.shown];
    shown[slot - 1] = !shown[slot - 1];
    usePlayer.setState({ shown, focusSlot: slot, master: shown[slot - 1] ? true : s.master });
    this.rememberHidden();
    const tr = trackIn(usePlayer.getState(), slot);
    this.hud(
      shown[slot - 1]
        ? t('player.hud.trackShown', { n: slot, name: languageName(tr?.lang) })
        : t('player.hud.trackHidden', { n: slot, name: languageName(tr?.lang) }),
    );
  }

  private rememberHidden(): void {
    const s = usePlayer.getState();
    if (s.file === null) return;
    const key = videoKey(s.file.name, s.file.size);
    updatePrefs((p) => ({ ...p, hidden: { ...p.hidden, [key]: { master: s.master, slots: [...s.shown] } } }));
  }

  setOffset(slot: SlotNumber, ms: number, opts: { hud?: boolean } = {}): void {
    const s = usePlayer.getState();
    const id = s.slots[slot - 1];
    if (id === null || id === undefined) return;
    const tr = s.tracks[id];
    if (tr === undefined) return;
    const offsetMs = Math.round(ms);
    if (offsetMs !== tr.offsetMs) this.activity.offsetMoved();
    usePlayer.setState({ tracks: { ...s.tracks, [id]: { ...tr, offsetMs } }, focusSlot: slot });
    if (s.file !== null) {
      const key = tr.id.replace(/^(f|e\d+):/, '');
      void this.media.saveSubtitleOffset(s.file.id, key, offsetMs).catch(() => undefined);
    }
    this.emitTick();
    if (opts.hud === true) this.hud(t('player.hud.offset', { n: slot, offset: offsetLabel(offsetMs) }));
  }

  nudgeOffset(deltaMs: number): void {
    const s = usePlayer.getState();
    const slot = s.focusSlot;
    const tr = trackIn(s, slot) ?? trackIn(s, 1);
    const at = tr === undefined ? null : slotOf(s, tr.id);
    if (tr === undefined || at === null) return;
    this.setOffset(at, tr.offsetMs + deltaMs, { hud: true });
  }

  /** "I just heard this line" (§8.1): freezes now, pauses, and opens the picker. */
  openSync(slot?: SlotNumber): void {
    const s = usePlayer.getState();
    const target = slot ?? s.focusSlot;
    const tr = trackIn(s, target) ?? trackIn(s, 1);
    if (tr === undefined) return;
    const at = slotOf(s, tr.id) ?? 1;
    const resume = this.isPlaying();
    this.pause();
    usePlayer.setState({ sync: { slot: at, at: this.time() * 1000, resume }, menu: null });
  }

  /** The picked line starts at the frozen moment: the track moves by the difference, with Undo. */
  applySync(cue: Cue): void {
    const s = usePlayer.getState();
    const sync = s.sync;
    if (sync === null) return;
    const tr = trackIn(s, sync.slot);
    if (tr === undefined) return;
    const before = tr.offsetMs;
    const offset = offsetToStartNow(cue, sync.at);
    this.setOffset(sync.slot, offset);
    usePlayer.setState({ sync: null });
    if (sync.resume) this.play();
    const slot = sync.slot;
    this.notice({
      text: t('player.sync.moved', { n: slot, offset: offsetLabel(offset - before) }),
      icon: 'check',
      action: {
        label: t('action.undo'),
        run: () => {
          this.setOffset(slot, before);
        },
        keys: ['mod', 'Z'],
      },
    });
    this.lastUndo = () => {
      this.setOffset(slot, before);
    };
  }

  cancelSync(): void {
    const sync = usePlayer.getState().sync;
    usePlayer.setState({ sync: null });
    if (sync?.resume === true) this.play();
  }

  /** ⌘Z / Ctrl+Z: the last thing a notice offered to undo. */
  lastUndo: (() => void) | null = null;

  undo(): void {
    const u = this.lastUndo;
    this.lastUndo = null;
    u?.();
  }

  /* ------------------------------------------------------------ panels */

  openPanel(tab: 'subtitles' | 'transcript'): void {
    const s = usePlayer.getState();
    if (s.panel === tab) {
      usePlayer.setState({ panel: null });
      return;
    }
    usePlayer.setState({ panel: tab, panelTab: tab, menu: null });
  }

  /* ------------------------------------------------------------ notices */

  notice(n: Omit<Notice, 'id' | 'ms'> & { ms?: number }): number {
    const id = nextNoticeId();
    const ms = n.ms ?? (n.action ? NOTICE_ACTION_MS : NOTICE_MS);
    const notice: Notice = { ...n, id, ms };
    usePlayer.setState((s) => {
      const kept = s.notices.filter((x) => !x.hud);
      const list = [notice, ...kept].slice(0, MAX_NOTICES);
      return { notices: list };
    });
    this.timeNotice(id, ms);
    return id;
  }

  /** A key's readout in the corner: replaces the last one and goes after 900 ms. */
  hud(text: string): void {
    const id = nextNoticeId();
    usePlayer.setState((s) => ({
      notices: [
        { id, text, icon: 'info' as const, hud: true, ms: HUD_MS },
        ...s.notices.filter((x) => !x.hud),
      ].slice(0, MAX_NOTICES),
    }));
    this.timeNotice(id, HUD_MS);
  }

  private timeNotice(id: number, ms: number): void {
    const timer = window.setTimeout(() => {
      this.dismissNotice(id);
    }, ms);
    this.noticeTimers.set(id, timer);
  }

  /** The pointer is over a notice: its time stops until the pointer leaves (§5). */
  holdNotice(id: number, hold: boolean): void {
    const timer = this.noticeTimers.get(id);
    if (hold) {
      if (timer !== undefined) window.clearTimeout(timer);
      this.noticeTimers.delete(id);
    } else if (timer === undefined) {
      const n = usePlayer.getState().notices.find((x) => x.id === id);
      if (n !== undefined) this.timeNotice(id, n.ms);
    }
  }

  dismissNotice(id: number): void {
    const timer = this.noticeTimers.get(id);
    if (timer !== undefined) window.clearTimeout(timer);
    this.noticeTimers.delete(id);
    usePlayer.setState((s) => ({ notices: s.notices.filter((x) => x.id !== id) }));
  }

  /* ------------------------------------------------------------ hints */

  markHint(which: 'drop' | 'move' | 'word' | 'point'): void {
    if (usePlayer.getState().prefs.hints[which]) return;
    updatePrefs((p) => ({ ...p, hints: { ...p.hints, [which]: true } }));
  }

  /* ------------------------------------------------------------ the end */

  private checkSummary(): void {
    const s = usePlayer.getState();
    if (s.summary || s.duration <= 0) return;
    const now = this.time();
    const credits = s.chapters.find((c) => /credits|end credits|générique|abspann/i.test(c.title ?? ''));
    if (credits !== undefined && now >= credits.start && now < credits.end) {
      this.showSummary();
      return;
    }
    const tr = trackIn(s, 1);
    const last = tr?.cues[tr.cues.length - 1];
    if (last !== undefined && tr !== undefined) {
      const lastEnd = (last.end + tr.offsetMs) / 1000;
      if (now >= lastEnd + SUMMARY_AFTER_LAST_CUE_S && lastEnd > s.duration * 0.5 && now < s.duration - 1) {
        this.showSummary();
      }
    }
  }

  showSummary(): void {
    if (usePlayer.getState().summary) return;
    usePlayer.setState({ summary: true, menu: null });
  }

  hideSummary(): void {
    usePlayer.setState({ summary: false });
  }

  /** Back to the empty screen; the video stays in Continue watching (§6.8). */
  library(): void {
    this.close();
    usePlayer.setState((s) => ({ ...resetForVideo(s), phase: 'empty', file: null, title: null }));
    void this.refreshRecent();
  }

  async refreshRecent(): Promise<void> {
    try {
      const recent = await this.media.recent();
      usePlayer.setState({ recent });
    } catch {
      usePlayer.setState({ recent: [] });
    }
  }

  /* ------------------------------------------------------------ resume */

  private saveResume(ended = false): void {
    const s = usePlayer.getState();
    if (s.file === null || s.playback === null || s.duration <= 0) return;
    const position = ended ? s.duration : this.time();
    void this.media.saveResume(s.file.id, position, s.duration).catch(() => undefined);
  }

  /**
   * Before the window closes, and as it is hidden: the minutes watched so far
   * are reported and the events go at once (the page may not get another turn).
   * Waits at most `CLOSE_FLUSH_MS`, so closing is never held up.
   */
  async sendActivity(closing: boolean): Promise<void> {
    // Closing is sent once: the window's own close button sends, then asks
    // the window to close, whose close-requested event would send again.
    if (closing) {
      this.closing ??= this.sendOnce(true);
      return this.closing;
    }
    return this.sendOnce(false);
  }

  private closing: Promise<void> | undefined;

  private async sendOnce(closing: boolean): Promise<void> {
    if (closing) this.activity.closed();
    else this.activity.report();
    const sent = (async () => {
      // A send already on its way is joined first; the second takes what was just noted.
      await flushEvents(true);
      await flushEvents(true);
    })();
    await Promise.race([sent, new Promise((resolve) => setTimeout(resolve, CLOSE_FLUSH_MS))]);
  }

  /** However the window closes (⌘W, Alt+F4, the system), what is left is sent first. */
  bindClose(): () => void {
    return this.host.window.onCloseRequested?.(() => this.sendActivity(true)) ?? (() => undefined);
  }

  close(): void {
    this.activity.closed();
    this.saveResume();
    cancelAnimationFrame(this.frameHandle);
    window.clearInterval(this.resumeTimer);
    this.generation++;
    this.stream?.stop();
  }

  /* ------------------------------------------------------------ errors */

  private failFromEngine(cause: unknown, file: FileRef): void {
    const word = mediaError(cause);
    const kind: ErrorKind =
      word === 'file_gone' || word === 'unknown_file'
        ? 'missing'
        : word === 'no_encoder' || word === 'no_video'
          ? 'codec'
          : word === 'ffmpeg_missing'
            ? 'engine'
            : word === 'unreadable'
              ? // The engine's probe could not read it: damaged or not a video.
                'damaged'
              : 'converter';
    this.fail(kind, `${file.name}: ${String(cause)}`);
  }

  fail(kind: ErrorKind, details: string): void {
    this.activity.failed(kind);
    const s = usePlayer.getState();
    const v = s.playback?.info.video[0];
    usePlayer.setState({
      phase: 'error',
      error: {
        kind,
        ...(s.file ? { file: s.file.name } : {}),
        ...(v ? { codec: v.codec } : {}),
        details,
      },
    });
  }

  /** "Copy details for support": the file's streams and this app's version. */
  supportDetails(): string {
    const s = usePlayer.getState();
    const p = s.playback;
    const lines = [
      `file: ${s.file?.name ?? ''}`,
      `error: ${s.error?.kind ?? ''} ${s.error?.details ?? ''}`,
      p ? `mode: ${p.mode} · mime: ${p.mime}` : '',
      p ? `container: ${p.info.container}` : '',
      ...(p?.info.video.map(
        (v) => `video: ${v.codec} ${v.profile ?? ''} ${String(v.width)}x${String(v.height)}`,
      ) ?? []),
      ...(p?.info.audio.map((a) => `audio: ${a.codec} ${String(a.channels)}ch ${a.language ?? ''}`) ?? []),
    ];
    return lines.filter((l) => l !== '').join('\n');
  }

  /**
   * The lines the other visible tracks show at a moment (the file's
   * seconds), with their languages: a parallel line in the notebook's
   * meaning language becomes the example's translation.
   */
  parallelLines(slot: SlotNumber | null, fileSeconds: number): ParallelLine[] {
    const s = usePlayer.getState();
    const out: ParallelLine[] = [];
    for (const n of [1, 2, 3] as const) {
      if (n === slot || !slotVisible(s, n)) continue;
      const tr = trackIn(s, n);
      if (tr === undefined || tr.picture) continue;
      const text = activeIndices(tr.cues, fileSeconds * 1000, tr.offsetMs)
        .map((i) => tr.cues[i]?.text ?? '')
        .filter((x) => x.trim() !== '')
        .join(' ');
      if (text !== '') out.push({ lang: tr.lang, text });
    }
    return out;
  }

  /** What "Seen in" says: the title, the episode and the cue's time. */
  seenInParts(fileSeconds: number): { title: string; episode: string | undefined; time: string } {
    const s = usePlayer.getState();
    const title = s.title?.title ?? s.file?.name ?? '';
    const ep = s.title ? episodeShort(s.title) : undefined;
    return { title, episode: ep, time: clock(fileSeconds) };
  }

  /** The local day, for the once-a-day rules. */
  today(): string {
    return localDay(new Date());
  }

  /** The active cue indices of a track at the playhead. */
  activeIn(tr: TrackState, fileSeconds: number): number[] {
    return activeIndices(tr.cues, fileSeconds * 1000, tr.offsetMs);
  }
}

/** What stays when a new video opens: prefs, recent, drag state; the rest starts again. */
function resetForVideo(s: ReturnType<typeof usePlayer.getState>): Partial<ReturnType<typeof initialState>> {
  const base = initialState();
  return {
    phase: base.phase,
    error: null,
    playback: null,
    chapters: [],
    duration: 0,
    paused: true,
    speed: 1,
    audio: undefined,
    episodes: null,
    tracks: {},
    slots: [null, null, null],
    off: [],
    master: true,
    shown: [true, true, true],
    focusSlot: 1,
    prompt: null,
    card: null,
    sync: null,
    summary: false,
    dots: [],
    menu: null,
    panel: s.panel,
  };
}

export function speedLabel(speed: number): string {
  return `${String(Math.round(speed * 100) / 100)}×`;
}

export const MAX_TRACKS = MAX_SHOWN;
