/**
 * Which subtitle lines are on screen, with each track's offset. The same
 * rules as the engine's `src/lib/media/cues.ts` in lexpad_desktop, returning
 * indices so the overlay can tell a new line from the one already drawn.
 *
 * Cues are in the file's milliseconds, sorted by start; a track's offset
 * (positive shows the lines later) is added to every cue.
 */
import type { Cue } from '@/lib/platform/media.js';

/** How far back an overlapping cue may start and still be on screen. */
const LONGEST_CUE_MS = 120_000;

/** The first index whose cue starts after `t`. */
function upperBound(cues: readonly Cue[], t: number): number {
  let lo = 0;
  let hi = cues.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    const c = cues[mid];
    if (c !== undefined && c.start <= t) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

/** The indices of the cues on screen at the file's time `t` (ms). */
export function activeIndices(cues: readonly Cue[], t: number, offsetMs: number): number[] {
  const at = t - offsetMs;
  const end = upperBound(cues, at);
  const out: number[] = [];
  for (let i = end - 1; i >= 0; i--) {
    const c = cues[i];
    if (c === undefined) continue;
    if (c.start < at - LONGEST_CUE_MS) break;
    if (c.end > at) out.push(i);
  }
  return out.reverse();
}

/** The index of the cue that started last at or before `t` (−1 before the first). */
export function lastCueIndexBefore(cues: readonly Cue[], t: number, offsetMs: number): number {
  return upperBound(cues, t - offsetMs) - 1;
}

/** The index of the cue nearest to `t` by its start, for the sync picker. */
export function nearestIndex(cues: readonly Cue[], t: number, offsetMs: number): number {
  if (cues.length === 0) return -1;
  const at = t - offsetMs;
  const i = upperBound(cues, at);
  const before = cues[i - 1];
  const after = cues[i];
  if (before === undefined) return i;
  if (after === undefined) return i - 1;
  return at - before.start <= after.start - at ? i - 1 : i;
}

/** The sync picker's five lines: two before the nearest, the nearest, two after (§8.1). */
export function aroundIndices(cues: readonly Cue[], t: number, offsetMs: number): number[] {
  const n = nearestIndex(cues, t, offsetMs);
  if (n < 0) return [];
  const from = Math.max(0, Math.min(n - 2, cues.length - 5));
  const out: number[] = [];
  for (let i = from; i < Math.min(cues.length, from + 5); i++) out.push(i);
  return out;
}

/**
 * The offset that makes `cue` start at `t` (the frozen "now"): works whether
 * the track runs early or late (§8.1).
 */
export function offsetToStartNow(cue: Cue, t: number): number {
  return Math.round(t - cue.start);
}

/** Whether a line reads right to left: its first strong character. */
export function isRtlText(text: string): boolean {
  for (const ch of text) {
    if (/[\u0590-\u08ff\ufb1d-\ufdff\ufe70-\ufeff]/u.test(ch)) return true;
    if (/\p{L}/u.test(ch)) return false;
  }
  return false;
}
