/**
 * Subtitles inside the video file ("soft subs", as VLC shows them): which of
 * them the player loads by itself, and what the menu calls each one. The
 * core finds them (ffprobe), maps the container's tag to a language
 * ("per" and "fas" are Persian) and reads the text ones out of the file; this
 * is only the page's choice and wording.
 */
import { language } from './languages.js';
import { relationOf, type Languages } from './slots.js';

/** What the choice needs of an embedded track (the core's `EmbeddedSubtitle`). */
export interface EmbeddedChoice {
  stream: number;
  supported: boolean;
  language?: string | undefined;
  default: boolean;
  forced: boolean;
  hearingImpaired: boolean;
}

/** The most embedded tracks loaded without a click: the learning language and your own. */
export const MAX_AUTO_EMBEDDED = 2;

/**
 * Best first within one language: a full track before a forced one (signs
 * only), the file's default before the rest, plain before SDH, then the
 * file's order.
 */
function rank(a: EmbeddedChoice, b: EmbeddedChoice): number {
  return (
    Number(a.forced) - Number(b.forced) ||
    Number(b.default) - Number(a.default) ||
    Number(a.hearingImpaired) - Number(b.hearingImpaired) ||
    a.stream - b.stream
  );
}

/**
 * The embedded text tracks to load when the video opens and no subtitle
 * file came with it: the best one in the language being learnt and the best
 * one in the learner's own (at most `MAX_AUTO_EMBEDDED`, learning first);
 * when neither language is there, the file's default, else its first. A
 * track flagged forced is still taken when it is the only one (releases
 * flag their one full subtitle forced so every player shows it).
 * Picture tracks are never chosen. Returns stream indexes.
 */
export function pickEmbedded(tracks: readonly EmbeddedChoice[], langs: Languages): number[] {
  const text = tracks.filter((t) => t.supported).sort(rank);
  if (text.length === 0) return [];
  const learning = text.find((t) => relationOf(t.language, langs) === 'learning');
  const own = text.find((t) => relationOf(t.language, langs) === 'own');
  const picked = [learning, own].filter((t): t is EmbeddedChoice => t !== undefined);
  if (picked.length > 0) return picked.slice(0, MAX_AUTO_EMBEDDED).map((t) => t.stream);
  const first = text.find((t) => t.default) ?? text[0];
  return first === undefined ? [] : [first.stream];
}

/** What the menu needs of a track in the file (the probe's `SubtitleStream`). */
export interface EmbeddedLabel {
  index: number;
  language: string | null;
  languageTag: string | null;
  title: string | null;
}

/** Container tags that say "no language" rather than naming one. */
const NO_LANGUAGE = new Set(['und', 'unk', 'mis', 'zxx', 'mul', '']);

/** The language part of a track's name: "Persian", or the tag as written, or the title. */
function baseName(track: EmbeddedLabel): string | undefined {
  const known = language(track.language ?? track.languageTag);
  if (known !== undefined) return known.name;
  const tag = (track.languageTag ?? '').trim().toLowerCase();
  if (!NO_LANGUAGE.has(tag)) return tag.toUpperCase();
  const title = track.title?.trim();
  return title !== undefined && title !== '' ? title : undefined;
}

/**
 * A track's name in the menu: its language ("Persian"), with its title when
 * another track of the file has the same language ("English (Commentary)"),
 * or its number when nothing tells them apart. A track with no language and
 * no title is "Track 3" (`trackWord` is the localized "Track").
 */
export function embeddedTrackName(
  track: EmbeddedLabel,
  all: readonly EmbeddedLabel[],
  trackWord: string,
): string {
  const name = baseName(track);
  if (name === undefined) return `${trackWord} ${String(track.index)}`;
  const twins = all.filter((t) => t.index !== track.index && baseName(t) === name);
  if (twins.length === 0) return name;
  const title = track.title?.trim();
  if (title !== undefined && title !== '' && title !== name && !twins.some((t) => t.title?.trim() === title))
    return `${name} (${title})`;
  return `${name} ${String(track.index)}`;
}
