/**
 * A slot's style as CSS (spec §7.2): the face (Vazirmatn by default for the
 * Arabic script), the colour, the edge and the opacity.
 */
import type { CSSProperties } from 'react';
import type { Colour, FontChoice, SlotStyle } from '../model/prefs.js';
import { usesArabicScript } from '../model/languages.js';

/** The colour as a token for the four named ones, or the learner's own "#rrggbb". */
export function trackColourVar(c: Colour): string {
  switch (c) {
    case 'white':
      return 'var(--sub1)';
    case 'yellow':
      return 'var(--sub2)';
    case 'sky':
      return 'var(--sub3)';
    case 'mint':
      return 'var(--sub-mint)';
    default:
      return c;
  }
}

/** The face a slot draws with; "auto" is Lexpad Sans, or Vazirmatn for the Arabic script. */
export function resolvedFont(font: FontChoice, lang: string | undefined): Exclude<FontChoice, 'auto'> {
  if (font !== 'auto') return font;
  return usesArabicScript(lang) ? 'vazirmatn' : 'sans';
}

export function fontFamily(font: FontChoice, lang: string | undefined): string {
  switch (resolvedFont(font, lang)) {
    case 'vazirmatn':
      return 'var(--fa)';
    case 'naskh':
      return "'Noto Naskh Arabic', var(--fa)";
    case 'atkinson':
      return "'Atkinson Hyperlegible', var(--sans)";
    case 'serif':
      return "'Noto Serif', var(--serif-sample)";
    case 'system':
      return 'system-ui, -apple-system, "Segoe UI", sans-serif';
    default:
      return 'var(--sans)';
  }
}

/** The text's inline style: colour, face, size, opacity and edge. */
export function lineStyle(style: SlotStyle, lang: string | undefined, fontPx: number): CSSProperties {
  return {
    color: trackColourVar(style.colour),
    fontFamily: fontFamily(style.font, lang),
    fontSize: `${String(fontPx)}px`,
    opacity: style.opacity,
    ['--bo' as string]: String(style.boxOpacity),
  };
}
