/**
 * What a dropped subtitle became (spec §9.4, §9.5; mock-ups 11 and 12). The
 * subtitle is already showing, framed in dashes; this card says what was
 * guessed — the language, from the file name or the letters, and the slot —
 * and offers one click to change it. It keeps itself after 8 s (12 s for
 * three rows or more), the pointer over it stops the clock, and it never
 * pauses the video.
 */
import { useEffect, useRef, useState } from 'react';
import { plural, t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import type { PlayerController } from '../controller.js';
import { LANGUAGES, languageName } from '../model/languages.js';
import type { ManyChoice, SlotNumber } from '../model/slots.js';
import { usePlayer, type DropPrompt as Prompt } from '../store.js';
import { PIcon } from './icons.js';
import { trackColourVar } from './subtitleStyle.js';
import styles from './DropPrompt.module.css';

/** How long the prompt waits before keeping what it guessed (§9.4, §9.5). */
export const PROMPT_MS = 8000;
export const PROMPT_MANY_MS = 12000;
/** Below this confidence the title asks: "Looks like Spanish?" (§9.2). */
export const UNSURE_BELOW = 0.6;

function useCountdown(ms: number, onDone: () => void): { left: number; hold: (on: boolean) => void } {
  const [left, setLeft] = useState(1);
  const held = useRef(false);
  const elapsed = useRef(0);
  const done = useRef(onDone);
  useEffect(() => {
    done.current = onDone;
  });
  useEffect(() => {
    let last = performance.now();
    let frame = 0;
    const step = (now: number): void => {
      if (!held.current) elapsed.current += now - last;
      last = now;
      const l = Math.max(0, 1 - elapsed.current / ms);
      setLeft(l);
      if (l <= 0) {
        done.current();
        return;
      }
      frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => {
      cancelAnimationFrame(frame);
    };
  }, [ms]);
  return {
    left,
    hold: (on) => {
      held.current = on;
    },
  };
}

export function DropPrompt({ controller }: { controller: PlayerController }): React.JSX.Element | null {
  const prompt = usePlayer((s) => s.prompt);
  if (prompt === null) return null;
  return prompt.kind === 'one' ? (
    <OnePrompt key={prompt.startedAt} prompt={prompt} controller={controller} />
  ) : (
    <ManyPrompt key={prompt.startedAt} prompt={prompt} controller={controller} />
  );
}

function OnePrompt({
  prompt,
  controller,
}: {
  prompt: Extract<Prompt, { kind: 'one' }>;
  controller: PlayerController;
}): React.JSX.Element | null {
  const track = usePlayer((s) => s.tracks[prompt.trackId]);
  const replaced = usePlayer((s) => (prompt.replaces === null ? undefined : s.tracks[prompt.replaces]));
  const slot = usePlayer((s) => {
    const i = s.slots.indexOf(prompt.trackId);
    return i < 0 ? prompt.slot : ((i + 1) as SlotNumber);
  });
  const ref = useRef<HTMLDivElement>(null);
  const close = (): void => {
    usePlayer.setState({ prompt: null });
  };
  const { left, hold } = useCountdown(PROMPT_MS, close);
  useEffect(() => {
    if (prompt.keyboard) ref.current?.querySelector<HTMLElement>('select')?.focus();
  }, [prompt.keyboard]);
  if (track === undefined) return null;
  const lang = track.lang;
  const place =
    slot === 1 ? t('player.place.bottom') : slot === 2 ? t('player.place.top') : t('player.place.above1');
  const unsure = track.langConfidence < UNSURE_BELOW;
  const title = t(unsure ? 'player.prompt.titleUnsure' : 'player.prompt.title', {
    lang: languageName(lang),
    n: slot,
    place: place.toLowerCase(),
  });
  const meta = [
    track.source.name,
    plural(track.cues.length, 'player.prompt.linesOne', 'player.prompt.lines', { count: track.cues.length }),
    track.encodingFixed
      ? t('player.prompt.encodingFixed', { lang: languageName(lang) })
      : track.textFixed
        ? t('player.prompt.textFixed')
        : null,
  ].filter((x): x is string => x !== null && x !== '');
  const remove = (): void => {
    controller.removeTrack(track.id);
    if (prompt.replaces !== null && replaced !== undefined) controller.put(prompt.replaces, prompt.slot);
    close();
  };
  return (
    <div
      ref={ref}
      className={styles.prompt}
      role="dialog"
      aria-label={title}
      onPointerEnter={() => {
        hold(true);
      }}
      onPointerLeave={() => {
        hold(false);
      }}
      onFocus={() => {
        hold(true);
      }}
      data-player-overlay=""
    >
      <div className={styles.head}>
        <span className={styles.tile}>
          <PIcon name="file" size={22} />
        </span>
        <div className={styles.body}>
          <div className={styles.title}>{title}</div>
          <div className={styles.meta}>{meta.join(' · ')}</div>
          <div className={styles.controls}>
            <LanguageSelect
              value={lang}
              unsure={unsure}
              onChange={(code) => {
                usePlayer.setState((s) => ({
                  tracks: { ...s.tracks, [track.id]: { ...track, lang: code, langConfidence: 1 } },
                }));
              }}
            />
            <div className={styles.segs} role="radiogroup" aria-label={t('player.prompt.slot')}>
              {([1, 2, 3] as const).map((n) => (
                <button
                  key={n}
                  type="button"
                  role="radio"
                  aria-checked={slot === n}
                  className={cx(styles.seg, slot === n && styles.segOn)}
                  onClick={() => {
                    controller.put(track.id, n);
                    // The one it would have replaced goes back to its slot.
                    if (prompt.replaces !== null && n !== prompt.slot)
                      controller.put(prompt.replaces, prompt.slot);
                  }}
                >
                  {n === 1
                    ? t('player.prompt.slot1')
                    : n === 2
                      ? t('player.prompt.slot2')
                      : t('player.prompt.slot3')}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
      <div className={styles.actions}>
        <button type="button" className={styles.text} onClick={remove}>
          {t('player.prompt.remove')}
        </button>
        <button type="button" className={styles.primary} onClick={close}>
          <PIcon name="check" size={18} />
          {replaced !== undefined && slot === prompt.slot
            ? t('player.prompt.replace', { lang: languageName(replaced.lang) })
            : t('player.prompt.keep')}
        </button>
      </div>
      <div className={styles.timer} aria-hidden="true">
        <div className={styles.timerFill} style={{ transform: `scaleX(${String(left)})` }} />
      </div>
    </div>
  );
}

function ManyPrompt({
  prompt,
  controller,
}: {
  prompt: Extract<Prompt, { kind: 'many' }>;
  controller: PlayerController;
}): React.JSX.Element {
  const tracks = usePlayer((s) => s.tracks);
  const slots = usePlayer((s) => s.slots);
  const styles3 = usePlayer((s) => s.prefs.styles);
  const close = (): void => {
    usePlayer.setState({ prompt: null });
  };
  const { hold } = useCountdown(prompt.choices.length >= 3 ? PROMPT_MANY_MS : PROMPT_MS, close);
  const slotNow = (c: ManyChoice): SlotNumber | null => {
    const i = slots.indexOf(c.id);
    return i < 0 ? null : ((i + 1) as SlotNumber);
  };
  const undo = (): void => {
    controller.restoreSlots(
      prompt.before,
      prompt.choices.map((c) => c.id),
    );
    close();
  };
  return (
    <div
      className={cx(styles.prompt, styles.many)}
      role="dialog"
      aria-label={plural(prompt.choices.length, 'player.notice.subtitlesAddedOne', 'player.prompt.many', {
        count: prompt.choices.length,
      })}
      onPointerEnter={() => {
        hold(true);
      }}
      onPointerLeave={() => {
        hold(false);
      }}
      data-player-overlay=""
    >
      <div className={styles.manyHead}>
        <span className={cx(styles.tile, styles.tileSmall)}>
          <PIcon name="file" size={22} />
        </span>
        <div>
          <div className={styles.title}>{t('player.prompt.many', { count: prompt.choices.length })}</div>
          <div className={styles.meta}>{t('player.prompt.manyLead')}</div>
        </div>
      </div>
      {prompt.choices.map((c) => {
        const tr = tracks[c.id];
        if (tr === undefined) return null;
        const now = slotNow(c);
        return (
          <div key={c.id} className={styles.manyRow}>
            <div className={styles.manyFile}>
              <div className={styles.fileName}>{tr.source.name}</div>
              <div className={styles.reason}>
                {t(`player.reason.${now === null ? 'full' : c.reason}` as 'player.reason.full')}
              </div>
            </div>
            <LanguageSelect
              value={tr.lang}
              unsure={tr.langConfidence < UNSURE_BELOW}
              onChange={(code) => {
                usePlayer.setState((s) => ({
                  tracks: { ...s.tracks, [tr.id]: { ...tr, lang: code, langConfidence: 1 } },
                }));
              }}
            />
            <label className={styles.selectWrap}>
              <span
                className={styles.slotDot}
                style={now === null ? undefined : { background: trackColourVar(styles3[now].colour) }}
                aria-hidden="true"
              />
              <select
                className={cx(styles.select, styles.slotSelect, now === null && styles.off)}
                aria-label={t('player.prompt.slot')}
                value={now === null ? 'off' : String(now)}
                onChange={(e) => {
                  const v = e.target.value;
                  if (v === 'off') controller.toOff(tr.id);
                  else controller.put(tr.id, Number(v) as SlotNumber);
                }}
              >
                <option value="1">{t('player.prompt.slot1')}</option>
                <option value="2">{t('player.prompt.slot2')}</option>
                <option value="3">{t('player.prompt.slot3Long')}</option>
                <option value="off">{t('player.subs.off')}</option>
              </select>
              <PIcon name="cd" size={15} className={styles.chev} />
            </label>
          </div>
        );
      })}
      <div className={cx(styles.actions, styles.manyActions)}>
        <button type="button" className={styles.text} onClick={undo}>
          {t('player.prompt.undo')}
        </button>
        <button type="button" className={styles.primary} onClick={close}>
          <PIcon name="check" size={18} />
          {t('player.prompt.looksRight')}
        </button>
      </div>
    </div>
  );
}

/** The language menu: "فارسی Persian ▾", ringed when the guess was unsure. */
/** "Español" (a Latin autonym reads alone), "فارسی Persian" (another script gets the English name too). */
function optionName(l: { autonym: string; name: string }): string {
  if (l.autonym === l.name || /^[\p{Script=Latin}\s'’-]+$/u.test(l.autonym)) return l.autonym;
  return `${l.autonym} ${l.name}`;
}

export function LanguageSelect({
  value,
  unsure,
  onChange,
}: {
  value: string | undefined;
  unsure: boolean;
  onChange: (code: string) => void;
}): React.JSX.Element {
  const known = LANGUAGES.some((l) => l.code === value);
  return (
    <label className={cx(styles.selectWrap, unsure && styles.unsure)}>
      <select
        className={styles.select}
        aria-label={t('player.prompt.language')}
        value={known ? value : ''}
        onChange={(e) => {
          onChange(e.target.value);
        }}
      >
        {!known ? <option value="">{(value ?? '?').toUpperCase()}</option> : null}
        {LANGUAGES.map((l) => (
          <option key={l.code} value={l.code}>
            {optionName(l)}
          </option>
        ))}
      </select>
      <PIcon name="cd" size={15} className={styles.chev} />
    </label>
  );
}
