/**
 * Every transient message in one place, the top-left corner (top-right in a
 * right-to-left interface), one style (spec §5): newest on top, at most
 * three, 8 px apart; 4 s on screen, 8 s with an action, and the pointer over
 * one stops its clock. Key readouts take the same place for 900 ms and
 * replace each other. Nothing here ever sits over the middle of the picture.
 */
import { useEffect, useRef, type RefObject } from 'react';
import { t } from '@/i18n/index.js';
import type { PlayerController } from '../controller.js';
import { usePlayer, type Notice } from '../store.js';
import { PIcon } from './icons.js';
import { Keys } from './kit.js';
import styles from './Notices.module.css';

interface Props {
  controller: PlayerController;
  mod: string;
  /** The stack's box, so a top subtitle can step down below it. */
  boxRef?: RefObject<HTMLDivElement | null>;
}

export function Notices({ controller, mod, boxRef }: Props): React.JSX.Element {
  const notices = usePlayer((s) => s.notices);
  return (
    <div
      ref={boxRef}
      className={styles.stack}
      role="status"
      aria-live="polite"
      aria-label={t('player.notices.label')}
    >
      {notices.map((n) => (
        <NoticeView key={n.id} notice={n} controller={controller} mod={mod} />
      ))}
    </div>
  );
}

function NoticeView({
  notice,
  controller,
  mod,
}: {
  notice: Notice;
  controller: PlayerController;
  mod: string;
}): React.JSX.Element {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = ref.current;
    if (el === null) return;
    const hold = (): void => {
      controller.holdNotice(notice.id, true);
    };
    const go = (): void => {
      controller.holdNotice(notice.id, false);
    };
    el.addEventListener('pointerenter', hold);
    el.addEventListener('pointerleave', go);
    el.addEventListener('focusin', hold);
    el.addEventListener('focusout', go);
    return () => {
      el.removeEventListener('pointerenter', hold);
      el.removeEventListener('pointerleave', go);
      el.removeEventListener('focusin', hold);
      el.removeEventListener('focusout', go);
    };
  }, [controller, notice.id]);
  const keys = notice.action?.keys?.map((k) => (k === 'mod' ? mod : k));
  return (
    <div ref={ref} className={notice.hud === true ? styles.hud : styles.notice} data-player-overlay="">
      <PIcon
        name={notice.icon === 'undo' ? 'undo' : notice.icon}
        size={18}
        className={notice.icon === 'pause' ? styles.iconDim : styles.icon}
      />
      <span className={styles.text}>
        {notice.strong !== undefined ? (
          <>
            <span className={styles.soft}>{notice.text}</span>{' '}
            <b className={styles.strong}>{notice.strong}</b>
            {notice.tail !== undefined ? <span className={styles.soft}> {notice.tail}</span> : null}
          </>
        ) : (
          <>
            {notice.text}
            {notice.tail !== undefined ? <span className={styles.soft}> · {notice.tail}</span> : null}
          </>
        )}
      </span>
      {notice.action !== undefined ? (
        <button
          type="button"
          className={styles.action}
          onClick={() => {
            notice.action?.run();
            controller.dismissNotice(notice.id);
          }}
        >
          {notice.action.label}
        </button>
      ) : null}
      {keys !== undefined ? (
        <span className={styles.keys}>
          <Keys keys={keys} />
        </span>
      ) : null}
    </div>
  );
}
