import { useEffect } from 'react';
import { restoreSession } from '@/api/client.js';
import { startActivity } from '@/features/activity/events.js';
import { platform } from '@/lib/platform/index.js';
import { useConfig } from '@/lib/useConfig.js';
import type { PlayerHost } from '@/lib/platform/types.js';

/**
 * The Player's window runs outside the app's sign-in gate (videos play
 * without an account), so the client events' sender is started here: for
 * the account the desktop core holds (`PlayerAccount.userId`), once the
 * core says it is connected, and again whenever the session changes. Before
 * that, what the Player notes waits in memory (`lib/surface.ts`) and goes with
 * the account that signs in from this window; nothing leaves before the
 * server takes it (`activity` in GET /config).
 */
export function usePlayerSender(host: PlayerHost): void {
  useEffect(() => {
    useConfig.getState().ensure();
    let stop: (() => void) | undefined;
    const life = { live: true };
    // A function, so a check made after an await reads the current value.
    const alive = (): boolean => life.live;
    const follow = async (): Promise<void> => {
      stop?.();
      stop = undefined;
      try {
        const account = await host.account();
        // The account the core holds, never the main window's database: the
        // two can differ while one window has not followed a sign-in yet. A
        // core that does not say starts nothing.
        const owner = account.userId;
        if (!alive() || !account.connected || typeof owner !== 'string' || !(await restoreSession())) return;
        if (!alive()) return;
        stop = startActivity(owner);
      } catch {
        // Offline core or no local account yet: nothing is sent, nothing is lost.
      }
    };
    void follow();
    const off = platform.desktop?.onSessionChange(() => {
      void follow();
    });
    return () => {
      life.live = false;
      off?.();
      stop?.();
    };
  }, [host]);
}
