/**
 * The top bar (spec §6.8, §24.3): Library, the Lexpad button, the title with
 * its episode chip (which opens the episode list), keyboard shortcuts and
 * player settings. On a Mac the system's window buttons sit at the left
 * (86 px kept for them); on Windows the caption buttons at the right
 * (152 px), drawn here because the window has no frame (§19).
 */
import { useState } from 'react';
import { plural, t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import type { PlayerController } from '../controller.js';
import type { Os } from '../model/keys.js';
import { episodeCode, parseTitle } from '../model/title.js';
import { minutesLeft } from '../model/time.js';
import { usePlayer } from '../store.js';
import { LexpadMark, PIcon } from './icons.js';
import { IconButton, Popover, Row } from './kit.js';
import styles from './TopBar.module.css';

interface Props {
  controller: PlayerController;
  os: Os;
  onLexpad: () => void;
  onShortcuts: () => void;
  onSettings: () => void;
}

export function TopBar({ controller, os, onLexpad, onShortcuts, onSettings }: Props): React.JSX.Element {
  const title = usePlayer((s) => s.title);
  const menu = usePlayer((s) => s.menu);
  const series = usePlayer((s) => s.episodes);
  const small = usePlayer((s) => s.small);
  const [chipEl, chipRef] = useState<HTMLButtonElement | null>(null);
  const mod = os === 'macos' ? '⌘' : 'Ctrl';
  const code = title ? episodeCode(title) : undefined;
  return (
    <div className={cx(styles.topbar, os === 'windows' && styles.windows)} data-chrome-zone="">
      <IconButton
        icon="grid"
        label={t('player.top.library')}
        tipSide="down"
        onClick={() => {
          controller.library();
        }}
      />
      <LexpadButton onClick={onLexpad} mod={mod} compact={small} />
      <div className={styles.title}>
        <span className={styles.name}>{title?.title ?? ''}</span>
        {code !== undefined ? (
          <span className={styles.anchor}>
            <button
              ref={chipRef}
              type="button"
              className={styles.ep}
              aria-haspopup={series !== null ? 'menu' : undefined}
              aria-expanded={series !== null ? menu === 'episodes' : undefined}
              disabled={series === null}
              onClick={() => {
                usePlayer.setState((s) => ({ menu: s.menu === 'episodes' ? null : 'episodes' }));
              }}
            >
              {code}
              {title?.episodeTitle ? <span className={styles.epTitle}>{title.episodeTitle}</span> : null}
              {series !== null ? <PIcon name="cd" size={16} /> : null}
            </button>
            {menu === 'episodes' && series !== null ? (
              <Episodes
                controller={controller}
                anchor={chipEl}
                onClose={() => {
                  usePlayer.setState({ menu: null });
                }}
              />
            ) : null}
          </span>
        ) : null}
      </div>
      {os === 'macos' ? <div className={styles.balance} aria-hidden="true" /> : null}
      <IconButton
        icon="kbd"
        label={t('player.top.shortcuts')}
        keys={['?']}
        tipSide="down"
        onClick={onShortcuts}
      />
      <IconButton
        icon="sliders"
        label={t('player.top.settings')}
        keys={[`${mod},`]}
        tipSide="down"
        onClick={onSettings}
      />
    </div>
  );
}

/**
 * "Lexpad": opens or brings forward the learning window (⌘1 / Ctrl+1). The
 * badge counts words saved in this session the learning window has not
 * shown yet (§24.3).
 */
export function LexpadButton({
  onClick,
  mod,
  compact,
}: {
  onClick: () => void;
  mod: string;
  compact: boolean;
}): React.JSX.Element {
  const unseen = usePlayer((s) => s.unseen);
  const label =
    unseen > 0
      ? plural(unseen, 'player.lexpad.ariaOne', 'player.lexpad.aria', { count: unseen })
      : t('player.lexpad.tip');
  return (
    <button
      type="button"
      className={cx(styles.lexbtn, compact && styles.lexCompact)}
      onClick={onClick}
      aria-label={label}
      aria-keyshortcuts={`${mod === '⌘' ? 'Meta' : 'Control'}+1`}
      title={`${t('player.lexpad.tip')}  ${mod}1`}
    >
      <span className={styles.mark}>
        <LexpadMark size={14} weight={2.6} />
      </span>
      {compact ? null : t('player.lexpad.label')}
      {unseen > 0 ? (
        <span className={styles.badge} aria-hidden="true">
          {unseen}
        </span>
      ) : null}
    </button>
  );
}

function Episodes({
  controller,
  anchor,
  onClose,
}: {
  controller: PlayerController;
  anchor: HTMLElement | null;
  onClose: () => void;
}): React.JSX.Element {
  const episodes = usePlayer((s) => s.episodes);
  return (
    <Popover label={t('player.top.episodes')} onClose={onClose} anchor={anchor} className={styles.episodes}>
      {episodes?.items.map((e, i) => {
        const tt = parseTitle(e.file.name);
        const code = episodeCode({
          ...tt,
          ...(e.season !== undefined ? { season: e.season } : {}),
          ...(e.episode !== undefined ? { episode: e.episode } : {}),
        });
        const pct = e.duration > 0 ? Math.min(100, (e.position / e.duration) * 100) : 0;
        return (
          <Row
            key={e.file.id}
            role="menuitemradio"
            checked={i === episodes.current}
            onClick={() => {
              onClose();
              if (i !== episodes.current) void controller.openVideo(e.file);
            }}
          >
            <span className={styles.thumb}>
              <PIcon name="film" size={20} />
              <span className={styles.thumbBar}>
                <span
                  style={{ width: `${String(e.watched ? 100 : pct)}%` }}
                  className={e.watched ? styles.thumbDone : undefined}
                />
              </span>
            </span>
            <span className={styles.epText}>
              <span className={styles.epName}>
                {code ?? ''} {tt.episodeTitle ?? ''}
              </span>
              <span className={styles.epMeta}>
                {e.watched
                  ? t('player.top.watched')
                  : e.position > 0
                    ? t('player.recent.minLeft', { count: minutesLeft(e.position, e.duration) })
                    : ''}
              </span>
            </span>
            {e.watched ? <PIcon name="check" size={18} className={styles.tick} /> : null}
          </Row>
        );
      })}
    </Popover>
  );
}

/** Windows: minimise, maximise and close, 46×36, at the top right, shown with the chrome (§2, §19). */
export function CaptionButtons({ controller }: { controller: PlayerController }): React.JSX.Element {
  const w = controller.host.window;
  return (
    <div className={styles.caps} data-chrome-zone="">
      <button
        type="button"
        className={styles.cap}
        aria-label={t('player.window.minimise')}
        onClick={() => void w.minimize()}
      >
        <PIcon name="min" size={16} style={{ strokeWidth: 1.2 }} />
      </button>
      <button
        type="button"
        className={styles.cap}
        aria-label={t('player.window.maximise')}
        onClick={() => void w.toggleMaximize()}
      >
        <PIcon name="max" size={16} style={{ strokeWidth: 1.2 }} />
      </button>
      <button
        type="button"
        className={cx(styles.cap, styles.capClose)}
        aria-label={t('player.window.close')}
        onClick={() => void controller.sendActivity(true).then(() => w.close())}
      >
        <PIcon name="x" size={16} style={{ strokeWidth: 1.2 }} />
      </button>
    </div>
  );
}
