/**
 * Which of the three subtitle slots a new subtitle goes to (spec §9.3):
 * the learning language at the bottom (Subtitle 1), the learner's own at the
 * top (Subtitle 2), anything else above Subtitle 1 (Subtitle 3). When all
 * three show, a new one waits "Off" in the panel. Never asks what it can
 * guess; always says what it guessed.
 */

export type SlotNumber = 1 | 2 | 3;

/** The most subtitles shown at once (owner, phase 1). */
export const MAX_SHOWN = 3;

/** Where a slot sits by default. */
export type Place = 'bottom' | 'top' | 'above1';

export const SLOT_PLACE: Record<SlotNumber, Place> = { 1: 'bottom', 2: 'top', 3: 'above1' };

/** How a subtitle relates to the learner. */
export type Relation = 'learning' | 'own' | 'other';

export interface Languages {
  /** The default notebook's language; undefined when signed out with no notebook. */
  learning: string | undefined;
  /** The profile's own language, or the system's when signed out. */
  own: string | undefined;
}

function base(code: string | undefined): string | undefined {
  return code?.toLowerCase().split(/[-_]/)[0];
}

export function relationOf(lang: string | undefined, langs: Languages): Relation {
  const l = base(lang);
  if (l === undefined) return 'other';
  if (l === base(langs.learning)) return 'learning';
  if (l === base(langs.own)) return 'own';
  // Signed out with no notebook: a subtitle that is not in your own language
  // is taken as the one you are learning.
  if (langs.learning === undefined && langs.own !== undefined) return 'learning';
  return 'other';
}

/** The slot a relation asks for. */
export function targetSlot(relation: Relation): SlotNumber {
  return relation === 'learning' ? 1 : relation === 'own' ? 2 : 3;
}

/** What each slot holds now: a track id, or null when free. */
export type Occupancy = readonly [string | null, string | null, string | null];

export interface OneChoice {
  slot: SlotNumber;
  relation: Relation;
  /** The track now in that slot, which "Yes, keep it" replaces (the default). */
  replaces: string | null;
  /** A free slot to offer instead, when the target is taken. */
  free: SlotNumber | null;
}

function freeSlots(occupied: Occupancy): SlotNumber[] {
  const out: SlotNumber[] = [];
  ([1, 2, 3] as const).forEach((n) => {
    if (occupied[n - 1] === null) out.push(n);
  });
  return out;
}

/** One dropped subtitle while something plays (the prompt, §9.4). */
export function chooseOne(lang: string | undefined, langs: Languages, occupied: Occupancy): OneChoice {
  const relation = relationOf(lang, langs);
  const slot = targetSlot(relation);
  const replaces = occupied[slot - 1] ?? null;
  const free = replaces === null ? null : (freeSlots(occupied)[0] ?? null);
  return { slot, relation, replaces, free };
}

export interface ManyItem {
  id: string;
  lang: string | undefined;
  /** How the language was found: the file name, the letters, the container. */
  source: 'fileName' | 'text' | 'track' | undefined;
}

export interface ManyChoice {
  id: string;
  /** null = Off: kept in the panel, not shown. */
  slot: SlotNumber | null;
  relation: Relation;
  /** Why, in the words the prompt shows (`player.reason.*`). */
  reason:
    'fileNameLearning' | 'fileNameOwn' | 'fileName' | 'lettersLearning' | 'lettersOwn' | 'letters' | 'full';
}

function reasonOf(item: ManyItem, relation: Relation): ManyChoice['reason'] {
  const byName = item.source === 'fileName' || item.source === 'track';
  if (relation === 'learning') return byName ? 'fileNameLearning' : 'lettersLearning';
  if (relation === 'own') return byName ? 'fileNameOwn' : 'lettersOwn';
  return byName ? 'fileName' : 'letters';
}

/**
 * Several subtitles at once (§9.5, and subtitles dropped with a video,
 * §9.3): each to the slot its language asks for while it is free, the
 * learning language first, then your own, then the rest in the order given;
 * a subtitle whose slot is taken goes to the next free one; past three, Off.
 */
export function chooseMany(items: readonly ManyItem[], langs: Languages, occupied: Occupancy): ManyChoice[] {
  const taken: (string | null)[] = [...occupied];
  const rank = (r: Relation): number => (r === 'learning' ? 0 : r === 'own' ? 1 : 2);
  const order = items
    .map((item, index) => ({ item, index, relation: relationOf(item.lang, langs) }))
    .sort((a, b) => rank(a.relation) - rank(b.relation) || a.index - b.index);
  const out = new Map<string, ManyChoice>();
  for (const { item, relation } of order) {
    let slot: SlotNumber | null = targetSlot(relation);
    if (taken[slot - 1] !== null) {
      const free = ([1, 2, 3] as const).find((n) => taken[n - 1] === null);
      slot = free ?? null;
    }
    if (slot !== null) taken[slot - 1] = item.id;
    out.set(item.id, {
      id: item.id,
      slot,
      relation,
      reason: slot === null ? 'full' : reasonOf(item, relation),
    });
  }
  // Back in the order the files came, as the prompt lists them.
  return items.map((i) => out.get(i.id)).filter((c): c is ManyChoice => c !== undefined);
}
