/**
 * The mini player's chrome (spec §13, mock-up 21): over the picture on
 * hover, close, back to the big window, keep on top and subtitles at the
 * top; play, a seek line and the time at the bottom. Only Subtitle 1 shows,
 * scaled down. The core makes the window small and keeps it on top; the
 * whole window drags.
 */
import { useEffect, useRef, useState } from 'react';
import { t } from '@/i18n/index.js';
import type { PlayerController } from '../controller.js';
import { clock } from '../model/time.js';
import { slotVisible, usePlayer } from '../store.js';
import { IconButton } from './kit.js';
import styles from './Mini.module.css';

export function MiniChrome({
  controller,
  onBack,
}: {
  controller: PlayerController;
  onBack: () => void;
}): React.JSX.Element {
  const paused = usePlayer((s) => s.paused);
  const duration = usePlayer((s) => s.duration);
  const subsOn = usePlayer((s) => slotVisible(s, 1));
  const [pinned, setPinned] = useState(true);
  const [now, setNow] = useState(0);
  const fill = useRef<HTMLDivElement>(null);
  const last = useRef(-1);
  useEffect(
    () =>
      controller.onTick((time) => {
        if (fill.current !== null && duration > 0)
          fill.current.style.transform = `scaleX(${String(time / duration)})`;
        const s = Math.floor(time);
        if (s !== last.current) {
          last.current = s;
          setNow(time);
        }
      }),
    [controller, duration],
  );
  return (
    <div className={styles.mini} data-tauri-drag-region="">
      <div className={styles.shade} aria-hidden="true" data-tauri-drag-region="" />
      <div className={styles.top}>
        <IconButton
          icon="x"
          label={t('player.mini.close')}
          onClick={() => void controller.sendActivity(true).then(() => controller.host.window.close())}
          tipSide="down"
        />
        <IconButton icon="full" label={t('player.mini.back')} onClick={onBack} tipSide="down" />
        <span className={styles.spacer} data-tauri-drag-region="" />
        <IconButton
          icon="pin"
          label={t('player.mini.pin')}
          on={pinned}
          pressed={pinned}
          onClick={() => {
            const next = !pinned;
            setPinned(next);
            void controller.host.window.setOnTop(next);
          }}
          tipSide="down"
        />
        <IconButton
          icon="subs"
          label={t('player.ctl.subtitles')}
          on={subsOn}
          onClick={() => {
            controller.toggleSlot(1);
          }}
          tipSide="down"
        />
      </div>
      <div className={styles.bottom}>
        <IconButton
          icon={paused ? 'play' : 'pause'}
          label={paused ? t('player.ctl.play') : t('player.ctl.pause')}
          onClick={() => {
            controller.togglePlay();
          }}
        />
        <div
          className={styles.seek}
          role="slider"
          tabIndex={0}
          aria-label={t('player.ctl.seek')}
          aria-valuemin={0}
          aria-valuemax={Math.round(duration)}
          aria-valuenow={Math.round(now)}
          onPointerDown={(e) => {
            const r = e.currentTarget.getBoundingClientRect();
            controller.seek(((e.clientX - r.left) / r.width) * duration);
          }}
          onKeyDown={(e) => {
            if (e.key === 'ArrowLeft') controller.skip(-5);
            if (e.key === 'ArrowRight') controller.skip(5);
          }}
        >
          <div ref={fill} className={styles.fill} />
        </div>
        <span className={styles.time}>{clock(now)}</span>
      </div>
    </div>
  );
}
