export type IconName = keyof typeof P;

interface Props {
  name: IconName;
  size?: number;
  className?: string | undefined;
  style?: CSSProperties | undefined;
}

/** One of the player's icons; decorative, so screen readers skip it (the button carries the name). */
export function PIcon({ name, size = 22, className, style }: Props): React.JSX.Element {
  const [kind, body] = P[name];
  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      aria-hidden="true"
      focusable="false"
      className={className}
      style={{
        flex: 'none',
        ...(kind === 'fill'
          ? { fill: 'currentColor', stroke: 'none' }
          : {
              fill: 'none',
              stroke: 'currentColor',
              strokeWidth: 1.75,
              strokeLinecap: 'round',
              strokeLinejoin: 'round',
            }),
        ...style,
      }}
    >
      {body}
    </svg>
  );
}

/** The Lexpad notebook mark, drawn in `currentColor` (the card's and the Lexpad button's). */
export function LexpadMark({
  size = 16,
  weight = 2.4,
}: {
  size?: number;
  weight?: number;
}): React.JSX.Element {
  return (
    <svg viewBox="0 0 32 32" width={size} height={size} aria-hidden="true" focusable="false">
      <rect
        x="10"
        y="8"
        width="12"
        height="16"
        rx="2"
        fill="none"
        stroke="currentColor"
        strokeWidth={weight}
      />
      <path d="M14 8v16M17 12h2M17 15h2" stroke="currentColor" strokeWidth={weight} strokeLinecap="round" />
    </svg>
  );
}
