/**
 * The seek bar (spec §6.1): chapters as segments with 3 px gaps, the played
 * part in mint, the converted part lighter, the knob with its halo, a dot
 * for every word saved in this video, and on hover a preview with the
 * chapter, the time and the Subtitle 1 line spoken there.
 *
 * The playhead moves every frame, so the fills and the knob are written to
 * the DOM from the controller's tick (`transform` and `width` on a few
 * elements, no React render, no layout read); React draws only the shape.
 */
import { useEffect, useMemo, useRef, useState, type KeyboardEvent, type PointerEvent } from 'react';
import { plural, t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { frameUrl } from '@/lib/platform/media.js';
import type { PlayerController } from '../controller.js';
import { activeIndices } from '../model/cues.js';
import { clock, spokenParts } from '../model/time.js';
import { trackIn, usePlayer, type SavedDot } from '../store.js';
import styles from './SeekBar.module.css';

interface Segment {
  start: number;
  end: number;
  title: string | null;
}

/** The chapters as segments over the whole length; one segment when the file has none. */
export function segmentsOf(
  chapters: readonly { start: number; end: number; title: string | null }[],
  duration: number,
): Segment[] {
  const usable = chapters.filter((c) => c.end > c.start && c.start < duration);
  if (usable.length === 0 || duration <= 0) return [{ start: 0, end: Math.max(duration, 1), title: null }];
  return usable.map((c, i) => ({
    start: i === 0 ? 0 : c.start,
    end: i === usable.length - 1 ? duration : Math.min(c.end, duration),
    title: c.title,
  }));
}

/** "26 minutes 58 seconds": what a screen reader says for a time. */
export function spokenTime(seconds: number): string {
  const p = spokenParts(seconds);
  const parts: string[] = [];
  if (p.hours > 0) parts.push(plural(p.hours, 'player.seek.hoursOne', 'player.seek.hours'));
  if (p.minutes > 0 || p.hours > 0)
    parts.push(plural(p.minutes, 'player.seek.minutesOne', 'player.seek.minutes'));
  parts.push(plural(p.seconds, 'player.seek.secondsOne', 'player.seek.seconds'));
  return parts.join(' ');
}

/** The keys a focused seek bar answers (§6.1): 5 s, a minute, the ends. */
export function seekKey(key: string, now: number, duration: number): number | undefined {
  switch (key) {
    case 'ArrowLeft':
      return now - 5;
    case 'ArrowRight':
      return now + 5;
    case 'PageDown':
      return now - 60;
    case 'PageUp':
      return now + 60;
    case 'Home':
      return 0;
    case 'End':
      return duration;
    default:
      return undefined;
  }
}

interface Props {
  controller: PlayerController;
}

export function SeekBar({ controller }: Props): React.JSX.Element {
  const duration = usePlayer((s) => s.duration);
  const chapters = usePlayer((s) => s.chapters);
  const dots = usePlayer((s) => s.dots);
  const segments = useMemo(() => segmentsOf(chapters, duration), [chapters, duration]);
  const trackRef = useRef<HTMLDivElement>(null);
  const knobRef = useRef<HTMLDivElement>(null);
  const playedRefs = useRef<(HTMLDivElement | null)[]>([]);
  const readyRefs = useRef<(HTMLDivElement | null)[]>([]);
  const sliderRef = useRef<HTMLDivElement>(null);
  const [hover, setHover] = useState<number | null>(null);
  const [dragging, setDragging] = useState(false);
  const [now, setNow] = useState(0);
  const lastSecond = useRef(-1);

  // The playhead, every frame: widths and one transform, nothing measured.
  useEffect(() => {
    const paint = (time: number): void => {
      const d = usePlayer.getState().duration;
      if (d <= 0) return;
      const pct = Math.max(0, Math.min(1, time / d));
      if (knobRef.current !== null) knobRef.current.style.left = `${String(pct * 100)}%`;
      segments.forEach((seg, i) => {
        const el = playedRefs.current[i];
        if (el === null || el === undefined) return;
        const w = Math.max(0, Math.min(1, (time - seg.start) / (seg.end - seg.start)));
        el.style.transform = `scaleX(${String(w)})`;
      });
      const second = Math.floor(time);
      if (second !== lastSecond.current) {
        lastSecond.current = second;
        setNow(time);
      }
    };
    return controller.onTick(paint);
  }, [controller, segments]);

  // The converted part: four times a second is plenty.
  useEffect(() => {
    const paint = (): void => {
      const ranges = controller.buffered();
      const buffered = ranges.reduce((m, r) => (r[0] <= controller.time() + 1 ? Math.max(m, r[1]) : m), 0);
      // While the core converts, what it has made so far is the ready part (§6.1, §16).
      const s = usePlayer.getState();
      const converted =
        s.progress !== null && s.playback !== null ? s.progress.readyUntil - s.playback.timeOffset : 0;
      const end = Math.max(buffered, converted);
      segments.forEach((seg, i) => {
        const el = readyRefs.current[i];
        if (el === null || el === undefined) return;
        const w = Math.max(0, Math.min(1, (end - seg.start) / (seg.end - seg.start)));
        el.style.transform = `scaleX(${String(w)})`;
      });
    };
    paint();
    const timer = window.setInterval(paint, 250);
    return () => {
      window.clearInterval(timer);
    };
  }, [controller, segments]);

  const timeAt = (clientX: number): number => {
    const el = trackRef.current;
    if (el === null || duration <= 0) return 0;
    const r = el.getBoundingClientRect();
    return Math.max(0, Math.min(duration, ((clientX - r.left) / r.width) * duration));
  };

  const live = usePlayer((s) => s.playback?.mode === 'direct');
  const onDown = (e: PointerEvent<HTMLDivElement>): void => {
    if (e.button !== 0) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    setDragging(true);
    const at = timeAt(e.clientX);
    setHover(at);
    controller.seek(at);
  };
  const onMove = (e: PointerEvent<HTMLDivElement>): void => {
    const at = timeAt(e.clientX);
    setHover(at);
    // Direct files seek live while scrubbing; streamed ones on release (§6.1).
    if (dragging && live) controller.seek(at);
  };
  const onUp = (e: PointerEvent<HTMLDivElement>): void => {
    if (!dragging) return;
    setDragging(false);
    controller.seek(timeAt(e.clientX));
  };

  const onKey = (e: KeyboardEvent<HTMLDivElement>): void => {
    const to = seekKey(e.key, controller.time(), duration);
    if (to === undefined) return;
    e.preventDefault();
    e.stopPropagation();
    controller.seek(to);
  };

  const chapterAt = (time: number): Segment | undefined =>
    segments.find((s) => time >= s.start && time < s.end);
  const current = chapterAt(now);
  const valueText =
    current?.title !== null && current?.title !== undefined && segments.length > 1
      ? t('player.seek.valueChapter', {
          position: spokenTime(now),
          duration: spokenTime(duration),
          chapter: current.title,
        })
      : t('player.seek.value', { position: spokenTime(now), duration: spokenTime(duration) });

  return (
    <div
      className={cx(styles.seek, (hover !== null || dragging) && styles.hover)}
      onPointerDown={onDown}
      onPointerMove={onMove}
      onPointerUp={onUp}
      onPointerLeave={() => {
        if (!dragging) setHover(null);
      }}
      data-chrome-hold={hover !== null || dragging ? '' : undefined}
    >
      <div
        ref={sliderRef}
        role="slider"
        tabIndex={0}
        aria-label={t('player.ctl.seek')}
        aria-valuemin={0}
        aria-valuemax={Math.round(duration)}
        aria-valuenow={Math.round(now)}
        aria-valuetext={valueText}
        className={styles.slider}
        onKeyDown={onKey}
      >
        <div ref={trackRef} className={styles.track} dir="ltr">
          {segments.map((seg, i) => {
            const hot = hover !== null && hover >= seg.start && hover < seg.end;
            const hoverW =
              hover !== null && hover > now
                ? Math.max(0, Math.min(1, (hover - seg.start) / (seg.end - seg.start)))
                : 0;
            return (
              <div
                key={`${String(seg.start)}-${String(i)}`}
                className={cx(styles.seg, hot && styles.hot)}
                style={{ flexGrow: seg.end - seg.start }}
              >
                <div
                  className={styles.ready}
                  ref={(el) => {
                    readyRefs.current[i] = el;
                  }}
                />
                <div className={styles.hoverFill} style={{ transform: `scaleX(${String(hoverW)})` }} />
                <div
                  className={styles.played}
                  ref={(el) => {
                    playedRefs.current[i] = el;
                  }}
                />
              </div>
            );
          })}
          <Dots dots={dots} duration={duration} controller={controller} />
        </div>
        <div ref={knobRef} className={styles.knob} aria-hidden="true" />
      </div>
      {hover !== null ? (
        <Preview
          time={hover}
          chapter={segments.length > 1 ? chapterAt(hover)?.title : null}
          duration={duration}
        />
      ) : null}
    </div>
  );
}

function Dots({
  dots,
  duration,
  controller,
}: {
  dots: SavedDot[];
  duration: number;
  controller: PlayerController;
}): React.JSX.Element | null {
  if (duration <= 0 || dots.length === 0) return null;
  return (
    <>
      {dots.map((d) => (
        <button
          key={d.id}
          type="button"
          className={styles.dot}
          style={{ left: `${String((d.at / duration) * 100)}%` }}
          aria-label={t('player.seek.savedWord', { word: d.word, time: clock(d.at) })}
          title={t('player.seek.savedWord', { word: d.word, time: clock(d.at) })}
          onPointerDown={(e) => {
            e.stopPropagation();
          }}
          onClick={(e) => {
            e.stopPropagation();
            controller.seek(d.at);
          }}
        />
      ))}
    </>
  );
}

function Preview({
  time,
  chapter,
  duration,
}: {
  time: number;
  chapter: string | null | undefined;
  duration: number;
}): React.JSX.Element {
  const frame = usePlayer((s) =>
    s.prefs.settings.previews && s.engineBase !== null && s.file !== null
      ? frameUrl(s.engineBase, s.file.id, time)
      : null,
  );
  const line = usePlayer((s) => {
    const tr = trackIn(s, 1);
    if (tr === undefined || tr.picture) return '';
    const idx = activeIndices(tr.cues, time * 1000, tr.offsetMs);
    return idx
      .map((i) => tr.cues[i]?.text ?? '')
      .join(' ')
      .replace(/\s+/g, ' ')
      .trim();
  });
  const pct = duration > 0 ? (time / duration) * 100 : 0;
  return (
    <div className={styles.preview} style={{ left: `${String(pct)}%` }} aria-hidden="true">
      {frame !== null ? <img className={styles.frame} src={frame} alt="" draggable={false} /> : null}
      {chapter ? <div className={styles.ch}>{chapter}</div> : null}
      <div className={styles.t}>{clock(time)}</div>
      {line !== '' ? (
        <div className={styles.line} dir="auto">
          {line}
        </div>
      ) : null}
    </div>
  );
}
