/**
 * The word as it is saved from the player: the card's meanings when there
 * are some, the subtitle line as its first example, and "Seen in The Terrace
 * · S1 E3 · 26:58" as the learner's private note. The same shape as the
 * desktop card's and the extension's `compose` (lexpad_desktop
 * `src/lib/compose.ts`), with the video in the note instead of an app.
 */
import type { PlayerCard } from '@/lib/platform/types.js';
import { MAX_MEMO } from './words.js';

export type WordCreate = PlayerCard & { source: string; memo?: string };

export function compose(
  headword: string,
  sentence: string,
  memo: string,
  card: PlayerCard | undefined,
  /** The same moment's line in the notebook's meaning language, from another track. */
  translation?: string,
): WordCreate {
  const base: PlayerCard = card ? { ...card } : { headword, category: 'general' };
  base.headword = headword;
  const meanings = (base.meanings ?? []).map((m) => ({ ...m, examples: [...(m.examples ?? [])] }));
  const line = sentence.trim();
  if (line !== '') {
    const first = meanings[0] ?? { meaning: '', examples: [] };
    const tr = translation?.trim();
    const seen = first.examples.findIndex((e) => e.sentence.trim() === line);
    if (seen < 0)
      first.examples = [{ sentence: line, ...(tr ? { translation: tr } : {}) }, ...first.examples].slice(
        0,
        5,
      );
    else if (tr && !first.examples[seen]?.translation)
      first.examples[seen] = { ...first.examples[seen], sentence: line, translation: tr };
    if (meanings.length === 0) meanings.push(first);
    else meanings[0] = first;
  }
  const kept = meanings.filter((m) => m.meaning.trim() !== '' || m.examples.length > 0);
  const out: WordCreate = { ...base, source: card ? 'ai' : 'manual' };
  delete out.meanings;
  if (kept.length > 0) out.meanings = kept.map((m) => (m.meaning.trim() === '' ? { ...m, meaning: '—' } : m));
  if (memo !== '') out.memo = [...memo].slice(0, MAX_MEMO).join('');
  return out;
}

/** The card's text for an AI report (the desktop card's `reportFragment`, same payload). */
export function reportFragment(headword: string, card: PlayerCard): string {
  const head = [
    card.correction && card.correction !== headword ? card.correction : headword,
    card.pos,
    card.level,
  ]
    .filter((part): part is string => typeof part === 'string' && part !== '')
    .join(' · ');
  const lines = [head];
  for (const [index, sense] of (card.meanings ?? []).slice(0, 3).entries()) {
    lines.push(`${String(index + 1)}. ${sense.meaning}`);
    if (sense.gloss) lines.push(sense.gloss);
    const example = sense.examples?.[0];
    if (example)
      lines.push(
        example.translation ? `“${example.sentence}” — ${example.translation}` : `“${example.sentence}”`,
      );
  }
  const text = [...lines.join('\n')].slice(0, 1500).join('');
  const payload = JSON.stringify({ surface: 'card', snapshot: text, headword });
  let binary = '';
  for (const byte of new TextEncoder().encode(payload)) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
