/**
 * The end of a video (spec §12, mock-up 16): the picture blurred behind, the
 * words saved tonight with "Practise now", the phone card with its QR code
 * to lexpad.app/phone, and for a series the next episode counting down.
 * With no word saved there is no summary, only the next episode (or
 * nothing). The one Pro line in the player lives here, once a day at most,
 * never for Pro, never with nothing saved, and only when it is true for
 * this account (`proLine`).
 */
import { useEffect, useRef, useState } from 'react';
import { plural, t } from '@/i18n/index.js';
import { minutesFor } from '@/lib/cardTime.js';
import { AppleMark } from '@/components/ui/Icon.js';
import type { PlayerController } from '../controller.js';
import { episodeShort, parseTitle } from '../model/title.js';
import { usePlayer } from '../store.js';
import { GooglePlayMark } from './brands.js';
import { PIcon } from './icons.js';
import { QR_MODULES, QR_PATH } from './qrPhone.js';
import styles from './EndSummary.module.css';

interface Props {
  controller: PlayerController;
  /** The Pro line, when this account may see it now; null otherwise. */
  proLine: { onClick: () => void } | null;
  /** The phone card is hidden once the account has signed in on a phone. */
  showPhone: boolean;
}

export function EndSummary({ controller, proLine, showPhone }: Props): React.JSX.Element | null {
  const summary = usePlayer((s) => s.summary);
  const dots = usePlayer((s) => s.dots);
  const title = usePlayer((s) => s.title);
  const next = usePlayer((s) => s.episodes?.next);
  const autoNext = usePlayer((s) => s.prefs.settings.nextEpisode);
  if (!summary) return null;
  const words = dots;
  const ep = title ? episodeShort(title) : undefined;
  const ids = words.map((w) => w.wordId).filter((x): x is string => x !== undefined);
  const close = (): void => {
    controller.hideSummary();
  };
  return (
    <div className={styles.end} data-player-overlay="">
      {next !== undefined && autoNext ? <NextEpisode controller={controller} /> : null}
      {words.length > 0 ? (
        <div className={styles.cards} role="dialog" aria-modal="false" aria-labelledby="end-title">
          <section className={styles.card}>
            <div className={styles.finished}>
              {t('player.end.finished', {
                title: [title?.title, ep].filter((x) => x !== undefined && x !== '').join(' · '),
              })}
            </div>
            <h2 id="end-title" className={styles.count}>
              {plural(words.length, 'player.end.wordsOne', 'player.end.words', { count: words.length })}
            </h2>
            <ul className={styles.list}>
              {words.map((w) => (
                <li key={w.id} className={styles.item}>
                  <span className={styles.word} dir="auto">
                    {w.word}
                  </span>
                  {w.meaning !== undefined ? (
                    <span className={styles.meaning} dir="auto">
                      {w.meaning}
                    </span>
                  ) : null}
                </li>
              ))}
            </ul>
            <div className={styles.actions}>
              {ids.length > 0 ? (
                <button
                  type="button"
                  className={styles.primary}
                  onClick={() => {
                    close();
                    void controller.host.openLexpad(`/session?deck=group&ids=${ids.join(',')}`);
                  }}
                >
                  {t('player.end.practise')}
                  <span className={styles.about}>
                    {plural(
                      minutesFor(ids.length, 1),
                      'player.end.practiseTimeOne',
                      'player.end.practiseTime',
                      { count: minutesFor(ids.length, 1) },
                    )}
                  </span>
                </button>
              ) : null}
              <button
                type="button"
                className={styles.again}
                onClick={() => {
                  close();
                  controller.seek(0);
                  controller.play();
                }}
              >
                {t('player.end.again')}
              </button>
            </div>
            {proLine !== null ? (
              <button type="button" className={styles.pro} onClick={proLine.onClick}>
                <PIcon name="spark" size={18} className={styles.proIcon} />
                <span>{t('player.end.pro')}</span>
                <span className={styles.proCta}>{t('player.end.tryPro')}</span>
              </button>
            ) : null}
          </section>
          {showPhone ? (
            <section className={styles.phone} aria-labelledby="phone-title">
              <h3 id="phone-title" className={styles.phoneTitle}>
                {t('player.end.phoneTitle')}
              </h3>
              <p className={styles.phoneLead}>{t('player.end.phoneLead')}</p>
              <div className={styles.qr} role="img" aria-label={t('player.end.qrLabel')}>
                <svg
                  viewBox={`0 0 ${String(QR_MODULES)} ${String(QR_MODULES)}`}
                  shapeRendering="crispEdges"
                  width="100%"
                  height="100%"
                  aria-hidden="true"
                >
                  <path d={QR_PATH} className={styles.qrInk} />
                </svg>
              </div>
              <p className={styles.scan}>{t('player.end.scan')}</p>
              <div className={styles.stores}>
                <span className={styles.store}>
                  <GooglePlayMark size={16} />
                  {t('player.end.googlePlay')}
                </span>
                <span className={styles.store}>
                  <AppleMark size={16} />
                  {t('player.end.iphone')}
                </span>
              </div>
              <p className={styles.already}>{t('player.end.already')}</p>
            </section>
          ) : null}
          <button type="button" className={styles.dismiss} aria-label={t('player.end.close')} onClick={close}>
            <PIcon name="x" size={18} />
          </button>
        </div>
      ) : null}
    </div>
  );
}

/** "Next episode in 10 s": Space or a click plays it now; the pointer over the card stops the count (§12). */
function NextEpisode({ controller }: { controller: PlayerController }): React.JSX.Element | null {
  const next = usePlayer((s) => s.episodes?.next);
  const delay = usePlayer((s) => s.prefs.settings.nextDelay);
  const [left, setLeft] = useState<number>(delay);
  const [stopped, setStopped] = useState(false);
  const held = useRef(false);
  useEffect(() => {
    if (stopped) return;
    const timer = window.setInterval(() => {
      if (held.current) return;
      setLeft((l) => l - 1);
    }, 1000);
    return () => {
      window.clearInterval(timer);
    };
  }, [stopped]);
  useEffect(() => {
    if (left <= 0 && next !== undefined && !stopped) void controller.openVideo(next);
  }, [left, next, stopped, controller]);
  useEffect(() => {
    const onKey = (e: KeyboardEvent): void => {
      if (e.key === ' ' && next !== undefined) {
        e.preventDefault();
        e.stopPropagation();
        void controller.openVideo(next);
      }
    };
    window.addEventListener('keydown', onKey, true);
    return () => {
      window.removeEventListener('keydown', onKey, true);
    };
  }, [controller, next]);
  if (next === undefined || stopped) return null;
  const tt = parseTitle(next.name);
  const code =
    tt.episode !== undefined
      ? `${tt.season !== undefined ? `S${String(tt.season)} · ` : ''}E${String(tt.episode)}`
      : '';
  const circumference = 2 * Math.PI * 15;
  const frac = Math.max(0, left) / delay;
  return (
    <div
      className={styles.next}
      onPointerEnter={() => {
        held.current = true;
      }}
      onPointerLeave={() => {
        held.current = false;
      }}
    >
      <button
        type="button"
        className={styles.nextPlay}
        onClick={() => void controller.openVideo(next)}
        aria-label={t('player.end.nextNow')}
      >
        <span className={styles.nextThumb} aria-hidden="true">
          <PIcon name="film" size={22} />
        </span>
        <span className={styles.nextText}>
          <span className={styles.nextIn} aria-live="polite">
            {t('player.end.next', { count: Math.max(0, left) })}
          </span>
          <span className={styles.nextName}>
            {code} {tt.episodeTitle ?? tt.title}
          </span>
        </span>
        <svg width="36" height="36" viewBox="0 0 36 36" aria-hidden="true" className={styles.ring}>
          <circle cx="18" cy="18" r="15" className={styles.ringTrack} />
          <circle
            cx="18"
            cy="18"
            r="15"
            className={styles.ringFill}
            strokeDasharray={circumference}
            strokeDashoffset={circumference * (1 - frac)}
            transform="rotate(-90 18 18)"
          />
          <path d="M15 12.5v11l8.5-5.5z" className={styles.ringPlay} />
        </svg>
      </button>
      <button
        type="button"
        className={styles.cancel}
        onClick={() => {
          setStopped(true);
        }}
      >
        {t('player.end.cancel')}
      </button>
    </div>
  );
}
